import { API_BASE, generateMockData } from '../constants';
import { Movie, Episode, HistoryItem, Notification } from '../types';

async function fetchSafe<T>(path: string, defaultValue: T): Promise<T> {
  try {
    const res = await fetch(`${API_BASE}${path}`);
    if (!res.ok) throw new Error('Network response was not ok');
    const text = await res.text();
    try {
      return JSON.parse(text);
    } catch (e) {
      return defaultValue;
    }
  } catch (error) {
    return defaultValue;
  }
}

export const movieService = {
  getAll: async (limit = 10): Promise<{ items: Movie[] }> => {
    // In a real app, you would handle pagination.
    const data = await fetchSafe<any>('/movies?limit=' + limit, { items: [] });
    if (Array.isArray(data)) return { items: data };
    if (data.items) return data;

    // Fallback to mock if API fails (for demo purposes)
    const mock = generateMockData(1, limit, "全部", "全部");
    return { items: mock.items as Movie[] };
  },

  getTop: async (type: string, limit = 15): Promise<Movie[]> => {
    return fetchSafe<Movie[]>(`/movies/top?type=${type}&limit=${limit}`, []);
  },

  search: async (query: string): Promise<Movie[]> => {
    return fetchSafe<Movie[]>(`/movies/search?q=${encodeURIComponent(query)}`, []);
  },

  getRecommendations: async (path: string, id: string | number): Promise<Movie[]> => {
    return fetchSafe<Movie[]>(`/movies/recommend?path=${encodeURIComponent(path)}&id=${id}`, []);
  },

  getEpisodes: async (path: string): Promise<Episode[]> => {
    return fetchSafe<Episode[]>(`/movies/episodes?path=${encodeURIComponent(path)}`, []);
  }
};

export const userService = {
  getHistory: async (): Promise<any[]> => {
    return fetchSafe<any[]>('/user/history', []);
  },

  clearHistory: async (): Promise<void> => {
    try {
      await fetch(`${API_BASE}/user/history`, { method: 'DELETE' });
    } catch (e) {
      console.error(e);
    }
  },

  reportHistory: async (payload: Partial<HistoryItem>) => {
    try {
      await fetch(`${API_BASE}/user/history`, {
