        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(payload)
      });
    } catch (e) {
      console.error(e);
    }
  },

  getVault: async (): Promise<Movie[]> => {
    return fetchSafe<Movie[]>('/user/vault', []);
