  const codecLabel = tech.codec ? String(tech.codec) : '';

  return (
    <div onClick={() => onClick(movie)} className={`relative flex-shrink-0 w-full aspect-[2/3] transition-all duration-300 ease-out cursor-pointer group ${isHovered ? 'scale-105 z-20' : 'scale-100 z-10'}`} onMouseEnter={() => setIsHovered(true)} onMouseLeave={() => setIsHovered(false)}> 
