import React, { useState, useEffect, useMemo } from 'react';
import { ChevronLeft, PlayCircle, Plus, Download, Share2, Star, User, RotateCcw } from 'lucide-react';
import { Movie, PlayOptions } from '../types';
import { movieService } from '../services/api';
import { formatBytes } from '../utils';
import { MovieCard } from '../components/movies/Cards';

interface MovieDetailProps {
  movie: Movie;
  history: any[];
  onBack: () => void;
  onPlay: (options: PlayOptions) => void;
  onMovieSelect: (m: Movie) => void;
  isFavorite: boolean;
  onToggleFavorite: (m: Movie) => void;
}

export const MovieDetail: React.FC<MovieDetailProps> = ({ movie, history, onBack, onPlay, onMovieSelect, isFavorite, onToggleFavorite }) => { 
  const [fullMovieData, setFullMovieData] = useState(movie);
  const [recommendations, setRecommendations] = useState<Movie[]>([]); 

  useEffect(() => {
    setFullMovieData(movie);
  }, [movie]);

  const safeId = String(fullMovieData.id || 'def');
  const hue = parseInt(safeId.split('-').pop() || '0') * 40; 

  const historyItem = useMemo(() => {
    if (!history || !history.length) return null;
    const allItems = history.flatMap(group => group.items || []);
    return allItems.find((item: any) => String(item.id) === String(fullMovieData.id));
  }, [history, fullMovieData]);

  useEffect(() => { 
    window.scrollTo(0, 0); 
    if (fullMovieData && fullMovieData.source_path) { 
        movieService.getRecommendations(fullMovieData.source_path, fullMovieData.id)
            .then(data => setRecommendations(data))
            .catch(err => console.error(err));
    } 
  }, [fullMovieData]); 

  const techSpecs = fullMovieData.tech_specs || {}; 

  return (
    <div className="relative min-h-screen w-full text-white pt-24 pb-12"> 
      <div className="absolute inset-0 bg-[#050505] z-0"> 
          <div className="absolute inset-0 opacity-20" style={{ backgroundImage: `radial-gradient(circle at 70% 20%, hsla(${hue}, 70%, 50%, 0.3), transparent 60%)`, }}></div> 
          <div className="absolute inset-0 bg-[url('https://images.unsplash.com/photo-1535868463750-c78d9543614f?q=80&w=2676&auto=format&fit=crop')] bg-cover bg-center opacity-10 mix-blend-overlay"></div> 
          <div className="absolute inset-0 bg-gradient-to-t from-[#050505] via-[#050505]/80 to-transparent"></div> 
      </div> 

      <div className="container mx-auto px-6 md:px-12 relative z-10"> 
        <button onClick={onBack} className="group flex items-center gap-2 text-gray-400 hover:text-primary mb-8 transition-colors"> <ChevronLeft className="group-hover:-translate-x-1 transition-transform" /> <span className="font-['Rajdhani'] font-bold tracking-wider">RETURN TO GRID</span> </button> 

        <div className="flex flex-col lg:flex-row gap-12 mb-20"> 
            <div className="w-full lg:w-1/3 flex flex-col gap-6"> 
                <div className="aspect-[2/3] w-full bg-[#0a0a12] border border-white/10 relative overflow-hidden group tech-border shadow-[0_0_30px_rgba(0,243,255,0.1)]"> 
                    <div className="absolute inset-0 bg-gradient-to-br from-primary/20 to-secondary/20 opacity-50"></div> 
                    {fullMovieData.cover_url ? (<div className="absolute inset-0 bg-cover bg-center opacity-80" style={{ backgroundImage: `url(${fullMovieData.cover_url})` }}></div>) : (<div className="absolute inset-0 flex flex-col items-center justify-center p-8 text-center border-4 border-double border-white/5 m-2"> <div className="text-6xl mb-4 opacity-20"> {fullMovieData.title.charAt(0)} </div> <h2 className="text-3xl font-['Orbitron'] font-bold text-white/80 glitch-text" data-text={fullMovieData.title}> {fullMovieData.title} </h2> </div>)} 
                    <div className="absolute inset-0 bg-primary mix-blend-overlay opacity-0 group-hover:opacity-20 transition-opacity duration-100"></div> 
                </div> 
                <div className="grid grid-cols-2 gap-4 font-['Rajdhani']"> 
                    <div className="bg-white/5 border border-white/10 p-4 rounded-sm text-center"> <div className="text-xs text-gray-400 uppercase tracking-widest mb-1">Sync Rate</div> <div className="text-2xl font-bold text-primary">98.4%</div> </div> 
                    <div className="bg-white/5 border border-white/10 p-4 rounded-sm text-center"> <div className="text-xs text-gray-400 uppercase tracking-widest mb-1">Rating</div> <div className="text-2xl font-bold text-secondary flex items-center justify-center gap-1"> <Star size={16} fill="var(--color-secondary)" /> {fullMovieData.rating} </div> </div> 
                </div> 
            </div> 

            <div className="flex-1"> 
                <div className="flex items-center gap-4 mb-2"> 
                  {(fullMovieData.tags || [])
                    .filter(tag => !['4K', '1080P', '720P', 'HDR', 'ATMOS'].includes(String(tag).toUpperCase()))
                    .map(tag => (<span key={tag} className="text-primary text-xs font-['Orbitron'] border border-primary/30 px-2 py-1 tracking-widest"> {String(tag)} </span>))} 
                </div> 
                <h1 className="text-5xl md:text-7xl font-black font-['Orbitron'] text-white mb-6 tracking-tighter uppercase leading-tight"> {fullMovieData.title} </h1> 
                <div className="flex flex-wrap items-center gap-6 text-gray-300 font-['Rajdhani'] text-lg mb-8"> <span>{fullMovieData.year}</span> <span className="w-1 h-1 bg-gray-500 rounded-full"></span> <span>{fullMovieData.duration || '120 MIN'}</span> <span className="w-1 h-1 bg-gray-500 rounded-full"></span> <span className="border border-gray-500 px-1 text-sm">R-18</span> <span className="w-1 h-1 bg-gray-500 rounded-full"></span> <span className="text-accent">DIRECTOR: {fullMovieData.director || 'UNKNOWN'}</span> </div> 

                <div className="flex flex-wrap gap-4 mb-10"> 
                    <button onClick={() => onPlay({})} className="flex-1 md:flex-none bg-primary hover:bg-white text-black px-8 py-4 rounded-sm font-['Orbitron'] font-bold flex items-center justify-center gap-3 transition-all hover:shadow-[0_0_20px_var(--color-primary)] text-lg group" > <PlayCircle className="w-6 h-6 fill-black group-hover:fill-black" /> <span>立即播放</span> </button> 
                    {historyItem && historyItem.progress > 0 && (<button onClick={() => onPlay({ startTime: historyItem.progress, filePath: historyItem.source_path })} className="flex-1 md:flex-none bg-[#0a0a12] border border-primary text-primary hover:bg-primary hover:text-black px-8 py-4 rounded-sm font-['Orbitron'] font-bold flex items-center justify-center gap-3 transition-all hover:shadow-[0_0_20px_var(--color-primary)] text-lg group"> <RotateCcw className="w-6 h-6" /> <span>继续观看 ({Math.round((historyItem.progress / historyItem.duration) * 100)}%)</span> </button>)} 
                    <button onClick={() => onToggleFavorite(fullMovieData)} className={`flex-1 md:flex-none bg-transparent border ${isFavorite ? 'border-accent text-accent bg-accent/10' : 'border-white/30 text-white hover:bg-white/10'} px-6 py-4 rounded-sm font-['Orbitron'] font-bold flex items-center justify-center gap-3 transition-all`} > <Plus className={`w-5 h-5 ${isFavorite ? 'rotate-45' : ''} transition-transform`} /> <span>{isFavorite ? '已收藏' : '加入片单'}</span> </button> 
                    <button className="px-4 py-4 border border-white/30 hover:text-primary hover:border-primary transition-all rounded-sm"> <Download className="w-5 h-5" /> </button> <button className="px-4 py-4 border border-white/30 hover:text-secondary hover:border-secondary transition-all rounded-sm"> <Share2 className="w-5 h-5" /> </button> 
                </div> 

                <div className="mb-10 relative"> <h3 className="text-xl font-['Orbitron'] font-bold text-white mb-4 flex items-center gap-2"> <span className="w-1 h-6 bg-red-500"></span> SYNOPSIS </h3> <p className="text-gray-300 text-lg leading-relaxed font-sans opacity-90 max-w-3xl border-l border-white/10 pl-6 py-2"> {fullMovieData.desc || "Data fragment corrupted. No detailed description available in the public archive. Access requires Level 5 clearance."} </p> </div> 

                {fullMovieData.tech_specs && (<div className="mb-10"> <h3 className="text-xl font-['Orbitron'] font-bold text-white mb-4 flex items-center gap-2"> <span className="w-1 h-6 bg-accent"></span> TECH SPECS </h3> <div className="grid grid-cols-2 md:grid-cols-4 gap-4"> <div className="bg-white/5 p-3 border border-white/10"> <div className="text-[10px] text-gray-500 mb-1">RESOLUTION</div> <div className="font-bold text-white font-['Rajdhani']">{String(techSpecs.resolution || 'UNKNOWN')}</div> </div> <div className="bg-white/5 p-3 border border-white/10"> <div className="text-[10px] text-gray-500 mb-1">FILE SIZE</div> <div className="font-bold text-white font-['Rajdhani']">{formatBytes(techSpecs.size)}</div> </div> <div className="bg-white/5 p-3 border border-white/10"> <div className="text-[10px] text-gray-500 mb-1">CODEC</div> <div className="font-bold text-white font-['Rajdhani']">{String(techSpecs.codec || 'UNKNOWN')}</div> </div> <div className="bg-white/5 p-3 border border-white/10"> <div className="text-[10px] text-gray-500 mb-1">AUDIO</div> <div className="font-bold text-white font-['Rajdhani']">{String(techSpecs.audio || 'UNKNOWN')}</div> </div> </div> </div>)} <div className="mb-10"> <h3 className="text-xl font-['Orbitron'] font-bold text-white mb-6 flex items-center gap-2"> <span className="w-1 h-6 bg-secondary"></span> CAST & CREW </h3> <div className="flex gap-6 overflow-x-auto pb-4 no-scrollbar"> {(fullMovieData.cast || ['UNKNOWN', 'UNKNOWN', 'UNKNOWN']).map((actor, i) => (<div key={i} className="flex flex-col items-center gap-3 min-w-[100px]"> <div className="w-20 h-20 rounded-full border-2 border-white/20 bg-[#1a1a24] flex items-center justify-center overflow-hidden hover:border-secondary transition-colors"> <User size={32} className="text-gray-600" /> </div> <span className="text-sm font-['Rajdhani'] font-bold tracking-wider text-gray-300">{actor}</span> </div>))} </div> </div> 
            </div> 
        </div> 

        <div className="border-t border-white/10 pt-10"> <h3 className="text-2xl font-['Orbitron'] font-bold text-white mb-8 flex items-center gap-3"> <div className="w-1 h-8 bg-accent"></div> <span>DATA_CORRELATION</span> <span className="text-accent text-sm border border-accent/30 px-2 py-0.5 tracking-widest">相关推荐</span> </h3> <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-6 gap-4 md:gap-6"> {recommendations.map(rec => (<div key={rec.id} className="transform transition-transform hover:scale-105"> <MovieCard movie={rec} category={{ colorClass: 'border-white/20' }} onClick={onMovieSelect} /> </div>))} </div> </div> 
    </div> 
  </div>); 
};

import React, { useState, useEffect, useRef } from 'react';
import { ChevronLeft, Play, Pause, Volume2, VolumeX, Lock, Maximize, BoxSelect, Scan, Activity } from 'lucide-react';
import { Movie, PlayOptions, Episode } from '../types';
import { movieService, userService } from '../services/api';
import { API_BASE } from '../constants';
import { formatBytes, formatDuration } from '../utils';
import { SciFiProgressRing } from './ui/CyberComponents';

interface PlayerProps {
  movie: Movie;
  onBack: () => void;
  initialOptions: PlayOptions;
}

export const Player: React.FC<PlayerProps> = ({ movie, onBack, initialOptions }) => { 
  const videoRef = useRef<HTMLVideoElement>(null); 
  const audioRef = useRef<HTMLAudioElement>(null);
  const [isPlaying, setIsPlaying] = useState(false); 
  const [currentTime, setCurrentTime] = useState(0); 
  const [duration, setDuration] = useState(0); 
  const [volume, setVolume] = useState(1); 
  const [isLocked, setIsLocked] = useState(false); 
  const [aspectRatio, setAspectRatio] = useState<'contain' | 'cover'>('contain'); 
  const [playbackRate, setPlaybackRate] = useState(1); 
  const [episodeList, setEpisodeList] = useState<Episode[]>([]); 
  const [currentFile, setCurrentFile] = useState<Episode | null>(null); 
  const [loading, setLoading] = useState(true); 
  const [progress, setProgress] = useState(0); 
  const [seekOnLoad, setSeekOnLoad] = useState<number | null>(null); 

  // Sync mode toggle
  const [syncMode, setSyncMode] = useState(false);

  // Auto-detect sync mode need (MKV/REMUX)
  useEffect(() => {
    if (currentFile && currentFile.path) {
      const path = currentFile.path.toLowerCase();
      const isMkv = path.endsWith('.mkv') || path.includes('remux');
      setSyncMode(isMkv);
    }
  }, [currentFile]);

  useEffect(() => { 
    if (!movie || !movie.source_path) return; 
    setLoading(true); 
    movieService.getEpisodes(movie.source_path)
      .then(data => { 
        setEpisodeList(data); 
        let targetFile: Episode | undefined; 
        if (initialOptions?.filePath) { 
          targetFile = data.find(ep => ep.path === initialOptions.filePath); 
        } 
        if (targetFile) { 
          setCurrentFile(targetFile); 
        } else if (data && data.length > 0) { 
          setCurrentFile(data[0]); 
        } else { 
          setCurrentFile({ id: 'main', path: movie.source_path || '', title: movie.title, label: "MOVIE" }); 
        } 
        setLoading(false); 
      })
      .catch(err => { 
        console.error(err); 
        setLoading(false); 
      }); 
  }, [movie, initialOptions]); 

  useEffect(() => { 
    if (initialOptions?.startTime && initialOptions?.filePath === currentFile?.path) { 
      setSeekOnLoad(initialOptions.startTime); 
    } else { 
      setSeekOnLoad(null); 
    } 
  }, [currentFile, initialOptions]); 

  // History Reporting
  useEffect(() => { 
    if (movie.id) { reportHistory(movie, currentFile, 0); } 
    const interval = setInterval(() => { 
      if (isPlaying && videoRef.current) { 
        reportHistory(movie, currentFile, videoRef.current.currentTime, videoRef.current.duration); 
      } 
    }, 10000); 
    return () => clearInterval(interval); 
  }, [movie, currentFile, isPlaying]); 

  const reportHistory = (movie: Movie, file: Episode | null, time: number, duration = 0) => { 
    if (!movie.id || time === 0) return; 
    const targetPath = file?.path || movie.source_path; 
    const payload = { 
        id: movie.id, 
        source_path: targetPath, 
        title: movie.title, 
        cover_url: movie.cover_url, 
        current_time: time, 
        duration: duration 
    }; 
    userService.reportHistory(payload);
  }; 

  // URLs
  const videoUrl = currentFile && currentFile.path ? `${API_BASE}/player/stream?path=${encodeURIComponent(currentFile.path)}` : ""; 
  const audioUrl = currentFile && currentFile.path && syncMode ? `${API_BASE}/player/audio_stream?path=${encodeURIComponent(currentFile.path)}` : "";

  const handleEpisodeChange = (ep: Episode) => { setCurrentFile(ep); setIsPlaying(true); }; 

  // Core Sync Logic
  const togglePlay = async () => { 
    const v = videoRef.current; 
    const a = audioRef.current;
    if (!v) return; 
    try { 
      if (v.paused) { 
        await v.play(); 
        if (syncMode && a) a.play().catch(e => console.warn("Audio pending:", e));
        setIsPlaying(true);
      } else { 
        v.pause(); 
        if (syncMode && a) a.pause();
        setIsPlaying(false);
      } 
    } catch (err) { console.warn("Playback error", err); } 
  }; 

  const onVideoPlay = () => {
      setIsPlaying(true);
      if(syncMode && audioRef.current) audioRef.current.play().catch(() => {});
  };

  const onVideoPause = () => {
      setIsPlaying(false);
      if(syncMode && audioRef.current) audioRef.current.pause();
  };

  const handleTimeUpdate = () => { 
    if (videoRef.current) { 
      const vTime = videoRef.current.currentTime;
      setCurrentTime(vTime); 
      const d = videoRef.current.duration || 0; 
      setDuration(d); 
      setProgress(d > 0 ? (vTime / d) * 100 : 0); 

      // Soft Sync Algorithm
      if (syncMode && audioRef.current && !audioRef.current.paused) {
          const aTime = audioRef.current.currentTime;
          const diff = vTime - aTime;

          if (Math.abs(diff) > 0.15 && Math.abs(diff) < 2) {
             const targetRate = diff > 0 ? 1.05 : 0.95;
             if (audioRef.current.playbackRate !== targetRate) {
                 audioRef.current.playbackRate = targetRate;
             }
          } 
          else if (Math.abs(diff) >= 2) {
             audioRef.current.currentTime = vTime;
          } 
          else {
             if (audioRef.current.playbackRate !== 1) audioRef.current.playbackRate = 1;
          }
      }
    } 
  }; 

  const handleSeek = (e: React.ChangeEvent<HTMLInputElement>) => { 
    const t = parseFloat(e.target.value); 
    if (videoRef.current) { 
        videoRef.current.currentTime = t; 
        setCurrentTime(t); 
        if(syncMode && audioRef.current) audioRef.current.currentTime = t;
    } 
  }; 

  const changePlaybackRate = () => { 
      const rates = [1, 1.5, 2]; 
      const next = rates[(rates.indexOf(playbackRate) + 1) % rates.length]; 
      setPlaybackRate(next); 
      if (videoRef.current) videoRef.current.playbackRate = next; 
      if (audioRef.current) audioRef.current.playbackRate = next;
  }; 

  const toggleAspectRatio = () => setAspectRatio(p => p === 'contain' ? 'cover' : 'contain'); 
  const handleFullscreen = () => { if (videoRef.current) videoRef.current.requestFullscreen().catch(console.warn); }; 

  const handleVideoEnded = () => { 
      if (episodeList.length > 0 && currentFile) { 
          const currentIndex = episodeList.findIndex(ep => ep.id === currentFile.id); 
          if (currentIndex !== -1 && currentIndex < episodeList.length - 1) { 
              const nextEp = episodeList[currentIndex + 1]; setCurrentFile(nextEp); setIsPlaying(true); 
          } 
      } 
  }; 

  const handleLoadedMetadata = () => { if (seekOnLoad !== null && videoRef.current) { videoRef.current.currentTime = seekOnLoad; setSeekOnLoad(null); } }; 

  const handleVolumeChange = (e: React.ChangeEvent<HTMLInputElement>) => {
      const val = parseFloat(e.target.value);
      setVolume(val);
      if (syncMode && audioRef.current) {
          audioRef.current.volume = val;
          if (videoRef.current) videoRef.current.volume = 0;
      } else if (videoRef.current) {
          videoRef.current.volume = val;
      }
  };

  return (
  <div className="fixed inset-0 bg-black z-50 flex flex-col"> 
    <div className={`absolute top-0 left-0 w-full p-4 z-20 bg-gradient-to-b from-black/80 to-transparent flex justify-between items-start transition-opacity duration-300 ${isPlaying && !isLocked ? 'opacity-0 hover:opacity-100' : 'opacity-100'} ${isLocked ? 'opacity-0' : ''}`}> 
        <div className="pointer-events-auto"><button onClick={onBack} className="text-white hover:text-primary bg-black/50 px-4 py-2 rounded border border-white/20 flex items-center gap-2"><ChevronLeft size={16} /> 退出播放</button></div> 
        <div className="text-right pointer-events-auto"><h2 className="text-xl font-['Orbitron'] font-bold text-white text-shadow-neon">{movie.title}</h2>{currentFile && (<div className="text-primary font-['Rajdhani'] text-sm tracking-widest">正在播放: {currentFile.label || "MOVIE"}</div>)}</div> 
    </div> 
    <div className="flex flex-col lg:flex-row h-full"> 
        <div className="flex-grow relative bg-black flex items-center justify-center group"> 
            {loading ? <div className="text-primary animate-pulse font-['Orbitron']">正在建立连接...</div> : (currentFile ? (
            <>
                <video ref={videoRef} src={videoUrl} className={`w-full h-full object-${aspectRatio}`} onTimeUpdate={handleTimeUpdate} onPlay={onVideoPlay} onPause={onVideoPause} onEnded={handleVideoEnded} onLoadedMetadata={handleLoadedMetadata} onClick={!isLocked ? togglePlay : undefined} autoPlay muted={syncMode} />
                {syncMode && <audio ref={audioRef} src={audioUrl} preload="auto" />}

                {syncMode && (
                    <div className="absolute top-20 left-4 pointer-events-none z-30 opacity-70 hover:opacity-100 transition-opacity">
                        <div className="bg-black/80 text-primary text-[10px] px-3 py-1.5 rounded border border-primary/30 flex flex-col gap-1 backdrop-blur-md">
                            <div className="flex items-center gap-2 font-bold">
                                <div className={`w-2 h-2 rounded-full animate-pulse ${audioUrl ? 'bg-green-500' : 'bg-yellow-500'}`}></div>
                                SYNC: DIRECT + TRANSCODE
                            </div>
                            <div className="text-gray-400 text-[9px]">AUDIO CACHE MODE</div>
                        </div>
                    </div>
                )}
            </>
            ) : <div className="text-red-500">未找到资源</div>)} 

            {isLocked && <div className="absolute top-4 right-4 text-red-500 flex items-center gap-2 bg-black/50 px-3 py-1 rounded border border-red-500/50 animate-pulse"><Lock size={16} /> 界面已锁定</div>} 

            {!isLocked && (<div className={`absolute inset-0 flex flex-col justify-end transition-opacity duration-300 ${isPlaying ? 'opacity-0 group-hover:opacity-100' : 'opacity-100'} bg-gradient-to-t from-black/90 via-transparent to-transparent pointer-events-none`}> 
                <div className="w-full px-8 pb-8 pt-12 pointer-events-auto bg-gradient-to-t from-black via-black/90 to-transparent"> 
                    <div className="backdrop-blur-md bg-black/40 border-t border-white/10 p-4 rounded-t-2xl shadow-[0_-10px_40px_rgba(0,0,0,0.5)] relative overflow-hidden"> 
                        <div className="absolute top-0 left-0 w-full h-[1px] bg-gradient-to-r from-transparent via-primary/50 to-transparent"></div> 
                        <div className="flex items-center gap-4 mb-4 w-full"> 
                            <span className="text-white font-['Rajdhani'] font-bold text-sm min-w-[80px] tracking-widest">{formatDuration(currentTime)} <span className="text-gray-600 mx-1">/</span> {formatDuration(duration)}</span> 
                            <div className="w-full group/progress relative h-6 flex items-center cursor-pointer"> 
                                <div className="absolute inset-0 h-1 bg-white/10 top-1/2 -translate-y-1/2 w-full rounded-full overflow-hidden"> 
                                    <div className="w-full h-full bg-[url('data:image/svg+xml;base64,PHN2ZyB4bWxucz0iaHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmciIHdpZHRoPSI0IiBoZWlnaHQ9IjQiPgo8cmVjdCB3aWR0aD0iNCIgaGVpZ2h0PSI0IiBmaWxsPSIjZmZmIiBmaWxsLW9wYWNpdHk9IjAuMDUiLz4KPC9zdmc+')] opacity-50"></div> 
                                </div> 
                                <div className="absolute h-1 top-1/2 -translate-y-1/2 transition-all duration-100 ease-out group-hover/progress:h-2 rounded-l-full" style={{ width: `${progress}%`, background: `linear-gradient(90deg, transparent, var(--color-primary))`, boxShadow: `0 0 15px var(--color-primary), 0 0 5px var(--color-primary)` }}> 
                                    <div className="absolute right-[-8px] top-1/2 -translate-y-1/2 w-6 h-6 flex items-center justify-center transform scale-0 group-hover/progress:scale-125 transition-transform duration-200"> 
                                        <svg width="24" height="24" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg" className="animate-pulse"> <path d="M12 2L21 7V17L12 22L3 17V7L12 2Z" stroke="var(--color-primary)" strokeWidth="2" fill="black" fillOpacity="0.8"/> <circle cx="12" cy="12" r="4" fill="var(--color-primary)" className="animate-[ping_2s_ease-in-out_infinite]" /> </svg> 
                                    </div> 
                                </div> 
                                <input type="range" min="0" max={duration || 100} value={currentTime} onChange={handleSeek} className="absolute inset-0 w-full h-full opacity-0 cursor-pointer z-20" /> 
                            </div> 
                            <div className="ml-2"><SciFiProgressRing progress={progress} size={48} /></div> 
                        </div> 
                        <div className="flex justify-between items-center border-t border-white/10 pt-4"> 
                            <div className="flex items-center gap-6"> 
                                <button onClick={togglePlay} className="text-white hover:text-primary transition-colors transform hover:scale-110 p-2 border border-white/10 hover:border-primary rounded-sm hover:shadow-[0_0_15px_var(--color-primary)] bg-black/50 backdrop-blur-sm"> {isPlaying ? <Pause size={24} fill="white" /> : <Play size={24} fill="white" />} </button> 
                                <div className="relative flex items-center group/vol"> 
                                    <button className="text-white hover:text-primary transition-colors p-2"> {volume === 0 ? <VolumeX size={24} /> : <Volume2 size={24} />} </button> 
                                    <div className="w-0 overflow-hidden group-hover/vol:w-24 transition-all duration-300 ml-2"> 
                                        <input type="range" min="0" max="1" step="0.1" value={volume} onChange={handleVolumeChange} className="w-20 h-1 bg-gray-600 rounded-lg appearance-none cursor-pointer accent-primary" /> 
                                    </div> 
                                </div> 
                            </div> 
                            <div className="flex items-center gap-4"> 
                                <button onClick={() => setIsLocked(true)} className="text-gray-400 hover:text-white hover:rotate-12 transition-transform" title="Lock Controls"><Lock size={20} /></button> 
                                <button onClick={toggleAspectRatio} className="text-gray-400 hover:text-white hover:scale-110 transition-transform" title="Aspect Ratio">{aspectRatio === 'contain' ? <BoxSelect size={20} /> : <Scan size={20} />}</button> 
                                <button onClick={changePlaybackRate} className="text-xs font-['Orbitron'] font-bold text-white hover:text-primary border border-white/20 px-2 py-1 rounded hover:border-primary transition-all hover:shadow-[0_0_10px_var(--color-primary)]">{playbackRate}x</button> 
                                <Maximize size={24} className="text-white hover:text-primary cursor-pointer hover:scale-110 transition-transform" onClick={handleFullscreen} /> 
                            </div> 
                        </div> 
                    </div> 
                </div> 
            </div>)} 

            {isLocked && <button onClick={() => setIsLocked(false)} className="absolute bottom-8 right-8 bg-black/50 p-3 rounded-full border border-red-500 text-red-500 hover:bg-red-500 hover:text-white transition-all z-50 pointer-events-auto"><Lock size={24} /></button>} 
        </div> 

        <div className={`w-full lg:w-80 bg-[#0a0a12]/95 border-l border-white/10 flex flex-col z-20 h-full overflow-hidden transition-transform duration-300 ${isLocked ? 'translate-x-full lg:translate-x-full' : 'translate-x-0'}`}> 
            <div className="p-4 border-b border-white/10"> 
                <div className="flex items-center gap-2 text-xs font-['Orbitron'] text-primary mb-3"><Activity size={14} /> SIGNAL_STATUS: ONLINE</div> 
                <div className="grid grid-cols-2 gap-2"> 
                    <div className="bg-black/40 p-2 border border-white/5"><div className="text-[10px] text-gray-500">BITRATE</div><div className="text-sm font-bold text-white font-['Rajdhani']">15 MB/s</div></div> 
                    <div className="bg-black/40 p-2 border border-white/5"><div className="text-[10px] text-gray-500">CODEC</div><div className="text-sm font-bold text-white font-['Rajdhani']">{String(movie.tech_specs?.codec || "HEVC")}</div></div> 
                    <div className="bg-black/40 p-2 border border-white/5"><div className="text-[10px] text-gray-500">RES</div><div className="text-sm font-bold text-white font-['Rajdhani']">{String(movie.tech_specs?.resolution || "4K")}</div></div> 
