import React, { useState, useEffect } from 'react';
import Navbar, { Footer } from './components/layout/Navbar';
import { Home, Library, Leaderboard, HistoryPage, SearchResults } from './features/Views';
import { ProfilePage } from './features/Profile';
import { MovieDetail } from './features/MovieDetail';
import { Player } from './components/Player';
import { movieService, userService, systemService } from './services/api';
import { THEMES } from './constants';
import { getStyles } from './utils';
import { Movie, ViewState, Notification, PlayOptions, UserSettings } from './types';

const App = () => { 
  const [movies, setMovies] = useState<Movie[]>([]); 
  const [currentView, setCurrentView] = useState<ViewState>('home'); 
  const [libraryInitialType, setLibraryInitialType] = useState("全部类型"); 
  const [selectedMovie, setSelectedMovie] = useState<Movie | null>(null); 
  const [searchResults, setSearchResults] = useState<Movie[]>([]); 
  const [searchQuery, setSearchQuery] = useState(''); 
  const [favorites, setFavorites] = useState<Movie[]>([]); 
  const [history, setHistory] = useState<any[]>([]); 
  const [notifications, setNotifications] = useState<Notification[]>([]); 
  const [settings, setSettings] = useState<UserSettings>({ scanlines: true, glitch: true }); 
  const [themeName, setThemeName] = useState('CYBER'); 
  const currentTheme = THEMES[themeName]; 
  const [playOptions, setPlayOptions] = useState<PlayOptions>({}); 

  // Inject Dynamic Styles (Scanlines, Glitch, CSS Variables)
  useEffect(() => { 
    // We cannot easily inject styles via React state into a global stylesheet in a strictly compliant way without styled-components
    // But we can update CSS Variables on the root.
    const root = document.documentElement; 
    root.style.setProperty('--scanline-opacity', settings.scanlines ? '0.2' : '0'); 
    root.style.setProperty('--glitch-active', settings.glitch ? 'block' : 'none'); 
    root.style.setProperty('--color-primary', currentTheme.primary); 
    root.style.setProperty('--color-secondary', currentTheme.secondary); 
    root.style.setProperty('--color-bg', currentTheme.bg); 
    root.style.setProperty('--color-text', currentTheme.text); 
    root.style.setProperty('--color-accent', currentTheme.accent); 
  }, [settings, currentTheme]); 

  // Initial Data Fetch
  useEffect(() => { 
    const fetchData = async () => { 
      const allMovies = await movieService.getAll(10);
      setMovies(allMovies.items);

      const historyData = await userService.getHistory();
      setHistory(historyData);

      const vaultData = await userService.getVault();
      setFavorites(vaultData);

      const notificationsData = await systemService.getNotifications();
      setNotifications(notificationsData);
    }; 
    fetchData(); 
  }, [currentView]); 

  const handleSearch = async (query: string) => { 
    setSearchQuery(query); 
    setCurrentView('search'); 
    try { 
      const data = await movieService.search(query); 
      setSearchResults(data); 
    } catch (e) { 
      console.error("Search failed", e); 
    } 
  }; 

  const handleToggleFavorite = async (movie: Movie) => { 
    const isFav = favorites.some(f => f.id === movie.id); 
    let newFavs; 
    if (isFav) { 
      newFavs = favorites.filter(f => f.id !== movie.id); 
    } else { 
      newFavs = [...favorites, movie]; 
    } 
    setFavorites(newFavs); 
    await userService.toggleFavorite(movie); 
  }; 

  const handleClearHistory = async () => { 
    await userService.clearHistory();
    setHistory([]); 
  }; 

  const handleNavigate = (view: ViewState) => { 
    if (view === 'library') { 
      setLibraryInitialType("全部类型"); 
    } 
    if (view === 'history') { 
      userService.getHistory().then(setHistory).catch(console.error); 
    } 
    setCurrentView(view); 
  }; 

  const handleViewCategory = (categoryId: string) => { 
    const mapping: Record<string, string> = { 'scifi': '科幻', 'action': '动作', 'romance': '剧情', 'anime': '动画' }; 
    const filterLabel = mapping[categoryId] || "全部类型"; 
    setLibraryInitialType(filterLabel); 
    setCurrentView('library'); 
  }; 

  const handleMovieSelect = (selectedItem: Movie) => {
    let fullMovie = movies.find(m => String(m.id) === String(selectedItem.id));
    if (!fullMovie) {
      fullMovie = movies.find(m => m.title === selectedItem.title);
    }
    // If we still don't have it (e.g. from leaderboard), use selectedItem
    setSelectedMovie(fullMovie || selectedItem);
    setCurrentView('detail');
  };

  return (
    <div className="min-h-screen font-sans selection:bg-secondary selection:text-white relative bg-[#050505] text-white overflow-x-hidden" style={{ backgroundColor: currentTheme.bg }}> 
      <style>{getStyles(settings, currentTheme)}</style> 
      <div className="scanlines"></div> 
      <div className="perspective-grid"></div> 

      {currentView !== 'player' && (
        <Navbar onNavigate={handleNavigate} currentView={currentView} onSearch={handleSearch} onProfile={() => setCurrentView('profile')} notifications={notifications} />
      )} 

      {currentView === 'home' && (<Home movies={movies} onMovieSelect={handleMovieSelect} onViewMore={handleViewCategory} />)} 
      {currentView === 'library' && (<Library movies={movies} onMovieSelect={handleMovieSelect} initialType={libraryInitialType} />)} 
      {currentView === 'leaderboard' && (<Leaderboard onMovieSelect={handleMovieSelect} />)} 
      {currentView === 'history' && (<HistoryPage history={history} onMovieSelect={handleMovieSelect} onClearHistory={handleClearHistory} />)} 
      {currentView === 'profile' && (<ProfilePage settings={settings} setSettings={setSettings} favorites={favorites} onToggleFavorite={handleToggleFavorite} onMovieSelect={handleMovieSelect} currentTheme={themeName} setTheme={setThemeName} />)} 
      {currentView === 'search' && (<SearchResults query={searchQuery} results={searchResults} onMovieSelect={handleMovieSelect} />)} 

      {currentView === 'detail' && selectedMovie && (
        <MovieDetail movie={selectedMovie} history={history} onBack={() => setCurrentView('home')} 
          onPlay={(options = {}) => { setPlayOptions(options); setCurrentView('player'); }} 
          onMovieSelect={handleMovieSelect} 
          isFavorite={favorites.some(f => f.id === selectedMovie.id)} 
          onToggleFavorite={handleToggleFavorite} 
        />
      )} 

      {currentView === 'player' && selectedMovie && (
        <Player movie={selectedMovie} initialOptions={playOptions} onBack={() => setCurrentView('detail')} />
      )} 

      {currentView !== 'player' && <Footer />} 
    </div>
  ); 
}; 

export default App;

