// --- Library Component ---
export const Library = ({ movies, onMovieSelect, initialType = "全部类型" }: { movies: Movie[]; onMovieSelect: (m: Movie) => void; initialType?: string }) => { 
  const [filters, setFilters] = useState({ type: initialType, region: "全部地区", year: "全部年份", sort: "更新时间" }); 
  useEffect(() => { setFilters(prev => ({ ...prev, type: initialType })); }, [initialType]); 

  const REGION_KEYWORDS: Record<string, string[]> = { "美国": ["美国", "USA", "United States", "America", "US"], "日本": ["日本", "Japan", "JP"], "中国": ["中国", "China", "CN", "Hong Kong", "Taiwan", "香港", "台湾"], "英国": ["英国", "UK", "United Kingdom", "Britain"], "韩国": ["韩国", "Korea", "South Korea", "KR"], "其他": ["其他", "Other"] }; 
  const EXCLUDE_RULES: Record<string, string[]> = { "动作": ["动画", "Family", "Animation"], "惊悚": ["动画", "Family"], "犯罪": ["动画", "Family"] }; 

  const displayedMovies = useMemo(() => { 
    if (!movies) return []; 
    let result = [...movies]; 
    if (filters.type !== "全部类型") { 
      result = result.filter(m => { 
        const tags = m.tags || []; 
        const hasType = tags.includes(filters.type) || m.type === filters.type; 
        if (!hasType) return false; 
        if (EXCLUDE_RULES[filters.type]) { 
          const shouldExclude = EXCLUDE_RULES[filters.type].some(excludeTag => tags.includes(excludeTag)); 
          if (shouldExclude) return false; 
        } 
        return true; 
      }); 
    } 
    if (filters.region !== "全部地区") { 
      result = result.filter(m => { 
        const r = (m.region || "").toLowerCase(); 
        const tags = (m.tags || []).map(t => t.toLowerCase()); 
        const keywords = REGION_KEYWORDS[filters.region] || [filters.region]; 
        return keywords.some(k => { 
          const keyword = k.toLowerCase(); 
          return r.includes(keyword) || tags.some(t => t.includes(keyword)); 
        }); 
      }); 
    } 
    if (filters.year !== "全部年份") { 
      if (filters.year === "更早") { result = result.filter(m => m.year < 2020); } 
      else { result = result.filter(m => String(m.year) == filters.year); } 
    } 
    if (filters.sort === "综合评分") { result.sort((a, b) => parseFloat(b.rating) - parseFloat(a.rating)); } 
    else if (filters.sort === "上映年份") { result.sort((a, b) => b.year - a.year); } 
    return result; 
  }, [movies, filters]); 

  return (
    <div className="min-h-screen w-full pt-24 px-4 md:px-12 pb-12"> 
      <div className="flex items-center gap-4 mb-8"> 
        <div className="p-2 border border-primary text-primary shadow-[0_0_10px_var(--color-primary)]"> <Filter className="w-6 h-6" /> </div> 
        <h1 className="text-3xl font-['Orbitron'] font-bold text-white tracking-widest"> DATABASE <span className="text-primary">ARCHIVES</span> </h1> 
        <div className="flex-grow h-[1px] bg-gradient-to-r from-primary/50 to-transparent"></div> 
      </div> 
      <div className="bg-[#0a0a12]/80 border border-white/10 backdrop-blur-md p-6 mb-10 relative overflow-hidden group tech-border"> 
        <div className="absolute top-0 right-0 w-16 h-16 border-t-2 border-r-2 border-red-500/50"></div> 
        <div className="space-y-4 relative z-10"> 
          <div className="flex flex-col md:flex-row md:items-center gap-2 md:gap-4"> 
            <span className="text-primary font-['Noto_Sans_SC'] font-bold py-1 min-w-[4rem] flex items-center gap-2"> <Cpu size={14} /> 类型 </span> 
            <div className="flex flex-wrap gap-2"> {FILTERS.types.map(type => (<FilterTag key={type} label={type} active={filters.type === type} onClick={() => setFilters({ ...filters, type: type })} />))} </div> 
          </div> 
          <div className="h-[1px] bg-white/5 w-full"></div> 
          <div className="flex flex-col md:flex-row md:items-center gap-2 md:gap-4"> 
            <span className="text-secondary font-['Noto_Sans_SC'] font-bold py-1 min-w-[4rem] flex items-center gap-2"> <Globe size={14} /> 地区 </span> 
            <div className="flex flex-wrap gap-2"> {FILTERS.regions.map(region => (<FilterTag key={region} label={region} active={filters.region === region} onClick={() => setFilters({ ...filters, region: region })} />))} </div> 
          </div> 
          <div className="h-[1px] bg-white/5 w-full"></div> 
          <div className="flex flex-col md:flex-row md:items-center gap-2 md:gap-4"> 
            <span className="text-accent font-['Noto_Sans_SC'] font-bold py-1 min-w-[4rem] flex items-center gap-2"> <Calendar size={14} /> 年份 </span> 
            <div className="flex flex-wrap gap-2"> {FILTERS.years.map(year => (<FilterTag key={year} label={year} active={filters.year === year} onClick={() => setFilters({ ...filters, year: year })} />))} </div> 
          </div> 
        </div> 
      </div> 
      <div className="flex flex-col md:flex-row justify-between items-end md:items-center mb-6 font-['Rajdhani'] gap-4"> 
        <div className="text-gray-400 text-sm flex items-center gap-2"> FOUND <span className="text-primary font-bold text-lg">{displayedMovies.length}</span> FILES </div> 
        <div className="flex items-center gap-2 bg-black/40 border border-white/10 px-2 py-1 rounded-sm"> {FILTERS.sorts.map(sort => (<button key={sort.id} onClick={() => setFilters({ ...filters, sort: sort.id })} className={`px-3 py-1 text-sm flex items-center gap-1 hover:text-primary transition-colors relative ${filters.sort === sort.id ? 'text-primary font-bold' : 'text-gray-500'}`} > {sort.label} {filters.sort === sort.id && <div className="absolute bottom-0 left-0 w-full h-[2px] bg-primary shadow-[0_0_5px_var(--color-primary)]"></div>} </button>))} </div> 
      </div> 
      {displayedMovies.length === 0 ? (<div className="h-96 w-full flex flex-col items-center justify-center gap-4 text-gray-600 border border-white/5 bg-black/20"> <AlertTriangle size={48} className="opacity-30" /> <div className="font-['Orbitron'] tracking-widest text-xl">NO DATA FOUND</div> <div className="text-xs font-sans">尝试切换筛选条件</div> </div>) : (<div className="grid grid-cols-2 md:grid-cols-4 lg:grid-cols-5 xl:grid-cols-6 gap-6"> {displayedMovies.map((movie) => (<MovieCard key={movie.id} movie={movie} category={{ colorClass: 'border-white/20' }} onClick={onMovieSelect} />))} </div>)} 
    </div>
  ); 
};

