import React, { useState, useEffect } from 'react';
import Navbar, { Footer } from './components/layout/Navbar';
import { Home, Library, Leaderboard, HistoryPage, SearchResults } from './features/Views';
import { ProfilePage } from './features/Profile';
import { MovieDetail } from './features/MovieDetail';
import { Player } from './components/Player';
import { movieService, userService, systemService } from './services/api';
import { THEMES } from './constants';
import { getStyles } from './utils';
import { Movie, ViewState, Notification, PlayOptions, UserSettings } from './types';

const App = () => { 
  const [movies, setMovies] = useState<Movie[]>([]); 
  const [currentView, setCurrentView] = useState<ViewState>('home'); 
  const [libraryInitialType, setLibraryInitialType] = useState("全部类型"); 
  const [selectedMovie, setSelectedMovie] = useState<Movie | null>(null); 
  const [searchResults, setSearchResults] = useState<Movie[]>([]); 
  const [searchQuery, setSearchQuery] = useState(''); 
  const [favorites, setFavorites] = useState<Movie[]>([]); 
  const [history, setHistory] = useState<any[]>([]); 
  const [notifications, setNotifications] = useState<Notification[]>([]); 
  const [settings, setSettings] = useState<UserSettings>({ scanlines: true, glitch: true }); 
  const [themeName, setThemeName] = useState('CYBER'); 
  const currentTheme = THEMES[themeName]; 
  const [playOptions, setPlayOptions] = useState<PlayOptions>({}); 

  // Inject Dynamic Styles (Scanlines, Glitch, CSS Variables)
  useEffect(() => { 
    // We cannot easily inject styles via React state into a global stylesheet in a strictly compliant way without styled-components
    // But we can update CSS Variables on the root.
    const root = document.documentElement; 
    root.style.setProperty('--scanline-opacity', settings.scanlines ? '0.2' : '0'); 
    root.style.setProperty('--glitch-active', settings.glitch ? 'block' : 'none'); 
    root.style.setProperty('--color-primary', currentTheme.primary); 
    root.style.setProperty('--color-secondary', currentTheme.secondary); 
    root.style.setProperty('--color-bg', currentTheme.bg); 
    root.style.setProperty('--color-text', currentTheme.text); 
    root.style.setProperty('--color-accent', currentTheme.accent); 
  }, [settings, currentTheme]); 

  // Initial Data Fetch
  useEffect(() => { 
    const fetchData = async () => { 
      // Fetch small batch for initial view (Banner etc), Home will fetch its own categories
      const allMovies = await movieService.getAll(20);
      setMovies(allMovies.items);

      const historyData = await userService.getHistory();
      setHistory(historyData);

      const vaultData = await userService.getVault();
      setFavorites(vaultData);

      const notificationsData = await systemService.getNotifications();
      setNotifications(notificationsData);
    }; 
    fetchData(); 
  }, [currentView]); 

  const handleSearch = async (query: string) => { 
    setSearchQuery(query); 
    setCurrentView('search'); 
    try { 
      const data = await movieService.search(query); 
      setSearchResults(data); 
    } catch (e) { 
      console.error("Search failed", e); 
    } 
  }; 

  const handleToggleFavorite = async (movie: Movie) => { 
    const isFav = favorites.some(f => f.id === movie.id); 
    let newFavs; 
    if (isFav) { 
      newFavs = favorites.filter(f => f.id !== movie.id); 
    } else { 
      newFavs = [...favorites, movie]; 
    } 
    setFavorites(newFavs); 
    await userService.toggleFavorite(movie); 
  }; 

  const handleClearHistory = async () => { 
    await userService.clearHistory();
    setHistory([]); 
  }; 

  const handleNavigate = (view: ViewState) => { 
    if (view === 'library') { 
      setLibraryInitialType("全部类型"); 
    } 
    if (view === 'history') { 
      userService.getHistory().then(setHistory).catch(console.error); 
    } 
    setCurrentView(view); 
  }; 

  const handleViewCategory = (categoryId: string) => { 
    const mapping: Record<string, string> = { 'scifi': '科幻', 'action': '动作', 'romance': '剧情', 'anime': '动画' }; 
    const filterLabel = mapping[categoryId] || "全部类型"; 
    setLibraryInitialType(filterLabel); 
    setCurrentView('library'); 
  }; 

  const handleMovieSelect = (selectedItem: Movie) => {
    let fullMovie = movies.find(m => String(m.id) === String(selectedItem.id));
    if (!fullMovie) {
      fullMovie = movies.find(m => m.title === selectedItem.title);
    }
    // If we still don't have it (e.g. from leaderboard), use selectedItem
    setSelectedMovie(fullMovie || selectedItem);
    setCurrentView('detail');
  };

  return (
    <div className="min-h-screen font-sans selection:bg-secondary selection:text-white relative bg-[#050505] text-white overflow-x-hidden" style={{ backgroundColor: currentTheme.bg }}> 
      <style>{getStyles(settings, currentTheme)}</style> 
      <div className="scanlines"></div> 
      <div className="perspective-grid"></div> 

      {currentView !== 'player' && (
        <Navbar onNavigate={handleNavigate} currentView={currentView} onSearch={handleSearch} onProfile={() => setCurrentView('profile')} notifications={notifications} />
      )} 

      {currentView === 'home' && (<Home movies={movies} onMovieSelect={handleMovieSelect} onViewMore={handleViewCategory} />)} 
      {currentView === 'library' && (<Library onMovieSelect={handleMovieSelect} initialType={libraryInitialType} />)} 
      {currentView === 'leaderboard' && (<Leaderboard onMovieSelect={handleMovieSelect} />)} 
      {currentView === 'history' && (<HistoryPage history={history} onMovieSelect={handleMovieSelect} onClearHistory={handleClearHistory} />)} 
      {currentView === 'profile' && (<ProfilePage settings={settings} setSettings={setSettings} favorites={favorites} onToggleFavorite={handleToggleFavorite} onMovieSelect={handleMovieSelect} currentTheme={themeName} setTheme={setThemeName} />)} 
      {currentView === 'search' && (<SearchResults query={searchQuery} results={searchResults} onMovieSelect={handleMovieSelect} />)} 

      {currentView === 'detail' && selectedMovie && (
        <MovieDetail movie={selectedMovie} history={history} onBack={() => setCurrentView('home')} 
          onPlay={(options = {}) => { setPlayOptions(options); setCurrentView('player'); }} 
          onMovieSelect={handleMovieSelect} 
          isFavorite={favorites.some(f => f.id === selectedMovie.id)} 
          onToggleFavorite={handleToggleFavorite} 
        />
      )} 

      {currentView === 'player' && selectedMovie && (
        <Player movie={selectedMovie} initialOptions={playOptions} onBack={() => setCurrentView('detail')} />
      )} 

      {currentView !== 'player' && <Footer />} 
    </div>
  ); 
}; 

export default App;

import React, { useRef, useState, useEffect } from 'react';
import { Cpu, Zap, Heart, Monitor, ChevronRight, Play } from 'lucide-react';
import { MovieCard } from '../components/movies/Cards';
import { Movie, Category } from '../types';
import { FEATURED_MOVIE } from '../constants';
import { movieService } from '../services/api';

const categories: Category[] = [
  { id: 'scifi', title: '科幻 / SCI-FI', icon: <Cpu className="w-5 h-5" />, colorClass: 'border-primary text-primary', bgClass: 'bg-primary/10', keywords: ['SCI-FI', '科幻', 'Science Fiction'] }, 
  { id: 'action', title: '动作 / ACTION', icon: <Zap className="w-5 h-5" />, colorClass: 'border-red-500 text-red-500', bgClass: 'bg-red-500/10', keywords: ['ACTION', '动作', 'Adventure', '冒险'] }, 
  { id: 'romance', title: '剧情 / DRAMA', icon: <Heart className="w-5 h-5" />, colorClass: 'border-secondary text-secondary', bgClass: 'bg-secondary/10', keywords: ['ROMANCE', '剧情', 'Drama', 'Love', '爱情'] }, 
  { id: 'anime', title: '动漫 / ANIME', icon: <Monitor className="w-5 h-5" />, colorClass: 'border-accent text-accent', bgClass: 'bg-accent/10', keywords: ['ANIME', '动画', 'Animation'] }
];

const CategoryRow: React.FC<{ category: Category; data: Movie[]; onMovieSelect: (m: Movie) => void; onViewMore: (id: string) => void }> = ({ category, data, onMovieSelect, onViewMore }) => { 
  const scrollRef = useRef<HTMLDivElement>(null); 
  const scroll = (direction: 'left' | 'right') => { 
    if (scrollRef.current) { 
      const { current } = scrollRef; 
      const scrollAmount = direction === 'left' ? -500 : 500; 
      current.scrollBy({ left: scrollAmount, behavior: 'smooth' }); 
    } 
  }; 
  const moviesToRender = Array.isArray(data) ? data : []; 
  if (moviesToRender.length === 0) return null; 
  return (
    <div className="mb-12 relative z-10 px-4 md:px-12 group"> 
      <div className="flex items-center justify-between mb-4 border-b border-white/10 pb-2"> 
        <div className="flex items-center gap-3"> 
          <div className={`p-1 border rounded-sm shadow-[0_0_10px_currentColor] ${category.colorClass}`}>{category.icon}</div> 
          <h2 className={`text-2xl font-['Orbitron'] font-bold tracking-wider text-white uppercase hover:text-primary transition-all duration-300`}>{category.title}</h2> 
        </div> 
        <button onClick={() => onViewMore(category.id)} className="flex items-center gap-1 text-sm font-['Rajdhani'] font-bold text-gray-500 hover:text-primary transition-colors tracking-widest group/btn">VIEW_ALL <ChevronRight size={14} className="group-hover/btn:translate-x-1 transition-transform" /></button> 
      </div> 
      <div className="relative w-full hidden md:block h-[1px] bg-gradient-to-r from-white/20 to-transparent mb-4"></div> 
      <button onClick={() => scroll('left')} className="absolute left-0 top-1/2 -translate-y-1/2 z-30 h-full w-16 bg-gradient-to-r from-black to-transparent opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-start pl-2 text-white hover:text-primary"><div className="bg-black/50 p-2 border border-white/20 backdrop-blur-sm hover:border-primary">&lt;</div></button> 
      <button onClick={() => scroll('right')} className="absolute right-0 top-1/2 -translate-y-1/2 z-30 h-full w-16 bg-gradient-to-l from-black to-transparent opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-end pr-2 text-white hover:text-primary"><div className="bg-black/50 p-2 border border-white/20 backdrop-blur-sm hover:border-primary">&gt;</div></button> 
      <div ref={scrollRef} className="flex gap-4 overflow-x-auto no-scrollbar pb-8 pt-4 pl-2" style={{ scrollSnapType: 'x mandatory' }}> 
        {moviesToRender.map((movie) => (<div key={movie.id} className="w-40 md:w-56 flex-shrink-0"><MovieCard movie={movie} category={{ colorClass: category.colorClass }} onClick={onMovieSelect} /></div>))} 
      </div> 
    </div>
  ); 
};

export const Home = ({ movies, onMovieSelect, onViewMore }: { movies: Movie[]; onMovieSelect: (m: Movie) => void; onViewMore: (id: string) => void }) => { 
  const featured = (movies && movies.length > 0) ? movies[0] : FEATURED_MOVIE; 
  const [categoryMovies, setCategoryMovies] = useState<Record<string, Movie[]>>({});

  useEffect(() => {
    const fetchCategoryData = async () => {
      const promises = categories.map(async (cat) => {
          let queryGenre = '剧情'; // Default
          if (cat.id === 'scifi') queryGenre = '科幻';
          else if (cat.id === 'action') queryGenre = '动作';
          else if (cat.id === 'romance') queryGenre = '剧情';
          else if (cat.id === 'anime') queryGenre = '动画';

          try {
            const res = await movieService.getAll(10, 1, queryGenre);
            return { id: cat.id, items: res.items };
          } catch (e) {
            console.error(`Failed to fetch genre ${queryGenre}`, e);
            return { id: cat.id, items: [] };
          }
      });

      const results = await Promise.all(promises);
      const newMap: Record<string, Movie[]> = {};
      results.forEach(r => {
          if (r.items && r.items.length > 0) {
            newMap[r.id] = r.items;
          }
      });
      setCategoryMovies(newMap);
    };
    fetchCategoryData();
  }, []);

  return (
    <> 
      <div className="relative w-full h-[85vh] overflow-hidden flex items-center z-10"> 
        <div className="absolute inset-0 bg-[#0a0a12]"><div className="absolute inset-0 bg-[url('https://images.unsplash.com/photo-1535868463750-c78d9543614f?q=80&w=2676&auto=format&fit=crop')] bg-cover bg-center opacity-40 mix-blend-luminosity"></div><div className="absolute inset-0 bg-gradient-to-t from-[#050505] via-[#050505]/80 to-transparent"></div></div> 
        <div className="container mx-auto px-6 md:px-12 relative mt-20"> 
          <h1 className="text-6xl md:text-8xl font-black font-['Orbitron'] text-white mb-4 tracking-tighter glitch-text" data-text={featured.title || "CYBERSTREAM"}>{featured.title || "CYBERSTREAM"}</h1> 
          <p className="max-w-xl text-gray-300 text-lg mb-10 leading-relaxed font-sans border-l-2 border-primary pl-4">{featured.desc || "Connect. Stream. Transcend."}</p> 
          <button onClick={() => onMovieSelect(featured)} className="bg-white hover:bg-primary text-black px-8 py-3 rounded-sm font-['Orbitron'] font-bold flex items-center gap-2 transition-all hover:scale-105"><Play className="w-5 h-5 fill-black" /><span>START_SYSTEM</span></button> 
        </div> 
      </div> 
      <div className="relative -mt-20 pb-10 space-y-8"> 
        {categories.map(cat => (
          <CategoryRow 
            key={cat.id} 
            category={cat} 
            data={categoryMovies[cat.id] || []} 
            onMovieSelect={onMovieSelect} 
            onViewMore={() => onViewMore(cat.id)} 
          />
        ))} 
      </div> 
    </>
  ); 
};

