import React, { useState, useEffect, useRef } from 'react';
import { ChevronLeft, Play, Pause, Volume2, VolumeX, Lock, Maximize, BoxSelect, Scan, Activity } from 'lucide-react';
import { Movie, PlayOptions, Episode } from '../types';
import { movieService, userService } from '../services/api';
import { formatDuration } from '../utils';
import { SciFiProgressRing } from './ui/CyberComponents';

interface PlayerProps {
  movie: Movie;
  onBack: () => void;
  initialOptions: PlayOptions;
}

export const Player: React.FC<PlayerProps> = ({ movie, onBack, initialOptions }) => { 
  const videoRef = useRef<HTMLVideoElement>(null); 
  const [isPlaying, setIsPlaying] = useState(false); 
  const [currentTime, setCurrentTime] = useState(0); 
  const [duration, setDuration] = useState(0); 
  const [volume, setVolume] = useState(1); 
  const [isLocked, setIsLocked] = useState(false); 
  const [aspectRatio, setAspectRatio] = useState<'contain' | 'cover'>('contain'); 
  const [playbackRate, setPlaybackRate] = useState(1); 
  const [episodeList, setEpisodeList] = useState<Episode[]>([]); 
  const [currentEpisode, setCurrentEpisode] = useState<Episode | null>(null); 
  const [loading, setLoading] = useState(true); 
  const [progress, setProgress] = useState(0); 
  const [seekOnLoad, setSeekOnLoad] = useState<number | null>(null); 

  useEffect(() => { 
    if (!movie) return; 
    setLoading(true); 

    // Convert Movie Resources to Episode List
    // We prefer fetching fresh detail to ensure we have resources
    movieService.getDetail(movie.id).then(fullMovie => {
      const resources = fullMovie?.resources || movie.resources || [];
      const episodes: Episode[] = resources.map((res, index) => ({
        id: index,
        resourceId: res.id,
        path: res.relative_path,
        title: res.filename,
        label: `FILE ${index + 1}`
      }));

      setEpisodeList(episodes);

      let targetEp: Episode | undefined;
      if (initialOptions?.resourceId) {
        targetEp = episodes.find(e => e.resourceId === initialOptions.resourceId);
      }

      if (targetEp) {
        setCurrentEpisode(targetEp);
      } else if (episodes.length > 0) {
        setCurrentEpisode(episodes[0]);
      }
      setLoading(false);
    });

  }, [movie, initialOptions]); 

  useEffect(() => { 
    if (initialOptions?.startTime) { 
      setSeekOnLoad(initialOptions.startTime); 
    } 
  }, [initialOptions]); 

  // History Reporting
  useEffect(() => { 
    const interval = setInterval(() => { 
      if (isPlaying && videoRef.current && currentEpisode?.resourceId) { 
        const dur = videoRef.current.duration;
        // Ensure duration is a finite number, otherwise send 0
        const safeDuration = (Number.isFinite(dur) && !isNaN(dur)) ? dur : 0;
        userService.reportHistory(currentEpisode.resourceId, videoRef.current.currentTime, safeDuration); 
      } 
    }, 10000); 
    return () => clearInterval(interval); 
  }, [currentEpisode, isPlaying]); 

  // URL
  const videoUrl = currentEpisode?.resourceId ? movieService.getStreamUrl(currentEpisode.resourceId) : ""; 

  const handleEpisodeChange = (ep: Episode) => { setCurrentEpisode(ep); setIsPlaying(true); }; 

  const togglePlay = async () => { 
    const v = videoRef.current; 
    if (!v) return; 
    try { 
      if (v.paused) { 
        await v.play(); 
        setIsPlaying(true);
      } else { 
        v.pause(); 
        setIsPlaying(false);
      } 
    } catch (err) { console.warn("Playback error", err); } 
  }; 

  const onVideoPlay = () => setIsPlaying(true);
  const onVideoPause = () => setIsPlaying(false);

  const handleTimeUpdate = () => { 
    if (videoRef.current) { 
      const vTime = videoRef.current.currentTime;
      setCurrentTime(vTime); 
      const d = videoRef.current.duration || 0; 
      setDuration(d); 
      setProgress(d > 0 ? (vTime / d) * 100 : 0); 
    } 
  }; 

  const handleSeek = (e: React.ChangeEvent<HTMLInputElement>) => { 
    const t = parseFloat(e.target.value); 
    if (videoRef.current) { 
        videoRef.current.currentTime = t; 
        setCurrentTime(t); 
    } 
  }; 

  const changePlaybackRate = () => { 
      const rates = [1, 1.5, 2]; 
      const next = rates[(rates.indexOf(playbackRate) + 1) % rates.length]; 
      setPlaybackRate(next); 
      if (videoRef.current) videoRef.current.playbackRate = next; 
  }; 

  const toggleAspectRatio = () => setAspectRatio(p => p === 'contain' ? 'cover' : 'contain'); 
  const handleFullscreen = () => { if (videoRef.current) videoRef.current.requestFullscreen().catch(console.warn); }; 

  const handleVideoEnded = () => { 
      if (episodeList.length > 0 && currentEpisode) { 
          const currentIndex = episodeList.findIndex(ep => ep.resourceId === currentEpisode.resourceId); 
          if (currentIndex !== -1 && currentIndex < episodeList.length - 1) { 
              const nextEp = episodeList[currentIndex + 1]; setCurrentEpisode(nextEp); setIsPlaying(true); 
          } 
      } 
  }; 

  const handleLoadedMetadata = () => { if (seekOnLoad !== null && videoRef.current) { videoRef.current.currentTime = seekOnLoad; setSeekOnLoad(null); } }; 

  const handleVolumeChange = (e: React.ChangeEvent<HTMLInputElement>) => {
      const val = parseFloat(e.target.value);
      setVolume(val);
      if (videoRef.current) {
          videoRef.current.volume = val;
      }
  };

  return (
  <div className="fixed inset-0 bg-black z-50 flex flex-col"> 
    <div className={`absolute top-0 left-0 w-full p-4 z-20 bg-gradient-to-b from-black/80 to-transparent flex justify-between items-start transition-opacity duration-300 ${isPlaying && !isLocked ? 'opacity-0 hover:opacity-100' : 'opacity-100'} ${isLocked ? 'opacity-0' : ''}`}> 
        <div className="pointer-events-auto"><button onClick={onBack} className="text-white hover:text-primary bg-black/50 px-4 py-2 rounded border border-white/20 flex items-center gap-2"><ChevronLeft size={16} /> 退出播放</button></div> 
        <div className="text-right pointer-events-auto"><h2 className="text-xl font-['Orbitron'] font-bold text-white text-shadow-neon">{movie.title}</h2></div> 
    </div> 
    <div className="flex flex-col lg:flex-row h-full"> 
        <div className="flex-grow relative bg-black flex items-center justify-center group"> 
            {loading ? <div className="text-primary animate-pulse font-['Orbitron']">连接中...</div> : (currentEpisode ? (
            <video ref={videoRef} src={videoUrl} className={`w-full h-full object-${aspectRatio}`} onTimeUpdate={handleTimeUpdate} onPlay={onVideoPlay} onPause={onVideoPause} onEnded={handleVideoEnded} onLoadedMetadata={handleLoadedMetadata} onClick={!isLocked ? togglePlay : undefined} autoPlay />
            ) : <div className="text-red-500">资源不可用</div>)} 

            {isLocked && <div className="absolute top-4 right-4 text-red-500 flex items-center gap-2 bg-black/50 px-3 py-1 rounded border border-red-500/50 animate-pulse"><Lock size={16} /> 界面已锁定</div>} 

            {!isLocked && (<div className={`absolute inset-0 flex flex-col justify-end transition-opacity duration-300 ${isPlaying ? 'opacity-0 group-hover:opacity-100' : 'opacity-100'} bg-gradient-to-t from-black/90 via-transparent to-transparent pointer-events-none`}> 
                <div className="w-full px-8 pb-8 pt-12 pointer-events-auto bg-gradient-to-t from-black via-black/90 to-transparent"> 
                    <div className="backdrop-blur-md bg-black/40 border-t border-white/10 p-4 rounded-t-2xl shadow-[0_-10px_40px_rgba(0,0,0,0.5)] relative overflow-hidden"> 
