                               </div>
                            </div>
                            <SciFiProgressRing progress={pct} size={40} />
                         </div>

                         <SciFiProgressBar progress={pct} />
                      </div>
                    </div>
                   );
                })}
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { ChevronLeft, Play, Pause, Volume2, VolumeX, Lock, Maximize, BoxSelect, Scan, Activity } from 'lucide-react';
import { Movie, PlayOptions, Episode } from '../types';
import { movieService, userService } from '../services/api';
import { formatDuration } from '../utils';
import { SciFiProgressRing } from './ui/CyberComponents';

interface PlayerProps {
  movie: Movie;
  onBack: () => void;
  initialOptions: PlayOptions;
}

export const Player: React.FC<PlayerProps> = ({ movie, onBack, initialOptions }) => { 
  const videoRef = useRef<HTMLVideoElement>(null); 
  const [isPlaying, setIsPlaying] = useState(false); 
  const [currentTime, setCurrentTime] = useState(0); 
  const [duration, setDuration] = useState(0); 
  const [volume, setVolume] = useState(1); 
  const [isLocked, setIsLocked] = useState(false); 
  const [aspectRatio, setAspectRatio] = useState<'contain' | 'cover'>('contain'); 
  const [playbackRate, setPlaybackRate] = useState(1); 
  const [episodeList, setEpisodeList] = useState<Episode[]>([]); 
  const [currentEpisode, setCurrentEpisode] = useState<Episode | null>(null); 
  const [loading, setLoading] = useState(true); 
  const [progress, setProgress] = useState(0); 
  const [seekOnLoad, setSeekOnLoad] = useState<number | null>(null); 

  useEffect(() => { 
    if (!movie) return; 
    setLoading(true); 

    // Convert Movie Resources to Episode List
    // We prefer fetching fresh detail to ensure we have resources
    movieService.getDetail(movie.id).then(fullMovie => {
      const resources = fullMovie?.resources || movie.resources || [];
      const episodes: Episode[] = resources.map((res, index) => ({
        id: index,
        resourceId: res.id,
        path: res.relative_path,
        title: res.filename,
        label: `FILE ${index + 1}`
      }));

      setEpisodeList(episodes);

      let targetEp: Episode | undefined;
      if (initialOptions?.resourceId) {
        targetEp = episodes.find(e => e.resourceId === initialOptions.resourceId);
      }

      if (targetEp) {
        setCurrentEpisode(targetEp);
      } else if (episodes.length > 0) {
        setCurrentEpisode(episodes[0]);
      }
      setLoading(false);
    });

  }, [movie, initialOptions]); 

  useEffect(() => { 
    if (initialOptions?.startTime) { 
      setSeekOnLoad(initialOptions.startTime); 
    } 
  }, [initialOptions]); 

  // History Reporting
  useEffect(() => { 
    const reportProgress = () => {
      if (videoRef.current && currentEpisode?.resourceId) { 
        const currentTime = videoRef.current.currentTime;
        const dur = videoRef.current.duration;

        // User Requirement: Only report if playback time > 5 seconds
        // This prevents accidental history entries for misoperations
        if (currentTime > 5) {
          // Ensure duration is a finite number, otherwise send 0
          const safeDuration = (Number.isFinite(dur) && !isNaN(dur)) ? dur : 0;
          userService.reportHistory(currentEpisode.resourceId, currentTime, safeDuration); 
        }
      } 
    };

    let interval: ReturnType<typeof setInterval>;

    if (isPlaying) {
      interval = setInterval(reportProgress, 10000); 
    }

    return () => {
      if (interval) clearInterval(interval);
      // Also report on cleanup (pause, exit, unmount) to catch the latest progress
      // strictly observing the > 5s rule
      reportProgress();
    }; 
  }, [currentEpisode, isPlaying]); 

  // URL
  const videoUrl = currentEpisode?.resourceId ? movieService.getStreamUrl(currentEpisode.resourceId) : ""; 

  const handleEpisodeChange = (ep: Episode) => { setCurrentEpisode(ep); setIsPlaying(true); }; 

  const togglePlay = async () => { 
    const v = videoRef.current; 
    if (!v) return; 
    try { 
      if (v.paused) { 
        await v.play(); 
        setIsPlaying(true);
      } else { 
        v.pause(); 
        setIsPlaying(false);
      } 
    } catch (err) { console.warn("Playback error", err); } 
  }; 

  const onVideoPlay = () => setIsPlaying(true);
  const onVideoPause = () => setIsPlaying(false);

  const handleTimeUpdate = () => { 
    if (videoRef.current) { 
      const vTime = videoRef.current.currentTime;
      setCurrentTime(vTime); 
      const d = videoRef.current.duration || 0; 
      setDuration(d); 
      setProgress(d > 0 ? (vTime / d) * 100 : 0); 
    } 
  }; 

  const handleSeek = (e: React.ChangeEvent<HTMLInputElement>) => { 
    const t = parseFloat(e.target.value); 
    if (videoRef.current) { 
        videoRef.current.currentTime = t; 
        setCurrentTime(t); 
    } 
  }; 

  const changePlaybackRate = () => { 
      const rates = [1, 1.5, 2]; 
      const next = rates[(rates.indexOf(playbackRate) + 1) % rates.length]; 
      setPlaybackRate(next); 
      if (videoRef.current) videoRef.current.playbackRate = next; 
  }; 

  const toggleAspectRatio = () => setAspectRatio(p => p === 'contain' ? 'cover' : 'contain'); 
  const handleFullscreen = () => { if (videoRef.current) videoRef.current.requestFullscreen().catch(console.warn); }; 

  const handleVideoEnded = () => { 
      if (episodeList.length > 0 && currentEpisode) { 
          const currentIndex = episodeList.findIndex(ep => ep.resourceId === currentEpisode.resourceId); 
          if (currentIndex !== -1 && currentIndex < episodeList.length - 1) { 
              const nextEp = episodeList[currentIndex + 1]; setCurrentEpisode(nextEp); setIsPlaying(true); 
          } 
      } 
  }; 

  const handleLoadedMetadata = () => { if (seekOnLoad !== null && videoRef.current) { videoRef.current.currentTime = seekOnLoad; setSeekOnLoad(null); } }; 

  const handleVolumeChange = (e: React.ChangeEvent<HTMLInputElement>) => {
      const val = parseFloat(e.target.value);
      setVolume(val);
      if (videoRef.current) {
          videoRef.current.volume = val;
      }
  };

  return (
  <div className="fixed inset-0 bg-black z-50 flex flex-col"> 
    <div className={`absolute top-0 left-0 w-full p-4 z-20 bg-gradient-to-b from-black/80 to-transparent flex justify-between items-start transition-opacity duration-300 ${isPlaying && !isLocked ? 'opacity-0 hover:opacity-100' : 'opacity-100'} ${isLocked ? 'opacity-0' : ''}`}> 
        <div className="pointer-events-auto"><button onClick={onBack} className="text-white hover:text-primary bg-black/50 px-4 py-2 rounded border border-white/20 flex items-center gap-2"><ChevronLeft size={16} /> 退出播放</button></div> 
        <div className="text-right pointer-events-auto"><h2 className="text-xl font-['Orbitron'] font-bold text-white text-shadow-neon">{movie.title}</h2></div> 
    </div> 
    <div className="flex flex-col lg:flex-row h-full"> 
        <div className="flex-grow relative bg-black flex items-center justify-center group"> 
            {loading ? <div className="text-primary animate-pulse font-['Orbitron']">连接中...</div> : (currentEpisode ? (
            <video ref={videoRef} src={videoUrl} className={`w-full h-full object-${aspectRatio}`} onTimeUpdate={handleTimeUpdate} onPlay={onVideoPlay} onPause={onVideoPause} onEnded={handleVideoEnded} onLoadedMetadata={handleLoadedMetadata} onClick={!isLocked ? togglePlay : undefined} autoPlay />
            ) : <div className="text-red-500">资源不可用</div>)} 

            {isLocked && <div className="absolute top-4 right-4 text-red-500 flex items-center gap-2 bg-black/50 px-3 py-1 rounded border border-red-500/50 animate-pulse"><Lock size={16} /> 界面已锁定</div>} 

            {!isLocked && (<div className={`absolute inset-0 flex flex-col justify-end transition-opacity duration-300 ${isPlaying ? 'opacity-0 group-hover:opacity-100' : 'opacity-100'} bg-gradient-to-t from-black/90 via-transparent to-transparent pointer-events-none`}> 
                <div className="w-full px-8 pb-8 pt-12 pointer-events-auto bg-gradient-to-t from-black via-black/90 to-transparent"> 
                    <div className="backdrop-blur-md bg-black/40 border-t border-white/10 p-4 rounded-t-2xl shadow-[0_-10px_40px_rgba(0,0,0,0.5)] relative overflow-hidden"> 
                        <div className="absolute top-0 left-0 w-full h-[1px] bg-gradient-to-r from-transparent via-primary/50 to-transparent"></div> 
                        <div className="flex items-center gap-4 mb-4 w-full"> 
                            <span className="text-white font-['Rajdhani'] font-bold text-sm min-w-[80px] tracking-widest">{formatDuration(currentTime)} <span className="text-gray-600 mx-1">/</span> {formatDuration(duration)}</span> 
                            <div className="w-full group/progress relative h-6 flex items-center cursor-pointer"> 
                                <div className="absolute inset-0 h-1 bg-white/10 top-1/2 -translate-y-1/2 w-full rounded-full overflow-hidden"> 
                                    <div className="w-full h-full bg-[url('data:image/svg+xml;base64,PHN2ZyB4bWxucz0iaHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmciIHdpZHRoPSI0IiBoZWlnaHQ9IjQiPgo8cmVjdCB3aWR0aD0iNCIgaGVpZ2h0PSI0IiBmaWxsPSIjZmZmIiBmaWxsLW9wYWNpdHk9IjAuMDUiLz4KPC9zdmc+')] opacity-50"></div> 
                                </div> 
                                <div className="absolute h-1 top-1/2 -translate-y-1/2 transition-all duration-100 ease-out group-hover/progress:h-2 rounded-l-full" style={{ width: `${progress}%`, background: `linear-gradient(90deg, transparent, var(--color-primary))`, boxShadow: `0 0 15px var(--color-primary), 0 0 5px var(--color-primary)` }}> 
                                    <div className="absolute right-[-8px] top-1/2 -translate-y-1/2 w-6 h-6 flex items-center justify-center transform scale-0 group-hover/progress:scale-125 transition-transform duration-200"> 
                                        <svg width="24" height="24" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg" className="animate-pulse"> <path d="M12 2L21 7V17L12 22L3 17V7L12 2Z" stroke="var(--color-primary)" strokeWidth="2" fill="black" fillOpacity="0.8"/> <circle cx="12" cy="12" r="4" fill="var(--color-primary)" className="animate-[ping_2s_ease-in-out_infinite]" /> </svg> 
                                    </div> 
                                </div> 
                                <input type="range" min="0" max={duration || 100} value={currentTime} onChange={handleSeek} className="absolute inset-0 w-full h-full opacity-0 cursor-pointer z-20" /> 
                            </div> 
                            <div className="ml-2"><SciFiProgressRing progress={progress} size={48} /></div> 
                        </div> 
                        <div className="flex justify-between items-center border-t border-white/10 pt-4"> 
                            <div className="flex items-center gap-6"> 
                                <button onClick={togglePlay} className="text-white hover:text-primary transition-colors transform hover:scale-110 p-2 border border-white/10 hover:border-primary rounded-sm hover:shadow-[0_0_15px_var(--color-primary)] bg-black/50 backdrop-blur-sm"> {isPlaying ? <Pause size={24} fill="white" /> : <Play size={24} fill="white" />} </button> 
                                <div className="relative flex items-center group/vol"> 
                                    <button className="text-white hover:text-primary transition-colors p-2"> {volume === 0 ? <VolumeX size={24} /> : <Volume2 size={24} />} </button> 
                                    <div className="w-0 overflow-hidden group-hover/vol:w-24 transition-all duration-300 ml-2"> 
                                        <input type="range" min="0" max="1" step="0.1" value={volume} onChange={handleVolumeChange} className="w-20 h-1 bg-gray-600 rounded-lg appearance-none cursor-pointer accent-primary" /> 
                                    </div> 
                                </div> 
                            </div> 
                            <div className="flex items-center gap-4"> 
                                <button onClick={() => setIsLocked(true)} className="text-gray-400 hover:text-white hover:rotate-12 transition-transform" title="Lock Controls"><Lock size={20} /></button> 
                                <button onClick={toggleAspectRatio} className="text-gray-400 hover:text-white hover:scale-110 transition-transform" title="Aspect Ratio">{aspectRatio === 'contain' ? <BoxSelect size={20} /> : <Scan size={20} />}</button> 
                                <button onClick={changePlaybackRate} className="text-xs font-['Orbitron'] font-bold text-white hover:text-primary border border-white/20 px-2 py-1 rounded hover:border-primary transition-all hover:shadow-[0_0_10px_var(--color-primary)]">{playbackRate}x</button> 
                                <Maximize size={24} className="text-white hover:text-primary cursor-pointer hover:scale-110 transition-transform" onClick={handleFullscreen} /> 
                            </div> 
                        </div> 
                    </div> 
                </div> 
            </div>)} 

            {isLocked && <button onClick={() => setIsLocked(false)} className="absolute bottom-8 right-8 bg-black/50 p-3 rounded-full border border-red-500 text-red-500 hover:bg-red-500 hover:text-white transition-all z-50 pointer-events-auto"><Lock size={24} /></button>} 
        </div> 

        <div className={`w-full lg:w-80 bg-[#0a0a12]/95 border-l border-white/10 flex flex-col z-20 h-full overflow-hidden transition-transform duration-300 ${isLocked ? 'translate-x-full lg:translate-x-full' : 'translate-x-0'}`}> 
            <div className="p-4 border-b border-white/10"> 
                <div className="flex items-center gap-2 text-xs font-['Orbitron'] text-primary mb-3"><Activity size={14} /> PLAYLIST</div> 
            </div> 
            <div className="flex-1 flex flex-col overflow-hidden"> 
                <div className="flex-1 overflow-y-auto p-2 custom-scrollbar space-y-1"> 
                    {episodeList.length > 0 ? (episodeList.map((ep) => (<button key={ep.id} onClick={() => handleEpisodeChange(ep)} className={`w-full text-left p-3 border transition-all group relative overflow-hidden ${currentEpisode && currentEpisode.resourceId === ep.resourceId ? 'bg-primary/10 border-primary text-primary' : 'bg-transparent border-white/5 text-gray-400 hover:bg-white/5 hover:border-white/20 hover:text-white'}`}> <div className="flex justify-between items-center relative z-10"><span className="font-['Orbitron'] font-bold text-sm truncate pr-2">{ep.title}</span>{currentEpisode && currentEpisode.resourceId === ep.resourceId && <Activity size={14} className="animate-pulse flex-shrink-0" />}</div> <div className="text-[10px] font-['Rajdhani'] opacity-60 truncate mt-1 relative z-10">{ep.label}</div> </button>))) : (<div className="p-4 text-center text-gray-500 text-xs">NO MEDIA FOUND</div>)} 
                </div> 
            </div> 
        </div> 
    </div> 
  </div>
  ); 
}

import React, { useState, useEffect } from 'react';
import Navbar, { Footer } from './components/layout/Navbar';
import { Home, Library, Leaderboard, HistoryPage, SearchResults } from './features/Views';
import { ProfilePage } from './features/Profile';
import { MovieDetail } from './features/MovieDetail';
import { Player } from './components/Player';
import { movieService, userService, systemService } from './services/api';
import { THEMES } from './constants';
import { getStyles } from './utils';
import { Movie, ViewState, Notification, PlayOptions, UserSettings } from './types';

const App = () => { 
  const [movies, setMovies] = useState<Movie[]>([]); 
  const [currentView, setCurrentView] = useState<ViewState>('home'); 
  const [libraryInitialType, setLibraryInitialType] = useState("全部类型"); 
  const [selectedMovie, setSelectedMovie] = useState<Movie | null>(null); 
  const [searchResults, setSearchResults] = useState<Movie[]>([]); 
  const [searchQuery, setSearchQuery] = useState(''); 
  const [favorites, setFavorites] = useState<Movie[]>([]); 
  const [history, setHistory] = useState<any[]>([]); 
  const [notifications, setNotifications] = useState<Notification[]>([]); 
  const [settings, setSettings] = useState<UserSettings>({ scanlines: true, glitch: true }); 
  const [themeName, setThemeName] = useState('CYBER'); 
  const currentTheme = THEMES[themeName]; 
  const [playOptions, setPlayOptions] = useState<PlayOptions>({}); 

  // Inject Dynamic Styles (Scanlines, Glitch, CSS Variables)
  useEffect(() => { 
    // We cannot easily inject styles via React state into a global stylesheet in a strictly compliant way without styled-components
    // But we can update CSS Variables on the root.
    const root = document.documentElement; 
    root.style.setProperty('--scanline-opacity', settings.scanlines ? '0.2' : '0'); 
    root.style.setProperty('--glitch-active', settings.glitch ? 'block' : 'none'); 
    root.style.setProperty('--color-primary', currentTheme.primary); 
    root.style.setProperty('--color-secondary', currentTheme.secondary); 
    root.style.setProperty('--color-bg', currentTheme.bg); 
    root.style.setProperty('--color-text', currentTheme.text); 
    root.style.setProperty('--color-accent', currentTheme.accent); 
  }, [settings, currentTheme]); 

  // Initial Data Fetch
  useEffect(() => { 
    const fetchData = async () => { 
      // Fetch small batch for initial view (Banner etc), Home will fetch its own categories
      const allMovies = await movieService.getAll(20);
      setMovies(allMovies.items);

      const historyData = await userService.getHistory();
      setHistory(historyData);

      const vaultData = await userService.getVault();
      setFavorites(vaultData);

      const notificationsData = await systemService.getNotifications();
      setNotifications(notificationsData);
    }; 
    fetchData(); 
  }, [currentView]); 

  const handleSearch = async (query: string) => { 
    setSearchQuery(query); 
    setCurrentView('search'); 
    try { 
      const data = await movieService.search(query); 
      setSearchResults(data); 
    } catch (e) { 
      console.error("Search failed", e); 
    } 
  }; 

  const handleToggleFavorite = async (movie: Movie) => { 
    const isFav = favorites.some(f => f.id === movie.id); 
    let newFavs; 
    if (isFav) { 
      newFavs = favorites.filter(f => f.id !== movie.id); 
    } else { 
      newFavs = [...favorites, movie]; 
    } 
    setFavorites(newFavs); 
    await userService.toggleFavorite(movie); 
  }; 

  const handleClearHistory = async () => { 
    await userService.clearHistory();
    setHistory([]); 
  }; 

  const handleDeleteHistoryItem = async (resourceId: string) => {
    await userService.deleteHistoryItem(resourceId);
    setHistory(prev => prev.filter(item => item.resourceId !== resourceId));
  };

  const handleNavigate = (view: ViewState) => { 
    if (view === 'library') { 
      setLibraryInitialType("全部类型"); 
    } 
    if (view === 'history') { 
      userService.getHistory().then(setHistory).catch(console.error); 
    } 
    setCurrentView(view); 
  }; 

  const handleViewCategory = (categoryId: string) => { 
    const mapping: Record<string, string> = { 'scifi': '科幻', 'action': '动作', 'romance': '剧情', 'anime': '动画' }; 
    const filterLabel = mapping[categoryId] || "全部类型"; 
    setLibraryInitialType(filterLabel); 
    setCurrentView('library'); 
  }; 

  const handleMovieSelect = (selectedItem: Movie) => {
    let fullMovie = movies.find(m => String(m.id) === String(selectedItem.id));
    if (!fullMovie) {
      fullMovie = movies.find(m => m.title === selectedItem.title);
    }
    // If we still don't have it (e.g. from leaderboard), use selectedItem
    setSelectedMovie(fullMovie || selectedItem);
    setCurrentView('detail');
  };

  return (
    <div className="min-h-screen font-sans selection:bg-secondary selection:text-white relative bg-[#050505] text-white overflow-x-hidden" style={{ backgroundColor: currentTheme.bg }}> 
      <style>{getStyles(settings, currentTheme)}</style> 
      <div className="scanlines"></div> 
      <div className="perspective-grid"></div> 

      {currentView !== 'player' && (
        <Navbar onNavigate={handleNavigate} currentView={currentView} onSearch={handleSearch} onProfile={() => setCurrentView('profile')} notifications={notifications} />
      )} 

      {currentView === 'home' && (<Home movies={movies} onMovieSelect={handleMovieSelect} onViewMore={handleViewCategory} />)} 
      {currentView === 'library' && (<Library onMovieSelect={handleMovieSelect} initialType={libraryInitialType} />)} 
      {currentView === 'leaderboard' && (<Leaderboard onMovieSelect={handleMovieSelect} />)} 
      {currentView === 'history' && (<HistoryPage history={history} onMovieSelect={handleMovieSelect} onClearHistory={handleClearHistory} onDeleteHistoryItem={handleDeleteHistoryItem} />)} 
      {currentView === 'profile' && (<ProfilePage settings={settings} setSettings={setSettings} favorites={favorites} onToggleFavorite={handleToggleFavorite} onMovieSelect={handleMovieSelect} currentTheme={themeName} setTheme={setThemeName} />)} 
      {currentView === 'search' && (<SearchResults query={searchQuery} results={searchResults} onMovieSelect={handleMovieSelect} />)} 

      {currentView === 'detail' && selectedMovie && (
        <MovieDetail movie={selectedMovie} history={history} onBack={() => setCurrentView('home')} 
          onPlay={(options = {}) => { setPlayOptions(options); setCurrentView('player'); }} 
          onMovieSelect={handleMovieSelect} 
          isFavorite={favorites.some(f => f.id === selectedMovie.id)} 
          onToggleFavorite={handleToggleFavorite} 
        />
      )} 

      {currentView === 'player' && selectedMovie && (
        <Player movie={selectedMovie} initialOptions={playOptions} onBack={() => {
            setCurrentView('detail');
            // Refresh history immediately after playing so Resume button updates
            userService.getHistory().then(setHistory);
        }} />
      )} 

      {currentView !== 'player' && <Footer />} 
    </div>
  ); 
}; 

