                <div className="flex flex-wrap items-center gap-6 text-gray-300 font-['Rajdhani'] text-lg mb-8"> <span>{fullMovieData.year}</span> <span className="w-1 h-1 bg-gray-500 rounded-full"></span> <span>{hasResources ? `${fullMovieData.resources?.length} FILES` : 'NO FILES'}</span> </div> 

                <div className="flex flex-wrap gap-4 mb-10">
                    {/* Resume Button */}
                    {resumeRecord && (
                        <button onClick={handleResume} className="flex-1 md:flex-none px-8 py-4 rounded-sm font-['Orbitron'] font-bold flex flex-col items-center justify-center gap-1 transition-all text-lg group bg-secondary hover:bg-white text-black hover:shadow-[0_0_20px_var(--color-secondary)] relative overflow-hidden">
                           <div className="flex items-center gap-3">
