  "info": {
    "title": "Cyber Media Center API (赛博影视)",
    "description": "## 专业发烧级影视中心后端接口文档\n\n此文档定义了 Cyber Media 的核心 API 交互规范。旨在取代 Plex/Emby，提供高性能、低延迟的媒体管理与流媒体服务。\n\n### 🔗 API 生命周期说明 (x-lifecycle-status)\n我们在每个接口中定义了开发状态，请前端同学注意：\n\n1.  🔴 **pending** (未开发): 接口仅有定义，后端尚未实现，调用会返回 501。\n2.  🟠 **implemented_unverified** (已开发未验证): 代码已合并，但未经完整测试，可能存在 Bug。\n3.  ❌ **failed_verification** (验证失败): 测试发现严重问题，暂时禁止使用。\n4.  ⚠️ **passed_imperfect** (验证通过但格式不规范): 功能可用，但返回字段可能不全或命名不符合规范，后续会变动。\n5.  ✅ **stable** (验证通过): 接口稳定，可放心集成。\n\n### 🛡️ 鉴权说明\n所有非公开接口需在 Header 中携带 `Authorization: Bearer <token>`。",
    "version": "1.9.1-beta",
    "contact": {
      "name": "Cyber Media Core Team",
      "email": "dev@cybermedia.local"
    }
  },
  "servers": [
    {
      "url": "https://alist.gameuniverse.top",
      "description": "生产环境 (Production)"
    },
    {
      "url": "http://localhost:5001",
      "description": "本地开发环境"
    }
  ],
  "paths": {
    "/": {
      "get": {
        "summary": "✅ [验证通过] 健康检查",
        "description": "检查后端服务连通性及数据库连接状态。",
        "operationId": "healthCheck",
        "x-lifecycle-status": "stable",
        "tags": [
          "System"
        ],
        "responses": {
          "200": {
            "description": "服务正常",
            "content": {
              "application/json": {
                "schema": {
                  "$ref": "#/components/schemas/ApiResponse"
                },
                "example": {
                  "code": 200,
                  "msg": "Pong",
                  "data": {
                    "status": "up",
                    "version": "1.9.0"
                  }
                }
              }
            }
          }
        }
      }
    },
    "/api/v1/scan": {
      "get": {
        "summary": "✅ [验证通过] 获取扫描状态",
        "description": "轮询接口，用于获取当前扫描任务的实时进度。",
        "operationId": "getScanStatus",
        "x-lifecycle-status": "stable",
        "tags": [
          "System"
        ],
        "responses": {
          "200": {
            "description": "当前状态",
            "content": {
              "application/json": {
                "schema": {
                  "allOf": [
                    {
                      "$ref": "#/components/schemas/ApiResponse"
                    },
                    {
                      "type": "object",
                      "properties": {
                        "data": {
                          "$ref": "#/components/schemas/ScanStatus"
                        }
                      }
                    }
                  ]
                }
              }
            }
          }
        }
      },
      "post": {
        "summary": "✅ [验证通过] 触发媒体库扫描",
        "description": "异步触发全量或增量扫描。任务 ID 将在响应中返回，用于通过 WebSocket 监听进度。",
        "operationId": "triggerScan",
        "x-lifecycle-status": "stable",
        "tags": [
          "System"
        ],
        "requestBody": {
          "content": {
            "application/json": {
              "schema": {
                "type": "object",
                "properties": {
                  "type": {
                    "type": "string",
                    "enum": [
                      "full",
                      "incremental"
                    ],
                    "default": "incremental"
                  },
                  "target_path": {
                    "type": "string",
                    "description": "指定扫描路径，留空则扫描全库"
                  }
                }
              }
            }
          }
        },
        "responses": {
          "202": {
            "description": "任务已接受",
            "content": {
              "application/json": {
                "schema": {
                  "$ref": "#/components/schemas/ApiResponse"
                }
              }
            }
          },
          "429": {
            "description": "已有扫描任务正在运行"
          }
        }
      }
    },
    "/api/v1/genres": {
      "get": {
        "summary": "🔵 [新增] 获取电影分类列表",
        "description": "获取当前媒体库中所有存在的电影分类（如动作、科幻、爱情），以及每个分类下的影片数量。用于首页分类导航。",
        "operationId": "listGenres",
        "x-lifecycle-status": "stable",
        "tags": [
          "Library"
        ],
        "responses": {
          "200": {
            "description": "分类列表",
            "content": {
              "application/json": {
                "schema": {
                  "allOf": [
                    {
                      "$ref": "#/components/schemas/ApiResponse"
                    },
                    {
                      "type": "object",
                      "properties": {
                        "data": {
                          "type": "array",
                          "items": {
                            "$ref": "#/components/schemas/Genre"
                          }
                        }
                      }
                    }
                  ]
                }
              }
            }
          }
        }
      }
    },
    "/api/v1/movies": {
      "get": {
        "summary": "✅ [验证通过] 获取电影列表 (分页/筛选/排序)",
        "description": "获取电影库数据。支持通过分类筛选、以及多维度排序（评分、年份、添加时间）。",
        "operationId": "listMovies",
        "x-lifecycle-status": "stable",
        "tags": [
          "Library"
        ],
        "parameters": [
          {
            "name": "page",
            "in": "query",
            "schema": {
              "type": "integer",
              "default": 1
            }
          },
          {
            "name": "page_size",
            "in": "query",
            "schema": {
              "type": "integer",
              "default": 20
            }
          },
          {
            "name": "genre",
            "in": "query",
            "description": "分类筛选 (例如 'Action', 'Sci-Fi')。留空则返回所有。",
            "schema": {
              "type": "string"
            }
          },
          {
            "name": "source_id",
            "in": "query",
            "description": "筛选：只显示来自特定存储源的电影",
            "schema": {
              "type": "integer"
            }
          },
          {
            "name": "sort_by",
            "in": "query",
            "description": "排序字段：添加时间(默认)、上映年份、评分、标题",
            "schema": {
              "type": "string",
              "enum": ["date_added", "year", "rating", "title"],
              "default": "date_added"
            }
          },
          {
            "name": "order",
            "in": "query",
            "description": "排序方式：升序、降序",
            "schema": {
              "type": "string",
              "enum": ["asc", "desc"],
              "default": "desc"
            }
          }
        ],
        "responses": {
          "200": {
            "description": "成功返回分页数据",
            "content": {
              "application/json": {
                "schema": {
                  "allOf": [
                    {
                      "$ref": "#/components/schemas/ApiResponse"
                    },
                    {
                      "type": "object",
                      "properties": {
                        "data": {
                          "type": "object",
                          "properties": {
                            "items": {
                              "type": "array",
                              "items": {
                                "$ref": "#/components/schemas/MovieSimple"
                              }
                            },
                            "pagination": {
                              "$ref": "#/components/schemas/PaginationMeta"
                            }
                          }
                        }
                      }
                    }
                  ]
                }
              }
            }
          }
        }
      }
    },
    "/api/v1/movies/{id}": {
      "get": {
        "summary": "🟠 [已开发未验证] 获取电影详情",
        "description": "获取单部电影的完整元数据。**现在会显示该电影在哪些存储源可用**。",
