    "/api/v1/movies/{id}/fix_match": {
      "post": {
        "summary": "🔵 [新增] 手动修正匹配 (Fix Match)",
        "description": "当自动刮削错误时，用户可手动提供 TMDB ID，后端将重新下载元数据并覆盖当前电影信息。这是发烧友必用的修正功能。",
        "operationId": "fixMovieMatch",
        "x-lifecycle-status": "implemented_unverified",
        "tags": [
          "Library"
        ],
        "parameters": [
          {
            "name": "id",
            "in": "path",
            "required": true,
            "description": "电影的唯一 UUID",
            "schema": {
              "type": "string"
            }
          }
        ],
        "requestBody": {
          "required": true,
          "content": {
            "application/json": {
              "schema": {
                "type": "object",
                "required": ["tmdb_id"],
                "properties": {
                  "tmdb_id": {
                    "type": "string",
                    "description": "正确的 TMDB ID (例如 '157336')"
                  }
                }
              }
            }
          }
        },
        "responses": {
          "200": {
            "description": "修正任务已提交",
            "content": {
              "application/json": {
                "schema": {
                  "$ref": "#/components/schemas/ApiResponse"
                }
              }
            }
          }
        }
      }
    },
    "/api/v1/resources/{id}/stream": {
      "get": {
        "summary": "⚠️ [格式不规范] 视频流媒体",
        "description": "直接返回二进制视频流。后端会自动处理不同协议（SMB/WebDAV）的流读取。",
        "operationId": "streamVideo",
        "x-lifecycle-status": "passed_imperfect",
        "tags": [
          "Player"
        ],
        "parameters": [
          {
            "name": "id",
            "in": "path",
            "required": true,
            "schema": {
              "type": "string"
            }
          },
          {
            "name": "container",
            "in": "query",
            "schema": {
              "type": "string",
              "enum": [
                "hls",
                "mp4",
                "direct"
              ]
            }
          }
        ],
        "responses": {
          "200": {
            "description": "视频流",
            "content": {
              "video/mp4": {
                "schema": {
                  "type": "string",
                  "format": "binary"
                }
              }
            }
          },
          "206": {
            "description": "Range 请求部分内容"
          }
        }
      }
    },
