    "/api/v1/user/history": {
      "get": {
        "summary": "❌ [验证失败] 获取观看历史",
        "description": "性能优化中。",
        "operationId": "getHistory",
        "x-lifecycle-status": "failed_verification",
        "tags": [
          "User"
        ],
        "responses": {
          "200": {
            "description": "历史记录",
            "content": {
              "application/json": {
                "schema": {
                  "$ref": "#/components/schemas/ApiResponse"
                }
              }
            }
          }
        }
      },
      "post": {
        "summary": "🟠 [已开发未验证] 上报播放进度",
        "description": "上报播放进度心跳。注意：**前端必须上报 total_duration**，后端不会去计算时长，这能极大减轻后端负载。",
        "operationId": "reportProgress",
        "x-lifecycle-status": "implemented_unverified",
        "tags": [
          "User"
        ],
        "requestBody": {
          "content": {
            "application/json": {
              "schema": {
                "type": "object",
                "required": [
                  "resource_id",
                  "position_sec",
                  "total_duration"
                ],
                "properties": {
                  "resource_id": {
                    "type": "string"
                  },
                  "position_sec": {
                    "type": "integer",
                    "description": "当前播放秒数"
                  },
                  "total_duration": {
                    "type": "integer",
                    "description": "视频总秒数 (必须由播放器提供)"
                  },
                  "device_id": {
                    "type": "string",
                    "description": "设备唯一标识 (UUID)，用于多端续播区分"
                  },
                  "device_name": {
                    "type": "string",
                    "description": "设备名称 (如 'Living Room TV')",
                    "example": "iPad Pro"
                  }
                }
              }
            }
          }
        },
        "responses": {
          "200": {
            "description": "上报成功"
          }
        }
      },
      "delete": {
        "summary": "🔵 [新增] 清空观看历史",
        "description": "清空当前用户的所有观看历史记录。**此操作不可逆，请谨慎使用。**",
