import { Filter, Cpu, Globe, Calendar, AlertTriangle, Loader2, Search } from 'lucide-react';
import { MovieCard } from '../components/movies/Cards';
import { Movie, Genre } from '../types';
import { FILTERS } from '../constants';
import { FilterTag } from '../components/ui/CyberComponents';
import { movieService } from '../services/api';

export const Library = ({ onMovieSelect, initialType = "全部类型" }: { onMovieSelect: (m: Movie) => void; initialType?: string }) => { 
  const [filters, setFilters] = useState({ type: initialType, region: "全部地区", year: "全部年份", sort: "更新时间" }); 
  const [libraryMovies, setLibraryMovies] = useState<Movie[]>([]);
  const [page, setPage] = useState(1);
  const [pageSize, setPageSize] = useState(0);
  const [hasMore, setHasMore] = useState(true);
  const [isLoading, setIsLoading] = useState(false);
  const [genres, setGenres] = useState<Genre[]>([]);
  const observer = useRef<IntersectionObserver | null>(null);

  useEffect(() => { setFilters(prev => ({ ...prev, type: initialType })); }, [initialType]); 

  // Fetch available genres on mount
  useEffect(() => {
    const fetchGenres = async () => {
      try {
        const data = await movieService.getGenres();
        setGenres(data);
      } catch (e) {
        console.error("Failed to fetch genres", e);
      }
    };
    fetchGenres();
  }, []);

  // Calculate dynamic page size to fill screen
  useEffect(() => {
    const calculateSize = () => {
      const width = window.innerWidth;
      const cols = width >= 1280 ? 6 : width >= 1024 ? 5 : width >= 768 ? 4 : 2;
      const padding = width >= 768 ? 96 : 32; 
      const contentWidth = width - padding;
      const cardWidth = contentWidth / cols;
      const cardHeight = cardWidth * 1.5; 
      const rows = Math.ceil(window.innerHeight / cardHeight) + 1;
      const needed = cols * rows;
      setPageSize(Math.max(needed, 20));
    };
    calculateSize();
  }, []);

  // Reset list when server-side filters change (Type, Sort)
  useEffect(() => {
    setPage(1);
    setLibraryMovies([]);
    setHasMore(true);
  }, [filters.type, filters.sort]);

  // Fetch movies with pagination and server-side filtering/sorting
  useEffect(() => {
    if (pageSize === 0) return;

    const fetchMovies = async () => {
      setIsLoading(true);
      try {
        // Determine genre param
        let genreParam: string | undefined = undefined;
        if (filters.type !== "全部类型") {
           const matchedGenre = genres.find(g => g.name === filters.type);
           genreParam = matchedGenre ? matchedGenre.slug : filters.type;
        }

        // Determine sort params
        let sortBy = 'date_added';
        let order = 'desc';
        if (filters.sort === "综合评分") {
           sortBy = 'rating';
        } else if (filters.sort === "上映年份") {
           sortBy = 'year';
        } else if (filters.sort === "标题") {
           sortBy = 'title';
           order = 'asc';
        }

        const res = await movieService.getAll(pageSize, page, genreParam, sortBy, order);
        setLibraryMovies(prev => {
          if (page === 1) return res.items;
          const existingIds = new Set(prev.map(m => m.id));
          const newItems = res.items.filter(m => !existingIds.has(m.id));
          return [...prev, ...newItems];
        });

        if (res.meta) {
          setHasMore(res.meta.current_page < res.meta.total_pages);
        } else {
          setHasMore(res.items.length === pageSize);
        }
      } catch (error) {
        console.error("Failed to fetch library", error);
      } finally {
        setIsLoading(false);
      }
    };
    fetchMovies();
  }, [page, pageSize, filters.type, filters.sort, genres]); 

  // Client-side Filtering for secondary fields (Region, Year)
  const REGION_KEYWORDS: Record<string, string[]> = { "美国": ["美国", "USA", "United States", "America", "US"], "日本": ["日本", "Japan", "JP"], "中国": ["中国", "China", "CN", "Hong Kong", "Taiwan", "香港", "台湾"], "英国": ["英国", "UK", "United Kingdom", "Britain"], "韩国": ["韩国", "Korea", "South Korea", "KR"], "其他": ["其他", "Other"] }; 

  const displayedMovies = useMemo(() => { 
    let result = [...libraryMovies]; 

    if (filters.region !== "全部地区") { 
      result = result.filter(m => { 
        const r = (m.region || "").toLowerCase(); 
        const tags = (m.tags || []).map(t => t.toLowerCase()); 
        const keywords = REGION_KEYWORDS[filters.region] || [filters.region]; 
        return keywords.some(k => { 
          const keyword = k.toLowerCase(); 
          return r.includes(keyword) || tags.some(t => t.includes(keyword)); 
        }); 
      }); 
    } 
    if (filters.year !== "全部年份") { 
      if (filters.year === "更早") { result = result.filter(m => m.year < 2020); } 
      else { result = result.filter(m => String(m.year) == filters.year); } 
    } 
    // Sort is handled server-side now, so we removed client-side sort logic to avoid conflict
    return result; 
  }, [libraryMovies, filters]); 

  // Auto-advance if filtered list is empty but server has more data
  useEffect(() => {
    if (!isLoading && hasMore && displayedMovies.length === 0 && libraryMovies.length > 0) {
       const timer = setTimeout(() => {
         setPage(prev => prev + 1);
       }, 500);
       return () => clearTimeout(timer);
    }
  }, [isLoading, hasMore, displayedMovies.length, libraryMovies.length]);

  // Infinite Scroll Ref
  const lastMovieRef = useCallback((node: HTMLDivElement) => {
    if (isLoading) return;
    if (observer.current) observer.current.disconnect();
    observer.current = new IntersectionObserver(entries => {
      if (entries[0].isIntersecting && hasMore) {
        setPage(prev => prev + 1);
      }
    });
    if (node) observer.current.observe(node);
  }, [isLoading, hasMore]);

  // Merge static and dynamic genres for display
  const displayGenres = ["全部类型", ...genres.map(g => g.name)];
  // Fallback to static if fetch fails/empty, but prioritize fetched ones
  const filterList = genres.length > 0 ? displayGenres : FILTERS.types;

  return (
    <div className="min-h-screen w-full pt-24 px-4 md:px-12 pb-12"> 
      <div className="flex items-center gap-4 mb-8"> 
        <div className="p-2 border border-primary text-primary shadow-[0_0_10px_var(--color-primary)]"> <Filter className="w-6 h-6" /> </div> 
        <h1 className="text-3xl font-['Orbitron'] font-bold text-white tracking-widest"> DATABASE <span className="text-primary">ARCHIVES</span> </h1> 
        <div className="flex-grow h-[1px] bg-gradient-to-r from-primary/50 to-transparent"></div> 
      </div> 
      <div className="bg-[#0a0a12]/80 border border-white/10 backdrop-blur-md p-6 mb-10 relative overflow-hidden group tech-border"> 
        <div className="absolute top-0 right-0 w-16 h-16 border-t-2 border-r-2 border-red-500/50"></div> 
        <div className="space-y-4 relative z-10"> 
          <div className="flex flex-col md:flex-row md:items-center gap-2 md:gap-4"> 
            <span className="text-primary font-['Noto_Sans_SC'] font-bold py-1 min-w-[4rem] flex items-center gap-2"> <Cpu size={14} /> 类型 </span> 
            <div className="flex flex-wrap gap-2"> {filterList.map(type => (<FilterTag key={type} label={type} active={filters.type === type} onClick={() => setFilters({ ...filters, type: type })} />))} </div> 
          </div> 
          <div className="h-[1px] bg-white/5 w-full"></div> 
          <div className="flex flex-col md:flex-row md:items-center gap-2 md:gap-4"> 
            <span className="text-secondary font-['Noto_Sans_SC'] font-bold py-1 min-w-[4rem] flex items-center gap-2"> <Globe size={14} /> 地区 </span> 
            <div className="flex flex-wrap gap-2"> {FILTERS.regions.map(region => (<FilterTag key={region} label={region} active={filters.region === region} onClick={() => setFilters({ ...filters, region: region })} />))} </div> 
          </div> 
          <div className="h-[1px] bg-white/5 w-full"></div> 
          <div className="flex flex-col md:flex-row md:items-center gap-2 md:gap-4"> 
            <span className="text-accent font-['Noto_Sans_SC'] font-bold py-1 min-w-[4rem] flex items-center gap-2"> <Calendar size={14} /> 年份 </span> 
            <div className="flex flex-wrap gap-2"> {FILTERS.years.map(year => (<FilterTag key={year} label={year} active={filters.year === year} onClick={() => setFilters({ ...filters, year: year })} />))} </div> 
          </div> 
        </div> 
      </div> 
      <div className="flex flex-col md:flex-row justify-between items-end md:items-center mb-6 font-['Rajdhani'] gap-4"> 
        <div className="text-gray-400 text-sm flex items-center gap-2"> FOUND <span className="text-primary font-bold text-lg">{displayedMovies.length}</span> FILES {libraryMovies.length > 0 && <span className="text-xs opacity-50">/ SCANNED {libraryMovies.length}</span>}</div> 
        <div className="flex items-center gap-2 bg-black/40 border border-white/10 px-2 py-1 rounded-sm"> {FILTERS.sorts.map(sort => (<button key={sort.id} onClick={() => setFilters({ ...filters, sort: sort.id })} className={`px-3 py-1 text-sm flex items-center gap-1 hover:text-primary transition-colors relative ${filters.sort === sort.id ? 'text-primary font-bold' : 'text-gray-500'}`} > {sort.label} {filters.sort === sort.id && <div className="absolute bottom-0 left-0 w-full h-[2px] bg-primary shadow-[0_0_5px_var(--color-primary)]"></div>} </button>))} </div> 
      </div> 

      <div className="grid grid-cols-2 md:grid-cols-4 lg:grid-cols-5 xl:grid-cols-6 gap-6"> 
        {displayedMovies.map((movie, index) => {
           // Attach ref to the last element of the list
           if (index === displayedMovies.length - 1) {
             return <div key={movie.id} ref={lastMovieRef}><MovieCard movie={movie} category={{ colorClass: 'border-white/20' }} onClick={onMovieSelect} /></div>;
           }
           return <MovieCard key={movie.id} movie={movie} category={{ colorClass: 'border-white/20' }} onClick={onMovieSelect} />;
        })} 
      </div>

      {isLoading && (
        <div className="w-full flex flex-col items-center justify-center py-8 gap-2">
          <Loader2 className="w-8 h-8 text-primary animate-spin" />
          <span className="text-xs font-['Orbitron'] text-primary animate-pulse">SCANNING_ARCHIVES...</span>
        </div>
      )}

      {!isLoading && displayedMovies.length === 0 && !hasMore && (
        <div className="h-96 w-full flex flex-col items-center justify-center gap-4 text-gray-600 border border-white/5 bg-black/20"> 
          <AlertTriangle size={48} className="opacity-30" /> 
          <div className="font-['Orbitron'] tracking-widest text-xl">NO DATA MATCHED</div> 
          <div className="text-xs font-sans">筛选条件未匹配到任何结果</div> 
        </div>
      )}

      {!hasMore && displayedMovies.length > 0 && (
        <div className="w-full text-center py-8 text-gray-600 font-['Rajdhani'] text-xs tracking-widest">END OF ARCHIVE</div>
      )}
    </div>
  ); 
};

import React, { useMemo, useState } from 'react';
import { Brain, Trash2, Layers, Clock, Activity, Database, Film, Play, X, AlertTriangle } from 'lucide-react';
import { Movie, HistoryItem } from '../types';
import { CyberSword, SciFiProgressRing, SciFiProgressBar } from '../components/ui/CyberComponents';
import { formatDuration } from '../utils';

export const HistoryPage = ({ history, onMovieSelect, onClearHistory, onDeleteHistoryItem }: { history: HistoryItem[]; onMovieSelect: (m: Movie) => void; onClearHistory: () => void; onDeleteHistoryItem: (id: string) => void }) => {
  const [confirmClear, setConfirmClear] = useState(false);

  // Group history items by date
  const groupedHistory = useMemo(() => {
    if (!history || !Array.isArray(history)) return [];

    const groups: Record<string, HistoryItem[]> = {};
    history.forEach(item => {
      // Use date string as key, default to "Recent" if missing
      const dateKey = item.date || "RECENT";
      if (!groups[dateKey]) {
        groups[dateKey] = [];
      }
      groups[dateKey].push(item);
    });

    return Object.entries(groups).map(([date, items]) => ({ date, items }));
  }, [history]);

  // Calculate stats
  const totalItems = history ? history.length : 0;
  let totalDuration = 0;
  let totalProgress = 0;

  if (history && Array.isArray(history)) {
    history.forEach((item) => {
      totalDuration += (item.duration || 0);
      totalProgress += (item.progress || 0);
    });
  }

  const completionRate = totalDuration > 0 ? Math.round((totalProgress / totalDuration) * 100) : 0;

  return (
    <div className="min-h-screen w-full pt-24 px-4 md:px-12 pb-12">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-end gap-6 mb-12 border-b border-white/10 pb-6">
        <div>
          <div className="flex items-center gap-3 mb-2">
            <Brain className="text-primary" size={24} />
            <h2 className="text-sm font-['Orbitron'] text-primary tracking-[0.2em]">NEURAL_ARCHIVE</h2>
          </div>
          <h1 className="text-4xl font-['Noto_Sans_SC'] font-bold text-white glitch-text" data-text="观看记录">观看记录</h1>
        </div>

        {confirmClear ? (
          <div className="flex items-center gap-2 animate-in slide-in-from-right-4">
             <span className="text-xs text-red-500 font-bold font-['Orbitron'] flex items-center gap-1"><AlertTriangle size={14} /> CONFIRM DELETE ALL?</span>
             <button onClick={() => { onClearHistory(); setConfirmClear(false); }} className="px-4 py-2 bg-red-500 text-black font-bold text-xs hover:bg-white transition-colors">YES, WIPE</button>
             <button onClick={() => setConfirmClear(false)} className="px-4 py-2 border border-white/20 text-gray-400 font-bold text-xs hover:text-white transition-colors">CANCEL</button>
          </div>
        ) : (
          <button onClick={() => setConfirmClear(true)} className="flex items-center gap-2 px-4 py-2 border border-red-500/50 text-red-500 hover:bg-red-500 hover:text-black transition-all font-['Orbitron'] text-xs font-bold">
            <Trash2 size={14} /> WIPE_MEMORY
          </button>
        )}
      </div>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-6 mb-12">
        <div className="bg-[#0a0a12]/60 border border-white/10 p-6 relative overflow-hidden group hover:border-primary/50 transition-colors">
          <div className="absolute top-0 right-0 p-4 text-primary group-hover:opacity-100 transition-all duration-500 drop-shadow-[0_0_10px_var(--color-primary)] animate-pulse"><Layers size={48} /></div>
          <div className="text-xs text-primary font-['Orbitron'] mb-2">TOTAL_ARCHIVES</div>
          <div className="text-3xl font-['Rajdhani'] font-bold text-white group-hover:text-primary transition-colors">{totalItems} <span className="text-sm text-gray-500">FILES</span></div>
        </div>
        <div className="bg-[#0a0a12]/60 border border-white/10 p-6 relative overflow-hidden group hover:border-secondary/50 transition-colors">
          <div className="absolute top-0 right-0 p-4 text-secondary group-hover:opacity-100 transition-all duration-500 drop-shadow-[0_0_10px_var(--color-secondary)] animate-pulse"><Clock size={48} /></div>
          <div className="text-xs text-secondary font-['Orbitron'] mb-2">SYNC_DURATION</div>
          <div className="text-3xl font-['Rajdhani'] font-bold text-white group-hover:text-secondary transition-colors">{formatDuration(totalProgress)}</div>
        </div>
        <div className="bg-[#0a0a12]/60 border border-white/10 p-6 relative overflow-hidden group hover:border-accent/50 transition-colors">
          <div className="absolute top-0 right-0 p-4 text-accent group-hover:opacity-100 transition-all duration-500 drop-shadow-[0_0_10px_var(--color-accent)] animate-pulse"><Activity size={48} /></div>
          <div className="text-xs text-accent font-['Orbitron'] mb-2">SYNC_RATE</div>
          <div className="text-3xl font-['Rajdhani'] font-bold text-white group-hover:text-accent transition-colors">{completionRate}%</div>
          <div className="w-full h-1 bg-gray-800 mt-2 rounded-full overflow-hidden">
             <div className="h-full bg-accent" style={{ width: `${completionRate}%` }}></div>
          </div>
        </div>
      </div>

      <div className="mb-12 hidden md:block">
         <CyberSword />
      </div>

      {groupedHistory.length === 0 ? (
        <div className="flex flex-col items-center justify-center h-64 text-gray-500">
          <Database size={48} className="mb-4 opacity-20" />
          <div className="font-['Orbitron'] tracking-widest">MEMORY_BANKS_EMPTY</div>
        </div>
      ) : (
        <div className="space-y-8 animate-in slide-in-from-bottom-4 duration-500">
          {groupedHistory.map((group, idx) => (
            <div key={idx}>
              <h3 className="text-xl font-['Orbitron'] font-bold text-white mb-6 flex items-center gap-2">
                 <span className="w-2 h-2 bg-primary rounded-full"></span>
                 {group.date}
              </h3>
              <div className="grid grid-cols-1 gap-4">
                {group.items.map((item: HistoryItem & { resourceId?: string }) => {
                   // Calculate percentage, guard against 0 duration
                   const pct = item.duration > 0 ? Math.min(100, Math.round((item.progress / item.duration) * 100)) : 0;
                   return (
                    <div key={item.id || Math.random()} className="group bg-[#0a0a12]/40 border border-white/10 hover:border-primary/50 transition-all p-4 flex flex-col md:flex-row items-center gap-6 cursor-pointer relative overflow-hidden hover:bg-white/5 shadow-[0_0_20px_rgba(0,0,0,0.3)] hover:shadow-[0_0_20px_rgba(0,243,255,0.1)]" onClick={() => onMovieSelect(item)}>
                      {item.resourceId && (
                        <button 
                          onClick={(e) => { e.stopPropagation(); onDeleteHistoryItem(item.resourceId!); }}
                          className="absolute top-2 right-2 p-2 text-gray-600 hover:text-red-500 hover:bg-red-500/10 rounded-full z-20 transition-all opacity-0 group-hover:opacity-100"
                          title="Delete Record"
                        >
                          <X size={16} />
                        </button>
                      )}

                      <div className="w-full md:w-48 h-28 shrink-0 relative overflow-hidden border border-white/10 group-hover:border-primary/50 transition-colors">
                         {item.cover_url ? (
                            <div className="absolute inset-0 bg-cover bg-center transition-transform duration-500 group-hover:scale-110" style={{ backgroundImage: `url(${item.cover_url})` }}></div>
                         ) : (
                            <div className="absolute inset-0 bg-gray-800 flex items-center justify-center"><Film className="text-gray-600" /></div>
                         )}
                         <div className="absolute inset-0 bg-black/20 group-hover:bg-transparent transition-colors"></div>
                         <div className="absolute inset-0 flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity">
                             <div className="bg-black/60 p-2 rounded-full border border-primary text-primary backdrop-blur-sm"><Play size={20} fill="currentColor" /></div>
                         </div>
                      </div>

                      <div className="flex-1 w-full">
                         <div className="flex justify-between items-start mb-2">
                            <div className="pr-8">
                               <h4 className="text-lg font-bold text-white font-['Noto_Sans_SC'] group-hover:text-primary transition-colors truncate">{item.title}</h4>
                               <div className="text-xs text-gray-500 font-['Rajdhani'] flex items-center gap-2 mt-1">
                                  <Clock size={12} className="text-gray-500" />
                                  <span>{item.time_str}</span>
                                  <span className="w-1 h-1 bg-gray-600 rounded-full"></span>
                                  <span className="text-gray-400">{formatDuration(item.progress)} / {formatDuration(item.duration)}</span>
                               </div>
                            </div>
                            <SciFiProgressRing progress={pct} size={40} />
                         </div>

                         <SciFiProgressBar progress={pct} />
                      </div>
                    </div>
                   );
                })}
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
};

import React, { useState, useEffect, useMemo, useRef, useCallback } from 'react';
import { Filter, Cpu, Globe, Calendar, AlertTriangle, Loader2, Search } from 'lucide-react';
import { MovieCard } from '../components/movies/Cards';
import { Movie, Genre } from '../types';
import { FILTERS } from '../constants';
import { FilterTag } from '../components/ui/CyberComponents';
import { movieService } from '../services/api';

export const Library = ({ onMovieSelect, initialType = "全部类型" }: { onMovieSelect: (m: Movie) => void; initialType?: string }) => { 
  const [filters, setFilters] = useState({ type: initialType, region: "全部地区", year: "全部年份", sort: "更新时间" }); 
  const [libraryMovies, setLibraryMovies] = useState<Movie[]>([]);
  const [page, setPage] = useState(1);
  const [pageSize, setPageSize] = useState(0);
  const [hasMore, setHasMore] = useState(true);
  const [isLoading, setIsLoading] = useState(false);
  const [genres, setGenres] = useState<Genre[]>([]);
  const observer = useRef<IntersectionObserver | null>(null);

  useEffect(() => { setFilters(prev => ({ ...prev, type: initialType })); }, [initialType]); 

  // Fetch available genres on mount
  useEffect(() => {
    const fetchGenres = async () => {
      try {
        const data = await movieService.getGenres();

        // Filter: Remove specific unwanted genres per user request
        const bannedGenres = ["Sci-Fi & Fantasy", "动作冒险", "音乐", "电视电影"];
        let processed = data.filter(g => !bannedGenres.includes(g.name));

        // Rename: Local -> 其他
        processed = processed.map(g => g.name === 'Local' ? { ...g, name: '其他' } : g);

        // Sort: Move "其他" to the end
        processed.sort((a, b) => {
            if (a.name === '其他') return 1;
            if (b.name === '其他') return -1;
            return 0;
        });

        setGenres(processed);
      } catch (e) {
        console.error("Failed to fetch genres", e);
      }
    };
    fetchGenres();
  }, []);

  // Calculate dynamic page size to fill screen
  useEffect(() => {
    const calculateSize = () => {
      const width = window.innerWidth;
      const cols = width >= 1280 ? 6 : width >= 1024 ? 5 : width >= 768 ? 4 : 2;
      const padding = width >= 768 ? 96 : 32; 
      const contentWidth = width - padding;
      const cardWidth = contentWidth / cols;
      const cardHeight = cardWidth * 1.5; 
      const rows = Math.ceil(window.innerHeight / cardHeight) + 1;
      const needed = cols * rows;
      setPageSize(Math.max(needed, 20));
    };
    calculateSize();
  }, []);

  // Reset list when server-side filters change (Type, Sort)
  useEffect(() => {
    setPage(1);
    setLibraryMovies([]);
    setHasMore(true);
  }, [filters.type, filters.sort]);

  // Fetch movies with pagination and server-side filtering/sorting
  useEffect(() => {
    if (pageSize === 0) return;

    const fetchMovies = async () => {
      setIsLoading(true);
      try {
        // Determine genre param
        let genreParam: string | undefined = undefined;
        if (filters.type !== "全部类型") {
           const matchedGenre = genres.find(g => g.name === filters.type);
           genreParam = matchedGenre ? matchedGenre.slug : filters.type;
        }

        // Determine sort params
        let sortBy = 'date_added';
        let order = 'desc';
        if (filters.sort === "综合评分") {
           sortBy = 'rating';
        } else if (filters.sort === "上映年份") {
           sortBy = 'year';
        } else if (filters.sort === "标题") {
           sortBy = 'title';
           order = 'asc';
        }

        const res = await movieService.getAll(pageSize, page, genreParam, sortBy, order);
        setLibraryMovies(prev => {
          if (page === 1) return res.items;
          const existingIds = new Set(prev.map(m => m.id));
          const newItems = res.items.filter(m => !existingIds.has(m.id));
          return [...prev, ...newItems];
        });

        if (res.meta) {
          setHasMore(res.meta.current_page < res.meta.total_pages);
        } else {
          setHasMore(res.items.length === pageSize);
        }
      } catch (error) {
        console.error("Failed to fetch library", error);
      } finally {
        setIsLoading(false);
      }
    };
    fetchMovies();
  }, [page, pageSize, filters.type, filters.sort, genres]); 

  // Client-side Filtering for secondary fields (Region, Year)
  const REGION_KEYWORDS: Record<string, string[]> = { "美国": ["美国", "USA", "United States", "America", "US"], "日本": ["日本", "Japan", "JP"], "中国": ["中国", "China", "CN", "Hong Kong", "Taiwan", "香港", "台湾"], "英国": ["英国", "UK", "United Kingdom", "Britain"], "韩国": ["韩国", "Korea", "South Korea", "KR"], "其他": ["其他", "Other"] }; 

  const displayedMovies = useMemo(() => { 
    let result = [...libraryMovies]; 

    if (filters.region !== "全部地区") { 
      result = result.filter(m => { 
        const r = (m.region || "").toLowerCase(); 
        const tags = (m.tags || []).map(t => t.toLowerCase()); 
        const keywords = REGION_KEYWORDS[filters.region] || [filters.region]; 
        return keywords.some(k => { 
          const keyword = k.toLowerCase(); 
          return r.includes(keyword) || tags.some(t => t.includes(keyword)); 
        }); 
      }); 
    } 
    if (filters.year !== "全部年份") { 
      if (filters.year === "更早") { result = result.filter(m => m.year < 2020); } 
      else { result = result.filter(m => String(m.year) == filters.year); } 
    } 
    // Sort is handled server-side now, so we removed client-side sort logic to avoid conflict
    return result; 
  }, [libraryMovies, filters]); 

  // Auto-advance if filtered list is empty but server has more data
  useEffect(() => {
    if (!isLoading && hasMore && displayedMovies.length === 0 && libraryMovies.length > 0) {
       const timer = setTimeout(() => {
         setPage(prev => prev + 1);
       }, 500);
       return () => clearTimeout(timer);
    }
  }, [isLoading, hasMore, displayedMovies.length, libraryMovies.length]);

  // Infinite Scroll Ref
  const lastMovieRef = useCallback((node: HTMLDivElement) => {
    if (isLoading) return;
    if (observer.current) observer.current.disconnect();
    observer.current = new IntersectionObserver(entries => {
      if (entries[0].isIntersecting && hasMore) {
        setPage(prev => prev + 1);
      }
    });
    if (node) observer.current.observe(node);
  }, [isLoading, hasMore]);

  // Merge static and dynamic genres for display
  const displayGenres = ["全部类型", ...genres.map(g => g.name)];
  // Fallback to static if fetch fails/empty, but prioritize fetched ones
  const filterList = genres.length > 0 ? displayGenres : FILTERS.types;

  return (
    <div className="min-h-screen w-full pt-24 px-4 md:px-12 pb-12"> 
      <div className="flex items-center gap-4 mb-8"> 
        <div className="p-2 border border-primary text-primary shadow-[0_0_10px_var(--color-primary)]"> <Filter className="w-6 h-6" /> </div> 
        <h1 className="text-3xl font-['Orbitron'] font-bold text-white tracking-widest"> DATABASE <span className="text-primary">ARCHIVES</span> </h1> 
        <div className="flex-grow h-[1px] bg-gradient-to-r from-primary/50 to-transparent"></div> 
      </div> 
      <div className="bg-[#0a0a12]/80 border border-white/10 backdrop-blur-md p-6 mb-10 relative overflow-hidden group tech-border"> 
        <div className="absolute top-0 right-0 w-16 h-16 border-t-2 border-r-2 border-red-500/50"></div> 
        <div className="space-y-4 relative z-10"> 
          <div className="flex flex-col md:flex-row md:items-center gap-2 md:gap-4"> 
            <span className="text-primary font-['Noto_Sans_SC'] font-bold py-1 min-w-[4rem] flex items-center gap-2"> <Cpu size={14} /> 类型 </span> 
            <div className="flex flex-wrap gap-2"> {filterList.map(type => (<FilterTag key={type} label={type} active={filters.type === type} onClick={() => setFilters({ ...filters, type: type })} />))} </div> 
          </div> 
          <div className="h-[1px] bg-white/5 w-full"></div> 
          <div className="flex flex-col md:flex-row md:items-center gap-2 md:gap-4"> 
            <span className="text-secondary font-['Noto_Sans_SC'] font-bold py-1 min-w-[4rem] flex items-center gap-2"> <Globe size={14} /> 地区 </span> 
            <div className="flex flex-wrap gap-2"> {FILTERS.regions.map(region => (<FilterTag key={region} label={region} active={filters.region === region} onClick={() => setFilters({ ...filters, region: region })} />))} </div> 
          </div> 
          <div className="h-[1px] bg-white/5 w-full"></div> 
          <div className="flex flex-col md:flex-row md:items-center gap-2 md:gap-4"> 
            <span className="text-accent font-['Noto_Sans_SC'] font-bold py-1 min-w-[4rem] flex items-center gap-2"> <Calendar size={14} /> 年份 </span> 
            <div className="flex flex-wrap gap-2"> {FILTERS.years.map(year => (<FilterTag key={year} label={year} active={filters.year === year} onClick={() => setFilters({ ...filters, year: year })} />))} </div> 
          </div> 
        </div> 
      </div> 
      <div className="flex flex-col md:flex-row justify-between items-end md:items-center mb-6 font-['Rajdhani'] gap-4"> 
        <div className="text-gray-400 text-sm flex items-center gap-2"> FOUND <span className="text-primary font-bold text-lg">{displayedMovies.length}</span> FILES {libraryMovies.length > 0 && <span className="text-xs opacity-50">/ SCANNED {libraryMovies.length}</span>}</div> 
        <div className="flex items-center gap-2 bg-black/40 border border-white/10 px-2 py-1 rounded-sm"> {FILTERS.sorts.map(sort => (<button key={sort.id} onClick={() => setFilters({ ...filters, sort: sort.id })} className={`px-3 py-1 text-sm flex items-center gap-1 hover:text-primary transition-colors relative ${filters.sort === sort.id ? 'text-primary font-bold' : 'text-gray-500'}`} > {sort.label} {filters.sort === sort.id && <div className="absolute bottom-0 left-0 w-full h-[2px] bg-primary shadow-[0_0_5px_var(--color-primary)]"></div>} </button>))} </div> 
      </div> 

      <div className="grid grid-cols-2 md:grid-cols-4 lg:grid-cols-5 xl:grid-cols-6 gap-6"> 
        {displayedMovies.map((movie, index) => {
           // Attach ref to the last element of the list
           if (index === displayedMovies.length - 1) {
             return <div key={movie.id} ref={lastMovieRef}><MovieCard movie={movie} category={{ colorClass: 'border-white/20' }} onClick={onMovieSelect} /></div>;
           }
           return <MovieCard key={movie.id} movie={movie} category={{ colorClass: 'border-white/20' }} onClick={onMovieSelect} />;
        })} 
      </div>

      {isLoading && (
        <div className="w-full flex flex-col items-center justify-center py-8 gap-2">
          <Loader2 className="w-8 h-8 text-primary animate-spin" />
          <span className="text-xs font-['Orbitron'] text-primary animate-pulse">SCANNING_ARCHIVES...</span>
        </div>
      )}

      {!isLoading && displayedMovies.length === 0 && !hasMore && (
        <div className="h-96 w-full flex flex-col items-center justify-center gap-4 text-gray-600 border border-white/5 bg-black/20"> 
          <AlertTriangle size={48} className="opacity-30" /> 
          <div className="font-['Orbitron'] tracking-widest text-xl">NO DATA MATCHED</div> 
          <div className="text-xs font-sans">筛选条件未匹配到任何结果</div> 
        </div>
      )}

      {!hasMore && displayedMovies.length > 0 && (
        <div className="w-full text-center py-8 text-gray-600 font-['Rajdhani'] text-xs tracking-widest">END OF ARCHIVE</div>
      )}
    </div>
  ); 
};

