import { ReactNode } from 'react';

export interface ThemeConfig {
  primary: string;
  secondary: string;
  bg: string;
  text: string;
  accent: string;
}

export interface TechSpecs {
  resolution?: string;
  codec?: string;
  size?: string;
  audio?: string;
  bitrate?: string;
  container?: string;
}

export interface MediaInfo {
  video_codec?: string;
  audio_codec?: string;
  resolution?: string;
  bitrate?: number;
}

export interface Resource {
  id: string;
  filename: string;
  source_id: number;
  source_name: string;
  protocol: string;
  relative_path: string;
  quality_label?: string;
  size_bytes?: number;
  container?: string;
  media_info?: MediaInfo;
}

export interface Genre {
  name: string;
  slug: string;
  count: number;
}

export interface Movie {
  id: string | number;
  title: string;
  original_title?: string;
  rating: string; // Mapped from number
  year: number;
  duration?: string | number;
  tags?: string[];
  desc?: string; // Mapped from overview
  overview?: string; // Raw API field
  cast?: string[];
  director?: string;
  poster_url?: string; // Raw API field
  backdrop_url?: string; // Raw API field
  cover_url?: string; // Mapped from poster_url for UI compat
  resources?: Resource[];
  type?: string;
  region?: string;
  tech_specs?: TechSpecs;
  views?: string;
  trend?: 'up' | 'down' | 'stable';
  change?: string;
  source_path?: string; // Legacy compat
  isPlayed?: boolean;
  lastPlayedAt?: string;
}

export interface Category {
