import { MovieCard } from '../components/movies/Cards';
import { Movie, Genre } from '../types';
import { FILTERS } from '../constants';
import { FilterTag } from '../components/ui/CyberComponents';
import { movieService } from '../services/api';

export const Library = ({ onMovieSelect, initialType = "全部类型" }: { onMovieSelect: (m: Movie) => void; initialType?: string }) => { 
  const [filters, setFilters] = useState({ type: initialType, region: "全部地区", year: "全部年份", sort: "更新时间" }); 
  const [libraryMovies, setLibraryMovies] = useState<Movie[]>([]);
  const [page, setPage] = useState(1);
  const [pageSize, setPageSize] = useState(0);
  const [hasMore, setHasMore] = useState(true);
  const [isLoading, setIsLoading] = useState(false);
  const [genres, setGenres] = useState<Genre[]>([]);
  const observer = useRef<IntersectionObserver | null>(null);

  useEffect(() => { setFilters(prev => ({ ...prev, type: initialType })); }, [initialType]); 

  // Fetch available genres on mount
  useEffect(() => {
    const fetchGenres = async () => {
      try {
        const data = await movieService.getGenres();

        // Filter: Remove specific unwanted genres per user request (both CN and EN common names)
        const bannedGenres = [
            "Sci-Fi & Fantasy", "动作冒险", "音乐", "电视电影",
            "Action & Adventure", "Music", "TV Movie", "Kids", "News", "Reality", "Soap", "Talk", "Politics"
        ];

        let processed = data.filter(g => !bannedGenres.includes(g.name));

        // Rename: Local -> 其他
        processed = processed.map(g => g.name === 'Local' ? { ...g, name: '其他' } : g);

        // Check if we have substantial data (more than just '其他')
        const hasSubstantialData = processed.filter(g => g.name !== '其他').length > 0;

        if (!hasSubstantialData) {
            // Fallback: Use standard hardcoded types if API returns nothing or only 'Local'
            // This prevents the UI from showing only "全部类型" and "其他"
            const defaults = FILTERS.types.slice(1).map(name => ({ name, slug: name, count: 0 }));

            // If '其他' (Local) existed in API, keep it
            const others = processed.find(g => g.name === '其他');

            processed = defaults;
            if (others) {
                processed.push(others);
            }
        } else {
            // Sort: Move "其他" to the end
            processed.sort((a, b) => {
                if (a.name === '其他') return 1;
                if (b.name === '其他') return -1;
                return 0;
            });
        }

        setGenres(processed);
      } catch (e) {
        console.error("Failed to fetch genres", e);
        // Fallback on error
        setGenres(FILTERS.types.slice(1).map(name => ({ name, slug: name, count: 0 })));
      }
    };
    fetchGenres();
  }, []);

  // Calculate dynamic page size to fill screen
  useEffect(() => {
    const calculateSize = () => {
      const width = window.innerWidth;
      const cols = width >= 1280 ? 6 : width >= 1024 ? 5 : width >= 768 ? 4 : 2;
      const padding = width >= 768 ? 96 : 32; 
      const contentWidth = width - padding;
      const cardWidth = contentWidth / cols;
      const cardHeight = cardWidth * 1.5; 
      const rows = Math.ceil(window.innerHeight / cardHeight) + 1;
      const needed = cols * rows;
      setPageSize(Math.max(needed, 20));
    };
    calculateSize();
  }, []);

  // Reset list when server-side filters change (Type, Sort)
  useEffect(() => {
    setPage(1);
    setLibraryMovies([]);
    setHasMore(true);
  }, [filters.type, filters.sort]);

  // Fetch movies with pagination and server-side filtering/sorting
  useEffect(() => {
    if (pageSize === 0) return;

    const fetchMovies = async () => {
      setIsLoading(true);
      try {
        // Determine genre param
        let genreParam: string | undefined = undefined;
        if (filters.type !== "全部类型") {
           const matchedGenre = genres.find(g => g.name === filters.type);
           // If matched, use slug. If not matched (fallback case), try mapping or use raw
           genreParam = matchedGenre ? matchedGenre.slug : filters.type;
        }

        // Determine sort params
        let sortBy = 'date_added';
        let order = 'desc';
        if (filters.sort === "综合评分") {
           sortBy = 'rating';
        } else if (filters.sort === "上映年份") {
           sortBy = 'year';
        } else if (filters.sort === "标题") {
           sortBy = 'title';
           order = 'asc';
        }

        const res = await movieService.getAll(pageSize, page, genreParam, sortBy, order);
        setLibraryMovies(prev => {
          if (page === 1) return res.items;
          const existingIds = new Set(prev.map(m => m.id));
          const newItems = res.items.filter(m => !existingIds.has(m.id));
          return [...prev, ...newItems];
        });

        if (res.meta) {
          setHasMore(res.meta.current_page < res.meta.total_pages);
        } else {
          setHasMore(res.items.length === pageSize);
        }
      } catch (error) {
        console.error("Failed to fetch library", error);
      } finally {
        setIsLoading(false);
      }
    };
    fetchMovies();
  }, [page, pageSize, filters.type, filters.sort, genres]); 

  // Client-side Filtering for secondary fields (Region, Year)
  const REGION_KEYWORDS: Record<string, string[]> = { "美国": ["美国", "USA", "United States", "America", "US"], "日本": ["日本", "Japan", "JP"], "中国": ["中国", "China", "CN", "Hong Kong", "Taiwan", "香港", "台湾"], "英国": ["英国", "UK", "United Kingdom", "Britain"], "韩国": ["韩国", "Korea", "South Korea", "KR"], "其他": ["其他", "Other"] }; 

  const displayedMovies = useMemo(() => { 
    let result = [...libraryMovies]; 

    if (filters.region !== "全部地区") { 
      result = result.filter(m => { 
        const r = (m.region || "").toLowerCase(); 
        const tags = (m.tags || []).map(t => t.toLowerCase()); 
        const keywords = REGION_KEYWORDS[filters.region] || [filters.region]; 
        return keywords.some(k => { 
          const keyword = k.toLowerCase(); 
          return r.includes(keyword) || tags.some(t => t.includes(keyword)); 
        }); 
      }); 
    } 
    if (filters.year !== "全部年份") { 
      if (filters.year === "更早") { result = result.filter(m => m.year < 2020); } 
      else { result = result.filter(m => String(m.year) == filters.year); } 
    } 
    // Sort is handled server-side now, so we removed client-side sort logic to avoid conflict
    return result; 
  }, [libraryMovies, filters]); 

  // Auto-advance if filtered list is empty but server has more data
  useEffect(() => {
    if (!isLoading && hasMore && displayedMovies.length === 0 && libraryMovies.length > 0) {
       const timer = setTimeout(() => {
         setPage(prev => prev + 1);
       }, 500);
       return () => clearTimeout(timer);
    }
  }, [isLoading, hasMore, displayedMovies.length, libraryMovies.length]);

  // Infinite Scroll Ref
  const lastMovieRef = useCallback((node: HTMLDivElement) => {
    if (isLoading) return;
    if (observer.current) observer.current.disconnect();
    observer.current = new IntersectionObserver(entries => {
      if (entries[0].isIntersecting && hasMore) {
        setPage(prev => prev + 1);
      }
    });
    if (node) observer.current.observe(node);
  }, [isLoading, hasMore]);

  // Merge static and dynamic genres for display
  // Use state genres as source of truth now since it handles the fallback
  const displayGenres = ["全部类型", ...genres.map(g => g.name)];

  return (
    <div className="min-h-screen w-full pt-24 px-4 md:px-12 pb-12"> 
      <div className="flex items-center gap-4 mb-8"> 
        <div className="p-2 border border-primary text-primary shadow-[0_0_10px_var(--color-primary)]"> <Filter className="w-6 h-6" /> </div> 
        <h1 className="text-3xl font-['Orbitron'] font-bold text-white tracking-widest"> DATABASE <span className="text-primary">ARCHIVES</span> </h1> 
        <div className="flex-grow h-[1px] bg-gradient-to-r from-primary/50 to-transparent"></div> 
      </div> 
      <div className="bg-[#0a0a12]/80 border border-white/10 backdrop-blur-md p-6 mb-10 relative overflow-hidden group tech-border"> 
        <div className="absolute top-0 right-0 w-16 h-16 border-t-2 border-r-2 border-red-500/50"></div> 
        <div className="space-y-4 relative z-10"> 
          <div className="flex flex-col md:flex-row md:items-center gap-2 md:gap-4"> 
            <span className="text-primary font-['Noto_Sans_SC'] font-bold py-1 min-w-[4rem] flex items-center gap-2"> <Cpu size={14} /> 类型 </span> 
            <div className="flex flex-wrap gap-2"> {displayGenres.map(type => (<FilterTag key={type} label={type} active={filters.type === type} onClick={() => setFilters({ ...filters, type: type })} />))} </div> 
          </div> 
          <div className="h-[1px] bg-white/5 w-full"></div> 
          <div className="flex flex-col md:flex-row md:items-center gap-2 md:gap-4"> 
            <span className="text-secondary font-['Noto_Sans_SC'] font-bold py-1 min-w-[4rem] flex items-center gap-2"> <Globe size={14} /> 地区 </span> 
            <div className="flex flex-wrap gap-2"> {FILTERS.regions.map(region => (<FilterTag key={region} label={region} active={filters.region === region} onClick={() => setFilters({ ...filters, region: region })} />))} </div> 
          </div> 
          <div className="h-[1px] bg-white/5 w-full"></div> 
          <div className="flex flex-col md:flex-row md:items-center gap-2 md:gap-4"> 
            <span className="text-accent font-['Noto_Sans_SC'] font-bold py-1 min-w-[4rem] flex items-center gap-2"> <Calendar size={14} /> 年份 </span> 
            <div className="flex flex-wrap gap-2"> {FILTERS.years.map(year => (<FilterTag key={year} label={year} active={filters.year === year} onClick={() => setFilters({ ...filters, year: year })} />))} </div> 
          </div> 
        </div> 
      </div> 
      <div className="flex flex-col md:flex-row justify-between items-end md:items-center mb-6 font-['Rajdhani'] gap-4"> 
        <div className="text-gray-400 text-sm flex items-center gap-2"> FOUND <span className="text-primary font-bold text-lg">{displayedMovies.length}</span> FILES {libraryMovies.length > 0 && <span className="text-xs opacity-50">/ SCANNED {libraryMovies.length}</span>}</div> 
        <div className="flex items-center gap-2 bg-black/40 border border-white/10 px-2 py-1 rounded-sm"> {FILTERS.sorts.map(sort => (<button key={sort.id} onClick={() => setFilters({ ...filters, sort: sort.id })} className={`px-3 py-1 text-sm flex items-center gap-1 hover:text-primary transition-colors relative ${filters.sort === sort.id ? 'text-primary font-bold' : 'text-gray-500'}`} > {sort.label} {filters.sort === sort.id && <div className="absolute bottom-0 left-0 w-full h-[2px] bg-primary shadow-[0_0_5px_var(--color-primary)]"></div>} </button>))} </div> 
      </div> 

      <div className="grid grid-cols-2 md:grid-cols-4 lg:grid-cols-5 xl:grid-cols-6 gap-6"> 
        {displayedMovies.map((movie, index) => {
           // Attach ref to the last element of the list
           if (index === displayedMovies.length - 1) {
             return <div key={movie.id} ref={lastMovieRef}><MovieCard movie={movie} category={{ colorClass: 'border-white/20' }} onClick={onMovieSelect} /></div>;
           }
           return <MovieCard key={movie.id} movie={movie} category={{ colorClass: 'border-white/20' }} onClick={onMovieSelect} />;
        })} 
      </div>

      {isLoading && (
        <div className="w-full flex flex-col items-center justify-center py-8 gap-2">
          <Loader2 className="w-8 h-8 text-primary animate-spin" />
          <span className="text-xs font-['Orbitron'] text-primary animate-pulse">SCANNING_ARCHIVES...</span>
        </div>
      )}

      {!isLoading && displayedMovies.length === 0 && !hasMore && (
        <div className="h-96 w-full flex flex-col items-center justify-center gap-4 text-gray-600 border border-white/5 bg-black/20"> 
          <AlertTriangle size={48} className="opacity-30" /> 
          <div className="font-['Orbitron'] tracking-widest text-xl">NO DATA MATCHED</div> 
          <div className="text-xs font-sans">筛选条件未匹配到任何结果</div> 
        </div>
      )}

      {!hasMore && displayedMovies.length > 0 && (
        <div className="w-full text-center py-8 text-gray-600 font-['Rajdhani'] text-xs tracking-widest">END OF ARCHIVE</div>
      )}
    </div>
  ); 
};

import React, { useState, useEffect, useMemo } from 'react';
import { ChevronLeft, PlayCircle, Plus, Download, Share2, Star, User, RotateCcw, FileVideo, Play, Cpu, HardDrive, Music, Box, Monitor } from 'lucide-react';
import { Movie, PlayOptions, HistoryItem } from '../types';
import { movieService } from '../services/api';
import { formatBytes, formatDuration } from '../utils';
import { MovieCard } from '../components/movies/Cards';

interface MovieDetailProps {
  movie: Movie;
  history: HistoryItem[];
  onBack: () => void;
  onPlay: (options: PlayOptions) => void;
  onMovieSelect: (m: Movie) => void;
  isFavorite: boolean;
  onToggleFavorite: (m: Movie) => void;
}

export const MovieDetail: React.FC<MovieDetailProps> = ({ movie, history, onBack, onPlay, onMovieSelect, isFavorite, onToggleFavorite }) => { 
  const [fullMovieData, setFullMovieData] = useState<Movie>(movie);
  const [loading, setLoading] = useState(false);

  // Fetch detailed info (resources) when movie changes
  useEffect(() => {
    const fetchDetail = async () => {
      setLoading(true);
      const detail = await movieService.getDetail(movie.id);
      if (detail) {
        setFullMovieData(detail);
      }
      setLoading(false);
    };
    fetchDetail();
    window.scrollTo(0, 0);
  }, [movie.id]);

  const safeId = String(fullMovieData.id || 'def');
  const hue = parseInt(safeId.split('-').pop() || '0') * 40; 

  // Resources check
  const hasResources = fullMovieData.resources && fullMovieData.resources.length > 0;
  const primaryResource = hasResources ? fullMovieData.resources![0] : null;

  // Calculate Resume Record
  // We look for any history item that matches one of the resources of this movie
  // Since history is typically sorted by recent, the first match is the last watched episode
  const resumeRecord = useMemo(() => {
    if (!history || !fullMovieData.resources) return null;

    // Create a set of resource IDs belonging to this movie
    const movieResourceIds = new Set(fullMovieData.resources.map(r => r.id));

    // Find the first history item that exists in this movie's resources
    const match = history.find(h => movieResourceIds.has(h.resourceId));

    // Only resume if progress is meaningful (>5s) and not effectively finished (>95%)
    if (match && match.progress > 5 && match.duration > 0 && (match.progress / match.duration) < 0.95) {
        // Enhance match with the filename from resources for display
        const resourceDetail = fullMovieData.resources.find(r => r.id === match.resourceId);
        return {
            ...match,
            filename: resourceDetail?.filename || 'Unknown File'
        };
    }
    return null;
  }, [history, fullMovieData]);

  const handlePlay = () => {
    if (primaryResource) {
      onPlay({ resourceId: primaryResource.id });
    }
  };

  const handleResume = () => {
    if (resumeRecord) {
        onPlay({ 
            resourceId: resumeRecord.resourceId, 
            startTime: resumeRecord.progress 
        });
    }
  };

  const techSpecs = fullMovieData.tech_specs || {}; 

  return (
    <div className="relative min-h-screen w-full text-white pt-24 pb-12"> 
      <div className="absolute inset-0 bg-[#050505] z-0"> 
          <div className="absolute inset-0 opacity-20" style={{ backgroundImage: `radial-gradient(circle at 70% 20%, hsla(${hue}, 70%, 50%, 0.3), transparent 60%)`, }}></div> 
          {fullMovieData.backdrop_url && <div className="absolute inset-0 bg-cover bg-center opacity-20 mix-blend-overlay transition-opacity duration-1000" style={{ backgroundImage: `url(${fullMovieData.backdrop_url})` }}></div>}
          <div className="absolute inset-0 bg-gradient-to-t from-[#050505] via-[#050505]/80 to-transparent"></div> 
      </div> 

      <div className="container mx-auto px-6 md:px-12 relative z-10"> 
        <button onClick={onBack} className="group flex items-center gap-2 text-gray-400 hover:text-primary mb-8 transition-colors"> <ChevronLeft className="group-hover:-translate-x-1 transition-transform" /> <span className="font-['Rajdhani'] font-bold tracking-wider">RETURN TO GRID</span> </button> 

        <div className="flex flex-col lg:flex-row gap-12 mb-20"> 
            <div className="w-full lg:w-1/3 flex flex-col gap-6"> 
                <div className="aspect-[2/3] w-full bg-[#0a0a12] border border-white/10 relative overflow-hidden group tech-border shadow-[0_0_30px_rgba(0,243,255,0.1)]"> 
                    <div className="absolute inset-0 bg-gradient-to-br from-primary/20 to-secondary/20 opacity-50"></div> 
                    {fullMovieData.cover_url ? (<div className="absolute inset-0 bg-cover bg-center opacity-80" style={{ backgroundImage: `url(${fullMovieData.cover_url})` }}></div>) : (<div className="absolute inset-0 flex flex-col items-center justify-center p-8 text-center border-4 border-double border-white/5 m-2"> <div className="text-6xl mb-4 opacity-20"> {fullMovieData.title.charAt(0)} </div> <h2 className="text-3xl font-['Orbitron'] font-bold text-white/80 glitch-text" data-text={fullMovieData.title}> {fullMovieData.title} </h2> </div>)} 
                </div> 

                {/* Tech Specs Block */}
                {techSpecs.resolution && (
                  <div className="grid grid-cols-2 gap-2 font-['Rajdhani'] text-xs">
                    {techSpecs.codec && <div className="bg-white/5 border border-white/10 p-2 flex items-center gap-2 text-gray-300"><Cpu size={14} className="text-primary"/> {techSpecs.codec}</div>}
                    {techSpecs.audio && <div className="bg-white/5 border border-white/10 p-2 flex items-center gap-2 text-gray-300"><Music size={14} className="text-secondary"/> {techSpecs.audio}</div>}
                    {techSpecs.resolution && <div className="bg-white/5 border border-white/10 p-2 flex items-center gap-2 text-gray-300"><Monitor size={14} className="text-accent"/> {techSpecs.resolution}</div>}
                    {techSpecs.size && <div className="bg-white/5 border border-white/10 p-2 flex items-center gap-2 text-gray-300"><HardDrive size={14} className="text-gray-500"/> {techSpecs.size}</div>}
                    {techSpecs.bitrate && <div className="col-span-2 bg-white/5 border border-white/10 p-2 flex items-center gap-2 text-gray-400 justify-center tracking-widest">BITRATE: {techSpecs.bitrate}</div>}
                  </div>
                )}

                <div className="grid grid-cols-2 gap-4 font-['Rajdhani']"> 
                    <div className="bg-white/5 border border-white/10 p-4 rounded-sm text-center"> <div className="text-xs text-gray-400 uppercase tracking-widest mb-1">Resource Status</div> <div className={`text-xl font-bold ${hasResources ? 'text-green-500' : 'text-red-500'}`}>{hasResources ? 'AVAILABLE' : 'OFFLINE'}</div> </div> 
                    <div className="bg-white/5 border border-white/10 p-4 rounded-sm text-center"> <div className="text-xs text-gray-400 uppercase tracking-widest mb-1">Rating</div> <div className="text-2xl font-bold text-secondary flex items-center justify-center gap-1"> <Star size={16} fill="var(--color-secondary)" /> {fullMovieData.rating} </div> </div> 
                </div> 
            </div> 

            <div className="flex-1"> 
                <h1 className="text-5xl md:text-7xl font-black font-['Orbitron'] text-white mb-6 tracking-tighter uppercase leading-tight"> {fullMovieData.title} </h1> 
                {fullMovieData.original_title && <h2 className="text-xl text-gray-500 font-['Noto_Sans_SC'] mb-6">{fullMovieData.original_title}</h2>}
                <div className="flex flex-wrap items-center gap-4 md:gap-6 text-gray-300 font-['Rajdhani'] text-lg mb-8"> 
                    <span>{fullMovieData.year}</span> 
                    {fullMovieData.tags && fullMovieData.tags.length > 0 && (
                        <>
                            <span className="w-1 h-1 bg-gray-500 rounded-full"></span>
                            <div className="flex flex-wrap gap-3">
                            {fullMovieData.tags.slice(0, 4).map(tag => (
                                <span key={tag} className="text-white/80 hover:text-primary transition-colors cursor-default">{tag}</span>
                            ))}
                            </div>
                        </>
                    )}
                    <span className="w-1 h-1 bg-gray-500 rounded-full"></span> 
                    <span>{hasResources ? `${fullMovieData.resources?.length} FILES` : 'NO FILES'}</span> 
                </div> 

                <div className="flex flex-wrap gap-4 mb-10 items-stretch">
                    {/* Resume Button - Cyberpunk Style */}
                    {resumeRecord && (
                        <button onClick={handleResume} className="relative group h-[70px] min-w-[260px] bg-transparent border-none outline-none cursor-pointer flex-grow md:flex-grow-0">
                            {/* Background Shape - Skewed Primary Color */}
                            <div className="absolute inset-0 bg-primary skew-x-[-12deg] rounded-sm shadow-[0_0_15px_var(--color-primary)] group-hover:shadow-[0_0_30px_var(--color-primary)] group-hover:bg-white transition-all duration-300"></div>

                            {/* Scanline Effect */}
                            <div className="absolute inset-0 bg-[linear-gradient(rgba(0,0,0,0),rgba(0,0,0,0.1)_50%,rgba(0,0,0,0))] bg-[length:100%_4px] opacity-20 pointer-events-none skew-x-[-12deg]"></div>

                            {/* Content Wrapper */}
                            <div className="absolute inset-0 flex items-center justify-between px-6 z-10 text-black">
                                <div className="flex items-center gap-4">
                                     <div className="p-2 bg-black/10 rounded-sm group-hover:bg-black/20 transition-colors border border-black/5">
                                        <RotateCcw size={20} className="group-hover:-rotate-90 transition-transform duration-500" strokeWidth={2.5} />
                                     </div>
                                     <div className="flex flex-col items-start justify-center">
                                         <span className="font-['Orbitron'] font-black text-xl tracking-wider leading-none drop-shadow-sm">CONTINUE</span>
                                         <div className="flex items-center gap-2 mt-1 opacity-80 font-['Rajdhani'] font-bold text-xs">
                                             <span className="bg-black/10 px-1 rounded-sm">{formatDuration(resumeRecord.progress)}</span>
                                             <span className="w-1 h-1 bg-black rounded-full"></span>
                                             <span className="max-w-[100px] truncate uppercase">{resumeRecord.filename || 'EPISODE'}</span>
                                         </div>
                                     </div>
                                </div>

                                {/* Progress Circle Mini */}
                                 <div className="w-8 h-8 relative flex items-center justify-center ml-2 opacity-80 group-hover:opacity-100 transition-opacity">
                                    <svg className="w-full h-full -rotate-90" viewBox="0 0 32 32">
                                        <circle cx="16" cy="16" r="14" fill="none" stroke="rgba(0,0,0,0.1)" strokeWidth="3" />
                                        <circle cx="16" cy="16" r="14" fill="none" stroke="currentColor" strokeWidth="3" strokeDasharray={`${(resumeRecord.progress / resumeRecord.duration) * 88} 100`} />
                                    </svg>
                                    <Play size={10} fill="currentColor" className="absolute" />
                                 </div>
                            </div>

                            {/* Decorative Corner */}
                            <div className="absolute bottom-0 right-0 w-6 h-6 bg-gradient-to-tl from-black/20 to-transparent skew-x-[-12deg] pointer-events-none"></div>
                        </button>
                    )}

                    <button disabled={!hasResources} onClick={handlePlay} className={`flex-1 md:flex-none px-8 py-4 rounded-sm font-['Orbitron'] font-bold flex items-center justify-center gap-3 transition-all text-lg group border border-white/20 hover:border-primary/50 ${hasResources ? 'bg-black/40 hover:bg-black/60 text-white' : 'bg-gray-800 text-gray-500 cursor-not-allowed'}`} > 
                        <PlayCircle className={`w-6 h-6 ${hasResources ? 'text-primary group-hover:text-white transition-colors' : ''}`} /> 
                        <span>{loading ? 'LOADING...' : hasResources ? (resumeRecord ? 'RESTART' : 'PLAY NOW') : 'UNAVAILABLE'}</span> 
                    </button> 

                    <button onClick={() => onToggleFavorite(fullMovieData)} className={`flex-1 md:flex-none bg-transparent border ${isFavorite ? 'border-accent text-accent bg-accent/10' : 'border-white/30 text-white hover:bg-white/10'} px-6 py-4 rounded-sm font-['Orbitron'] font-bold flex items-center justify-center gap-3 transition-all`} > 
                        <Plus className={`w-5 h-5 ${isFavorite ? 'rotate-45' : ''} transition-transform`} /> 
                        <span>{isFavorite ? 'VAULTED' : 'ADD TO VAULT'}</span> 
                    </button> 
                </div> 

                <div className="mb-10 relative"> <h3 className="text-xl font-['Orbitron'] font-bold text-white mb-4 flex items-center gap-2"> <span className="w-1 h-6 bg-red-500"></span> OVERVIEW </h3> <p className="text-gray-300 text-lg leading-relaxed font-sans opacity-90 max-w-3xl border-l border-white/10 pl-6 py-2"> {fullMovieData.desc || fullMovieData.overview || "No detailed description available in the archive."} </p> </div> 
            </div> 
        </div> 
    </div> 
  </div>); 
};

