                                <div className="text-xl font-['Orbitron'] font-bold text-gray-300 flex items-center gap-2">
                                    <HardDrive size={18} /> {techSpecs.size || 'N/A'}
                                </div>
                                <div className="w-8 h-0.5 bg-gray-500 mt-3 opacity-50"></div>
                            </div>
                        </div>

                        {techSpecs.bitrate && (
                            <div className="mt-4 flex items-center gap-3 bg-black/40 border border-white/5 px-4 py-2 w-fit">
                                <Activity size={14} className="text-gray-500" />
                                <span className="text-xs font-['Rajdhani'] text-gray-400">BITRATE_STREAM:</span>
                                <span className="text-sm font-['Orbitron'] font-bold text-white tracking-wider">{techSpecs.bitrate}</span>
                            </div>
                        )}
                    </div>
                )}
            </div> 
        </div> 
    </div> 
  </div>); 
};

import React, { useState, useEffect } from 'react';
import Navbar, { Footer } from './components/layout/Navbar';
import { Home, Library, Leaderboard, HistoryPage, SearchResults } from './features/Views';
import { ProfilePage } from './features/Profile';
import { MovieDetail } from './features/MovieDetail';
import { Player } from './components/Player';
import { movieService, userService, systemService } from './services/api';
import { THEMES } from './constants';
import { getStyles } from './utils';
import { Movie, ViewState, Notification, PlayOptions, UserSettings } from './types';

const App = () => { 
  const [movies, setMovies] = useState<Movie[]>([]); 
  const [currentView, setCurrentView] = useState<ViewState>('home'); 
  const [libraryInitialType, setLibraryInitialType] = useState("全部类型"); 
  const [selectedMovie, setSelectedMovie] = useState<Movie | null>(null); 
  const [searchResults, setSearchResults] = useState<Movie[]>([]); 
  const [searchQuery, setSearchQuery] = useState(''); 
  const [favorites, setFavorites] = useState<Movie[]>([]); 
  const [history, setHistory] = useState<any[]>([]); 
  const [notifications, setNotifications] = useState<Notification[]>([]); 
  const [settings, setSettings] = useState<UserSettings>({ scanlines: true, glitch: true }); 
  const [themeName, setThemeName] = useState('CYBER'); 
  const currentTheme = THEMES[themeName]; 
  const [playOptions, setPlayOptions] = useState<PlayOptions>({}); 

  // Inject Dynamic Styles (Scanlines, Glitch, CSS Variables)
  useEffect(() => { 
    // We cannot easily inject styles via React state into a global stylesheet in a strictly compliant way without styled-components
    // But we can update CSS Variables on the root.
    const root = document.documentElement; 
    root.style.setProperty('--scanline-opacity', settings.scanlines ? '0.2' : '0'); 
    root.style.setProperty('--glitch-active', settings.glitch ? 'block' : 'none'); 
    root.style.setProperty('--color-primary', currentTheme.primary); 
    root.style.setProperty('--color-secondary', currentTheme.secondary); 
    root.style.setProperty('--color-bg', currentTheme.bg); 
    root.style.setProperty('--color-text', currentTheme.text); 
    root.style.setProperty('--color-accent', currentTheme.accent); 
  }, [settings, currentTheme]); 

  // Initial Data Fetch
  useEffect(() => { 
    const fetchData = async () => { 
      // Fetch small batch for initial view (Banner etc), Home will fetch its own categories
      try {
        const allMovies = await movieService.getAll(20);
        setMovies(allMovies.items);

        const historyData = await userService.getHistory();
        setHistory(historyData);

        const vaultData = await userService.getVault();
        setFavorites(vaultData);

        const notificationsData = await systemService.getNotifications();
        setNotifications(notificationsData);
      } catch (e) {
        console.error("Failed to fetch initial data", e);
      }
    }; 
    fetchData(); 
  }, []); // Only run once on mount, not on view change

  const handleSearch = async (query: string) => { 
    setSearchQuery(query); 
    setCurrentView('search'); 
    try { 
      const data = await movieService.search(query); 
      setSearchResults(data); 
    } catch (e) { 
      console.error("Search failed", e); 
    } 
  }; 

  const handleToggleFavorite = async (movie: Movie) => { 
    const isFav = favorites.some(f => f.id === movie.id); 
    let newFavs; 
    if (isFav) { 
      newFavs = favorites.filter(f => f.id !== movie.id); 
    } else { 
      newFavs = [...favorites, movie]; 
    } 
    setFavorites(newFavs); 
    await userService.toggleFavorite(movie); 
  }; 

  const handleClearHistory = async () => { 
    await userService.clearHistory();
    setHistory([]); 
  }; 

  const handleDeleteHistoryItem = async (resourceId: string) => {
    await userService.deleteHistoryItem(resourceId);
    setHistory(prev => prev.filter(item => item.resourceId !== resourceId));
  };

  const handleNavigate = (view: ViewState) => { 
    if (view === 'library') { 
      setLibraryInitialType("全部类型"); 
    } 
    if (view === 'history') { 
      userService.getHistory().then(setHistory).catch(console.error); 
    } 
    setCurrentView(view); 
  }; 

  const handleViewCategory = (categoryId: string) => { 
    const mapping: Record<string, string> = { 'scifi': '科幻', 'action': '动作', 'romance': '剧情', 'anime': '动画' }; 
    const filterLabel = mapping[categoryId] || "全部类型"; 
    setLibraryInitialType(filterLabel); 
    setCurrentView('library'); 
  }; 

  const handleMovieSelect = (selectedItem: Movie) => {
    let fullMovie = movies.find(m => String(m.id) === String(selectedItem.id));
    if (!fullMovie) {
      fullMovie = movies.find(m => m.title === selectedItem.title);
    }
    // If we still don't have it (e.g. from leaderboard), use selectedItem
    setSelectedMovie(fullMovie || selectedItem);
    setCurrentView('detail');
  };

  return (
    <div className="min-h-screen font-sans selection:bg-secondary selection:text-white relative bg-[#050505] text-white overflow-x-hidden" style={{ backgroundColor: currentTheme.bg }}> 
      <style>{getStyles(settings, currentTheme)}</style> 
      <div className="scanlines"></div> 
      <div className="perspective-grid"></div> 

      {currentView !== 'player' && (
        <Navbar onNavigate={handleNavigate} currentView={currentView} onSearch={handleSearch} onProfile={() => setCurrentView('profile')} notifications={notifications} />
      )} 

      {currentView === 'home' && (<Home movies={movies} onMovieSelect={handleMovieSelect} onViewMore={handleViewCategory} />)} 
      {currentView === 'library' && (<Library onMovieSelect={handleMovieSelect} initialType={libraryInitialType} />)} 
      {currentView === 'leaderboard' && (<Leaderboard onMovieSelect={handleMovieSelect} />)} 
      {currentView === 'history' && (<HistoryPage history={history} onMovieSelect={handleMovieSelect} onClearHistory={handleClearHistory} onDeleteHistoryItem={handleDeleteHistoryItem} />)} 
      {currentView === 'profile' && (<ProfilePage settings={settings} setSettings={setSettings} favorites={favorites} onToggleFavorite={handleToggleFavorite} onMovieSelect={handleMovieSelect} currentTheme={themeName} setTheme={setThemeName} />)} 
      {currentView === 'search' && (<SearchResults query={searchQuery} results={searchResults} onMovieSelect={handleMovieSelect} />)} 

      {currentView === 'detail' && selectedMovie && (
        <MovieDetail movie={selectedMovie} history={history} onBack={() => setCurrentView('home')} 
          onPlay={(options = {}) => { setPlayOptions(options); setCurrentView('player'); }} 
          onMovieSelect={handleMovieSelect} 
          isFavorite={favorites.some(f => f.id === selectedMovie.id)} 
          onToggleFavorite={handleToggleFavorite} 
        />
      )} 

      {currentView === 'player' && selectedMovie && (
        <Player movie={selectedMovie} initialOptions={playOptions} onBack={() => {
            setCurrentView('detail');
            // Refresh history immediately after playing so Resume button updates
            userService.getHistory().then(setHistory);
        }} />
      )} 

      {currentView !== 'player' && <Footer />} 
    </div>
  ); 
}; 

export default App;

import React, { useState, useEffect, useMemo } from 'react';
import { ChevronLeft, PlayCircle, Plus, Download, Share2, Star, User, RotateCcw, FileVideo, Play, Cpu, HardDrive, Music, Box, Monitor, Activity } from 'lucide-react';
import { Movie, PlayOptions, HistoryItem } from '../types';
import { movieService } from '../services/api';
import { formatBytes, formatDuration } from '../utils';
import { MovieCard } from '../components/movies/Cards';

interface MovieDetailProps {
  movie: Movie;
  history: HistoryItem[];
  onBack: () => void;
  onPlay: (options: PlayOptions) => void;
  onMovieSelect: (m: Movie) => void;
  isFavorite: boolean;
  onToggleFavorite: (m: Movie) => void;
}

export const MovieDetail: React.FC<MovieDetailProps> = ({ movie, history, onBack, onPlay, onMovieSelect, isFavorite, onToggleFavorite }) => { 
  const [fullMovieData, setFullMovieData] = useState<Movie>(movie);
  const [loading, setLoading] = useState(false);

  // Fetch detailed info (resources) when movie changes
  useEffect(() => {
    const fetchDetail = async () => {
      setLoading(true);
      const detail = await movieService.getDetail(movie.id);
      if (detail) {
        setFullMovieData(detail);
      }
      setLoading(false);
    };
    fetchDetail();
    window.scrollTo(0, 0);
  }, [movie.id]);

  const safeId = String(fullMovieData.id || 'def');
  const hue = parseInt(safeId.split('-').pop() || '0') * 40; 

  // Resources check
  const hasResources = fullMovieData.resources && fullMovieData.resources.length > 0;
  const primaryResource = hasResources ? fullMovieData.resources![0] : null;

  // Calculate Resume Record
  // We look for any history item that matches one of the resources of this movie
  // Since history is typically sorted by recent, the first match is the last watched episode
  const resumeRecord = useMemo(() => {
    if (!history || !fullMovieData.resources) return null;

    // Create a set of resource IDs belonging to this movie
    const movieResourceIds = new Set(fullMovieData.resources.map(r => r.id));

    // Find the first history item that exists in this movie's resources
    const match = history.find(h => movieResourceIds.has(h.resourceId));

    // Only resume if progress is meaningful (>5s) and not effectively finished (>95%)
    if (match && match.progress > 5 && match.duration > 0 && (match.progress / match.duration) < 0.95) {
        // Enhance match with the filename from resources for display
        const resourceDetail = fullMovieData.resources.find(r => r.id === match.resourceId);
        return {
            ...match,
            filename: resourceDetail?.filename || 'Unknown File'
        };
    }
    return null;
  }, [history, fullMovieData]);

  const handlePlay = () => {
    if (primaryResource) {
      onPlay({ resourceId: primaryResource.id });
    }
  };

  const handleResume = () => {
    if (resumeRecord) {
        onPlay({ 
            resourceId: resumeRecord.resourceId, 
            startTime: resumeRecord.progress 
        });
    }
  };

  const techSpecs = fullMovieData.tech_specs || {}; 

  return (
    <div className="relative min-h-screen w-full text-white pt-24 pb-12 overflow-hidden"> 
      {/* Immersive Backdrop Background */}
      <div className="absolute inset-0 z-0"> 
          {/* Background Color Base */}
          <div className="absolute inset-0 bg-[#050505]"></div>

          {fullMovieData.backdrop_url ? (
            <>
                {/* High Res Backdrop Image */}
                <div 
                    className="absolute inset-0 bg-cover bg-top transition-opacity duration-1000" 
                    style={{ 
                        backgroundImage: `url(${fullMovieData.backdrop_url})`,
                        opacity: 0.5 
                    }}
                ></div>

                {/* Gradient Overlay - Bottom Fade (Seamless blend to footer/content) */}
                <div className="absolute inset-0 bg-gradient-to-t from-[#050505] via-[#050505]/80 to-transparent via-60%"></div>

                {/* Gradient Overlay - Left Fade (Make text readable) */}
                <div className="absolute inset-0 bg-gradient-to-r from-[#050505] via-[#050505]/70 to-transparent via-50%"></div>

                {/* Gradient Overlay - Top Fade (Navbar visibility) */}
                <div className="absolute top-0 left-0 right-0 h-32 bg-gradient-to-b from-[#050505]/90 to-transparent"></div>
            </>
          ) : (
            /* Fallback Abstract Gradient if no backdrop */
            <>
                <div className="absolute inset-0 opacity-20" style={{ backgroundImage: `radial-gradient(circle at 70% 20%, hsla(${hue}, 70%, 50%, 0.3), transparent 60%)`, }}></div>
                <div className="absolute inset-0 bg-gradient-to-t from-[#050505] via-[#050505]/80 to-transparent"></div>
            </>
          )}
      </div> 

      <div className="container mx-auto px-6 md:px-12 relative z-10"> 
        <button onClick={onBack} className="group flex items-center gap-2 text-gray-400 hover:text-primary mb-8 transition-colors"> <ChevronLeft className="group-hover:-translate-x-1 transition-transform" /> <span className="font-['Rajdhani'] font-bold tracking-wider">RETURN TO GRID</span> </button> 

        <div className="flex flex-col lg:flex-row gap-12 mb-20"> 
            <div className="w-full lg:w-1/3 flex flex-col gap-6"> 
