import React, { useState, useEffect, useMemo, useRef, useCallback } from 'react';
import { Filter, Cpu, Globe, Calendar, AlertTriangle, Loader2 } from 'lucide-react';
import { MovieCard } from '../components/movies/Cards';
import { Movie, Genre } from '../types';
import { FILTERS } from '../constants';
import { FilterTag } from '../components/ui/CyberComponents';
import { movieService } from '../services/api';

export const Library = ({ onMovieSelect, initialType = "全部类型" }: { onMovieSelect: (m: Movie) => void; initialType?: string }) => { 
  const [filters, setFilters] = useState({ type: initialType, region: "全部地区", year: "全部年份", sort: "更新时间" }); 
  const [libraryMovies, setLibraryMovies] = useState<Movie[]>([]);
  const [page, setPage] = useState(1);
  const [pageSize, setPageSize] = useState(0);
  const [hasMore, setHasMore] = useState(true);
  const [isLoading, setIsLoading] = useState(false);
  const [genres, setGenres] = useState<Genre[]>([]);
  const observer = useRef<IntersectionObserver | null>(null);

  useEffect(() => { setFilters(prev => ({ ...prev, type: initialType })); }, [initialType]); 

  // Fetch available genres on mount
  useEffect(() => {
    const fetchGenres = async () => {
      try {
        const data = await movieService.getGenres();

        // Filter: Remove specific unwanted genres per user request
        const bannedGenres = [
            "Sci-Fi & Fantasy", "动作冒险", "音乐", "电视电影",
            "Action & Adventure", "Music", "TV Movie", "Kids", "News", "Reality", "Soap", "Talk", "Politics"
        ];

        let processed = data.filter(g => !bannedGenres.includes(g.name));
        processed = processed.map(g => g.name === 'Local' ? { ...g, name: '其他' } : g);

        const hasSubstantialData = processed.filter(g => g.name !== '其他').length > 0;

        if (!hasSubstantialData) {
            const defaults = FILTERS.types.slice(1).map(name => ({ name, slug: name, count: 0 }));
            const others = processed.find(g => g.name === '其他');
            processed = defaults;
            if (others) processed.push(others);
        } else {
            processed.sort((a, b) => {
                if (a.name === '其他') return 1;
                if (b.name === '其他') return -1;
                return 0;
            });
        }
        setGenres(processed);
      } catch (e) {
        console.error("Failed to fetch genres", e);
        setGenres(FILTERS.types.slice(1).map(name => ({ name, slug: name, count: 0 })));
      }
    };
    fetchGenres();
  }, []);

  // Calculate dynamic page size
  useEffect(() => {
    const calculateSize = () => {
      const width = window.innerWidth;
      const cols = width >= 1280 ? 6 : width >= 1024 ? 5 : width >= 768 ? 4 : 2;
      const padding = width >= 768 ? 96 : 32; 
      const contentWidth = width - padding;
      const cardWidth = contentWidth / cols;
      const cardHeight = cardWidth * 1.5; 
      const rows = Math.ceil(window.innerHeight / cardHeight) + 1;
      const needed = cols * rows;
      setPageSize(Math.max(needed, 20));
    };
    calculateSize();
  }, []);

  // Reset list ONLY when server-side filters change (Type, Sort)
  // Changing Region or Year does NOT trigger this, ensuring we keep current data
  useEffect(() => {
    setPage(1);
    setLibraryMovies([]);
    setHasMore(true);
  }, [filters.type, filters.sort]);

  // Fetch movies from Backend
  useEffect(() => {
    if (pageSize === 0) return;

    const fetchMovies = async () => {
      setIsLoading(true);
      try {
        let genreParam: string | undefined = undefined;
        if (filters.type !== "全部类型") {
           const matchedGenre = genres.find(g => g.name === filters.type);
           genreParam = matchedGenre ? matchedGenre.slug : filters.type;
        }

        let sortBy = 'date_added';
        let order = 'desc';
        if (filters.sort === "综合评分") {
           sortBy = 'rating';
        } else if (filters.sort === "上映年份") {
           sortBy = 'year';
        } else if (filters.sort === "标题") {
           sortBy = 'title';
           order = 'asc';
        }

        // Backend call only uses genre and sort, ignoring region/year
        const res = await movieService.getAll(pageSize, page, genreParam, sortBy, order);

        setLibraryMovies(prev => {
          if (page === 1) return res.items;
          const existingIds = new Set(prev.map(m => m.id));
          const newItems = res.items.filter(m => !existingIds.has(m.id));
          return [...prev, ...newItems];
        });

        if (res.meta) {
          setHasMore(res.meta.current_page < res.meta.total_pages);
        } else {
          setHasMore(res.items.length === pageSize);
        }
      } catch (error) {
        console.error("Failed to fetch library", error);
      } finally {
        setIsLoading(false);
      }
    };
    fetchMovies();
  }, [page, pageSize, filters.type, filters.sort, genres]); 

  // Client-side Filtering Logic (Region & Year)
  // This runs purely on the frontend against the 'libraryMovies' array
  const displayedMovies = useMemo(() => { 
    let result = [...libraryMovies]; 

    // 1. Region Filter
    if (filters.region !== "全部地区") { 
      const targetRegion = filters.region;
      result = result.filter(m => { 
        // Logic: Check if the movie's inferred region matches the filter
        // Also check raw tags just in case
        const regionStr = (m.region || "其他");
        const tags = (m.tags || []).join(' ');

        if (targetRegion === "其他") {
            return regionStr === "其他" || regionStr === "Other";
        }
        return regionStr.includes(targetRegion) || tags.includes(targetRegion);
      }); 
    } 

    // 2. Year Filter
    if (filters.year !== "全部年份") { 
      if (filters.year === "更早") { 
        result = result.filter(m => m.year < 2020); 
      } else { 
        result = result.filter(m => String(m.year) === filters.year); 
      } 
    } 

    return result; 
  }, [libraryMovies, filters]); 

  // Infinite Scroll Ref
  const lastMovieRef = useCallback((node: HTMLDivElement) => {
    if (isLoading) return;
    if (observer.current) observer.current.disconnect();
    observer.current = new IntersectionObserver(entries => {
      if (entries[0].isIntersecting && hasMore) {
        setPage(prev => prev + 1);
      }
    });
    if (node) observer.current.observe(node);
  }, [isLoading, hasMore]);

  const displayGenres = ["全部类型", ...genres.map(g => g.name)];

  return (
    <div className="min-h-screen w-full pt-24 px-4 md:px-12 pb-12"> 
      <div className="flex items-center gap-4 mb-8"> 
        <div className="p-2 border border-primary text-primary shadow-[0_0_10px_var(--color-primary)]"> <Filter className="w-6 h-6" /> </div> 
        <h1 className="text-3xl font-['Orbitron'] font-bold text-white tracking-widest"> DATABASE <span className="text-primary">ARCHIVES</span> </h1> 
        <div className="flex-grow h-[1px] bg-gradient-to-r from-primary/50 to-transparent"></div> 
      </div> 

      {/* Filter Control Panel */}
      <div className="bg-[#0a0a12]/80 border border-white/10 backdrop-blur-md p-6 mb-10 relative overflow-hidden group tech-border"> 
        <div className="absolute top-0 right-0 w-16 h-16 border-t-2 border-r-2 border-red-500/50"></div> 
        <div className="space-y-4 relative z-10"> 
          {/* Genre Filter (Triggers Fetch) */}
          <div className="flex flex-col md:flex-row md:items-center gap-2 md:gap-4"> 
            <span className="text-primary font-['Noto_Sans_SC'] font-bold py-1 min-w-[4rem] flex items-center gap-2"> <Cpu size={14} /> 类型 </span> 
            <div className="flex flex-wrap gap-2"> {displayGenres.map(type => (<FilterTag key={type} label={type} active={filters.type === type} onClick={() => setFilters({ ...filters, type: type })} />))} </div> 
          </div> 
          <div className="h-[1px] bg-white/5 w-full"></div> 

          {/* Region Filter (Client Side Only) */}
          <div className="flex flex-col md:flex-row md:items-center gap-2 md:gap-4"> 
            <span className="text-secondary font-['Noto_Sans_SC'] font-bold py-1 min-w-[4rem] flex items-center gap-2"> <Globe size={14} /> 地区 </span> 
            <div className="flex flex-wrap gap-2"> {FILTERS.regions.map(region => (<FilterTag key={region} label={region} active={filters.region === region} onClick={() => setFilters({ ...filters, region: region })} />))} </div> 
          </div> 
          <div className="h-[1px] bg-white/5 w-full"></div> 

          {/* Year Filter (Client Side Only) */}
          <div className="flex flex-col md:flex-row md:items-center gap-2 md:gap-4"> 
            <span className="text-accent font-['Noto_Sans_SC'] font-bold py-1 min-w-[4rem] flex items-center gap-2"> <Calendar size={14} /> 年份 </span> 
            <div className="flex flex-wrap gap-2"> {FILTERS.years.map(year => (<FilterTag key={year} label={year} active={filters.year === year} onClick={() => setFilters({ ...filters, year: year })} />))} </div> 
          </div> 
        </div> 
      </div> 

      {/* List Header */}
      <div className="flex flex-col md:flex-row justify-between items-end md:items-center mb-6 font-['Rajdhani'] gap-4"> 
        <div className="text-gray-400 text-sm flex items-center gap-2"> 
          DISPLAYING <span className="text-primary font-bold text-lg">{displayedMovies.length}</span> FILES 
          {filters.region !== "全部地区" || filters.year !== "全部年份" ? (
             <span className="text-xs text-orange-400 border border-orange-500/30 px-1 rounded">FILTERED (LOCAL)</span>
          ) : (
             <span className="text-xs opacity-50">/ TOTAL LOADED {libraryMovies.length}</span>
          )}
        </div> 
        <div className="flex items-center gap-2 bg-black/40 border border-white/10 px-2 py-1 rounded-sm"> 
          {FILTERS.sorts.map(sort => (<button key={sort.id} onClick={() => setFilters({ ...filters, sort: sort.id })} className={`px-3 py-1 text-sm flex items-center gap-1 hover:text-primary transition-colors relative ${filters.sort === sort.id ? 'text-primary font-bold' : 'text-gray-500'}`} > {sort.label} {filters.sort === sort.id && <div className="absolute bottom-0 left-0 w-full h-[2px] bg-primary shadow-[0_0_5px_var(--color-primary)]"></div>} </button>))} 
        </div> 
      </div> 

      {/* Movie Grid */}
      <div className="grid grid-cols-2 md:grid-cols-4 lg:grid-cols-5 xl:grid-cols-6 gap-6"> 
        {displayedMovies.map((movie, index) => {
           // We keep infinite scroll active even when filtering client side, 
           // allowing user to load more data from backend into the "pool" which is then filtered.
           if (index === displayedMovies.length - 1) {
             return <div key={movie.id} ref={lastMovieRef}><MovieCard movie={movie} category={{ colorClass: 'border-white/20' }} onClick={onMovieSelect} /></div>;
           }
           return <MovieCard key={movie.id} movie={movie} category={{ colorClass: 'border-white/20' }} onClick={onMovieSelect} />;
        })} 
      </div>

      {isLoading && (
        <div className="w-full flex flex-col items-center justify-center py-8 gap-2">
          <Loader2 className="w-8 h-8 text-primary animate-spin" />
          <span className="text-xs font-['Orbitron'] text-primary animate-pulse">SCANNING_ARCHIVES...</span>
        </div>
      )}

      {!isLoading && displayedMovies.length === 0 && (
        <div className="h-96 w-full flex flex-col items-center justify-center gap-4 text-gray-600 border border-white/5 bg-black/20"> 
          <AlertTriangle size={48} className="opacity-30" /> 
          <div className="font-['Orbitron'] tracking-widest text-xl">NO DATA MATCHED</div> 
          <div className="text-xs font-sans">当前加载的资源中未找到匹配项 (尝试向下滚动加载更多)</div> 
        </div>
      )}

      {!hasMore && displayedMovies.length > 0 && (
        <div className="w-full text-center py-8 text-gray-600 font-['Rajdhani'] text-xs tracking-widest">END OF ARCHIVE</div>
      )}
    </div>
  ); 
};

import { API_BASE } from '../constants';
import { Movie, Episode, HistoryItem, Notification, Resource, Genre, TechSpecs } from '../types';
import { formatBytes } from '../utils';

// Types defining the raw API response structure based on openapi.json
interface ApiResponse<T> {
  code: number;
  msg: string;
  trace_id?: string;
  data: T;
}

interface ApiPagination {
  current_page: number;
  page_size: number;
  total_items: number;
  total_pages: number;
}

interface ApiMovieSimple {
  id: string;
  title: string;
  poster_url?: string;
  rating?: number;
  year?: number;
  source_ids?: number[];
  genres?: string[];
  user_data?: {
      is_played?: boolean;
      last_played_at?: string;
  };
  // Allow loose typing for fields that might exist in backend but not spec yet
  [key: string]: any; 
}

interface ApiMovieDetailed extends ApiMovieSimple {
  original_title?: string;
  overview?: string;
  backdrop_url?: string;
  resources?: Resource[];
}

async function fetchApi<T>(path: string, options?: RequestInit): Promise<T | null> {
  try {
    const res = await fetch(`${API_BASE}${path}`, options);
    if (!res.ok) {
      console.warn(`API Error ${res.status} on ${path}`);
      return null;
    }
    const json: ApiResponse<T> = await res.json();
    if (json.code !== 200) {
      console.warn(`API Business Error ${json.code}: ${json.msg}`);
      return null;
    }
    return json.data;
  } catch (error) {
    console.error(`Network Error on ${path}`, error);
    return null;
  }
}

// Helper to infer metadata from text content
const inferMetadata = (title: string = '', overview: string = '') => {
  const safeTitle = title || '';
  const safeOverview = overview || '';
  const text = (safeTitle + ' ' + safeOverview).toLowerCase();

  const types = [];
  if (/sci-fi|space|future|alien|robot|cyber|star|planet|未来|太空|外星|科幻|赛博/.test(text)) types.push('科幻');
  if (/action|fight|battle|war|kill|gun|hero|动作|战斗|战争/.test(text)) types.push('动作');
  if (/love|romance|kiss|heart|爱情|恋爱/.test(text)) types.push('剧情');
  if (/anime|manga|cartoon|animation|动画|动漫/.test(text)) types.push('动画');
  if (/thriller|horror|ghost|scary|惊悚|恐怖|悬疑/.test(text)) types.push('惊悚');

  const regions = [];
  if (/china|chinese|mandarin|cantonese|中国|华语/.test(text)) regions.push('中国');
  if (/hong kong|hk|香港/.test(text)) regions.push('中国'); // Group HK into CN for simple filter, or keep separate if needed
  if (/taiwan|tw|台湾/.test(text)) regions.push('中国');
  if (/japan|japanese|tokyo|日本|日语/.test(text)) regions.push('日本');
  if (/korea|korean|seoul|韩国|韩语/.test(text)) regions.push('韩国');
  if (/usa|america|hollywood|new york|美国|美剧/.test(text)) regions.push('美国');
  if (/uk|united kingdom|britain|london|英国|英剧/.test(text)) regions.push('英国');

  const mainType = types[0] || '剧情';
  // Ensure the main type is present in tags
  const finalTags = [...types];
  if (!finalTags.includes(mainType)) {
    finalTags.push(mainType);
  }

  return {
    type: mainType, // Default to Drama
    tags: [...finalTags, ...regions, 'HD'],
    region: regions[0] || '其他'
  };
};

// Helper to parse duration from various formats to seconds
const parseDuration = (val: string | number | undefined): number => {
  if (val === undefined || val === null) return 0;
  if (typeof val === 'number') {
    return isNaN(val) ? 0 : val;
  }
  const str = String(val).trim().toUpperCase();
  if (str === 'N/A' || str === '') return 0;

  // Try to find a number at the start
  const match = str.match(/^(\d+(\.\d+)?)/);
  if (!match) return 0;

  let num = parseFloat(match[1]);

  // Check units
  if (str.includes('MIN')) {
    num *= 60;
  } else if (str.includes('H') && !str.includes('MIN')) { 
     // Handle "2H" or similar if needed, though MIN is standard in this app
     num *= 3600;
  }
  // If no unit, assume seconds if it's from API logic, but if from constants mock it might be mixed.
  // Assuming raw number in string is seconds unless MIN specified.

  return Math.floor(num);
};

// Adapter to convert API format to UI Movie format
const mapApiMovieToUi = (apiMovie: ApiMovieSimple | ApiMovieDetailed): Movie => {
  const isDetailed = (m: any): m is ApiMovieDetailed => 'resources' in m;

  const safeTitle = apiMovie.title || 'Unknown Title';

  // Use explicit genres from API if available, otherwise fallback to inference
  let type = apiMovie.type;
  let tags = apiMovie.tags || [];
  let region = apiMovie.region;

  if (apiMovie.genres && apiMovie.genres.length > 0) {
    // If API provides genres, use them primarily
    tags = [...apiMovie.genres, ...tags];
    if (!type) type = apiMovie.genres[0];
  }

  // Fallback if still missing info
  if (!type || tags.length === 0 || !region) {
      const inferred = inferMetadata(safeTitle, isDetailed(apiMovie) ? apiMovie.overview : '');
      if (!type) type = inferred.type;
      if (tags.length === 0) tags = inferred.tags;
      if (!region) region = inferred.region;
  }

  // Deduplicate tags
  tags = Array.from(new Set(tags));

  // Build Tech Specs from Resource info if detailed
  let techSpecs: TechSpecs = { resolution: 'HD' };
  if (isDetailed(apiMovie) && apiMovie.resources && apiMovie.resources.length > 0) {
      const bestRes = apiMovie.resources[0]; // Assuming first is best
      if (bestRes.media_info) {
          techSpecs = {
              resolution: bestRes.media_info.resolution || 'HD',
              codec: bestRes.media_info.video_codec?.toUpperCase(),
              audio: bestRes.media_info.audio_codec?.toUpperCase(),
              bitrate: bestRes.media_info.bitrate ? `${(bestRes.media_info.bitrate / 1000).toFixed(1)} Mbps` : undefined,
              container: bestRes.container?.toUpperCase(),
              size: bestRes.size_bytes ? formatBytes(bestRes.size_bytes) : undefined
          };
      } else if (bestRes.quality_label) {
          techSpecs.resolution = bestRes.quality_label;
      }
  } else if (apiMovie.tech_specs) {
      // Legacy or pre-computed field support
      techSpecs = apiMovie.tech_specs;
  }

  return {
    id: apiMovie.id || `unknown-${Math.random()}`,
    title: safeTitle,
    original_title: isDetailed(apiMovie) ? apiMovie.original_title : undefined,
    rating: apiMovie.rating ? Number(apiMovie.rating).toFixed(1) : '0.0',
    year: apiMovie.year || new Date().getFullYear(),
    cover_url: apiMovie.poster_url || '', // Map poster to cover
    poster_url: apiMovie.poster_url,
    backdrop_url: isDetailed(apiMovie) ? apiMovie.backdrop_url : undefined,
    desc: isDetailed(apiMovie) ? apiMovie.overview : '',
    overview: isDetailed(apiMovie) ? apiMovie.overview : '',
    resources: isDetailed(apiMovie) ? apiMovie.resources : [],
    duration: apiMovie.duration || 'N/A', 
    tags: tags,
    type: type,
    region: region,
    views: 'N/A',
    isPlayed: apiMovie.user_data?.is_played || false,
    lastPlayedAt: apiMovie.user_data?.last_played_at,
    tech_specs: techSpecs
  };
};

const getDeviceId = () => {
    let id = localStorage.getItem('cyber_device_id');
    if (!id) {
        id = crypto.randomUUID();
        localStorage.setItem('cyber_device_id', id);
    }
    return id;
};

export const movieService = {
  getAll: async (limit = 20, page = 1, genre?: string, sort_by?: string, order?: string): Promise<{ items: Movie[], meta?: ApiPagination }> => {
    let url = `/api/v1/movies?page=${page}&page_size=${limit}`;
    if (genre) {
      url += `&genre=${encodeURIComponent(genre)}`;
    }
    if (sort_by) {
      url += `&sort_by=${encodeURIComponent(sort_by)}`;
    }
    if (order) {
      url += `&order=${encodeURIComponent(order)}`;
    }

    const data = await fetchApi<{ items: ApiMovieSimple[], pagination: ApiPagination }>(url);
    if (!data) return { items: [] };

    return {
      items: data.items.map(mapApiMovieToUi),
      meta: data.pagination
    };
  },

  getGenres: async (): Promise<Genre[]> => {
    const data = await fetchApi<Genre[]>('/api/v1/genres');
    return data || [];
  },

  // Since /movies/top doesn't exist in OpenAPI, we assume using the general list 
  // Client-side sorting will be needed if backend doesn't support sort param (not in spec)
  getTop: async (type: string, limit = 15): Promise<Movie[]> => {
    const data = await fetchApi<{ items: ApiMovieSimple[] }>(`/api/v1/movies?page_size=${limit}`);
    if (!data) return [];
    // Mock sort by rating for "HOT" since API doesn't have sort param yet
    return data.items.map(mapApiMovieToUi).sort((a, b) => parseFloat(b.rating) - parseFloat(a.rating));
  },

  // Server-side search using the 'keyword' parameter from /api/v1/movies endpoint
  search: async (query: string): Promise<Movie[]> => {
    const data = await fetchApi<{ items: ApiMovieSimple[] }>(`/api/v1/movies?keyword=${encodeURIComponent(query)}&page_size=50`);
    if (!data) return [];
    return data.items.map(mapApiMovieToUi);
  },

  getDetail: async (id: string | number): Promise<Movie | null> => {
    const data = await fetchApi<ApiMovieDetailed>(`/api/v1/movies/${id}`);
    if (!data) return null;
    return mapApiMovieToUi(data);
  },

  // Recommend not in API, return empty or random from list
  getRecommendations: async (path: string, id: string | number): Promise<Movie[]> => {
    return [];
  },

  // Helper to construct stream URL
  getStreamUrl: (resourceId: string): string => {
    return `${API_BASE}/api/v1/resources/${resourceId}/stream`;
  }
};

export const userService = {
  getHistory: async (): Promise<HistoryItem[]> => {
    const data = await fetchApi<any>('/api/v1/user/history');
    if (!data) return [];

    let items: any[] = [];
    // API might return array directly OR { items: [...] } OR { data: [...] }
    if (Array.isArray(data)) {
        items = data;
    } else if (typeof data === 'object') {
        if (Array.isArray(data.items)) items = data.items;
        else if (Array.isArray(data.data)) items = data.data;
    }

    return items.map(item => {
      // Robustly handle various backend response shapes
      const movieInfo = item.movie || item; 
      // Map base movie info
      const movie = mapApiMovieToUi(movieInfo);

      const updatedAt = item.updated_at || item.created_at || new Date().toISOString();
      let dateObj = new Date(updatedAt);
      if (isNaN(dateObj.getTime())) dateObj = new Date();

      // Parse duration: prioritise history item's duration (usually seconds), fallback to movie metadata
      let duration = 0;
      if (item.duration) {
         duration = parseDuration(item.duration);
      } else {
         duration = parseDuration(movie.duration);
      }

      const progress = Number(item.progress || item.position_sec || 0);

      return {
        ...movie,
        // Keep resource_id specifically for history deletion
        resourceId: item.resource_id, 
        progress: progress,
        duration: duration, 
        time_str: dateObj.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
        date: dateObj.toLocaleDateString(),
        updated_at: updatedAt
      };
    }).sort((a, b) => new Date(b.updated_at!).getTime() - new Date(a.updated_at!).getTime());
  },

  clearHistory: async (): Promise<void> => {
    try {
      await fetch(`${API_BASE}/api/v1/user/history`, { method: 'DELETE' });
    } catch (e) { console.error(e); }
  },

  deleteHistoryItem: async (resourceId: string): Promise<void> => {
    try {
      await fetch(`${API_BASE}/api/v1/user/history/${resourceId}`, { method: 'DELETE' });
    } catch (e) { console.error(e); }
  },

  reportHistory: async (resourceId: string, positionSec: number, totalDuration: number) => {
    try {
      await fetch(`${API_BASE}/api/v1/user/history`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          resource_id: resourceId,
          position_sec: Math.floor(positionSec),
          total_duration: Math.floor(totalDuration),
          device_id: getDeviceId(),
          device_name: navigator.userAgent
        })
      });
    } catch (e) { console.error(e); }
  },

  getVault: async (): Promise<Movie[]> => {
    // Not in OpenAPI, return empty or mock
    return [];
  },

  toggleFavorite: async (movie: Movie) => {
    // Not in OpenAPI
    console.warn("Vault API not available in current spec");
  }
};

