      setIsLoading(true);
      try {
        // Map UI filter labels to API params
        let genreParam: string | undefined = undefined;
        if (filters.type !== "全部类型") {
           genreParam = filters.type;
        }

        let sortBy = 'date_added';
        let order = 'desc';
        if (filters.sort === "综合评分") {
           sortBy = 'rating';
