      )}
    </div>
  ); 
};

import React, { useMemo } from 'react';
import { Cpu, Globe, Calendar } from 'lucide-react';
import { FilterTag } from '../ui/CyberComponents';

// Mapping for API region names to Chinese
const REGION_NAME_MAP: Record<string, string> = {
  "United States of America": "美国",
  "United States": "美国",
  "United Kingdom": "英国",
  "China": "中国",
  "Japan": "日本",
  "South Korea": "韩国",
  "Korea": "韩国",
  "France": "法国",
  "Germany": "德国",
  "Canada": "加拿大",
  "Australia": "澳大利亚",
  "India": "印度",
  "Russia": "俄罗斯",
  "Thailand": "泰国",
  "Hong Kong": "中国香港",
  "Taiwan": "中国台湾",
  "Italy": "意大利",
  "Spain": "西班牙",
  "Brazil": "巴西",
  "Sweden": "瑞典",
  "Unknown": "未知",
  "Other": "其他"
};

// Mapping for API genre names to Chinese or UI display names
const GENRE_DISPLAY_MAP: Record<string, string> = {
  "Local": "本地"
};

interface FilterPanelProps {
  rawGenres: string[];
  rawRegions: string[];
  rawYears: string[];
  activeFilters: {
    type: string;
    region: string;
    year: string;
  };
  onFilterChange: (key: 'type' | 'region' | 'year', value: string) => void;
}

export const FilterPanel: React.FC<FilterPanelProps> = ({ 
  rawGenres, 
  rawRegions, 
  rawYears, 
  activeFilters, 
  onFilterChange 
}) => {

  // Logic 1: Process Genres (Filter unwanted, Rename/Move Local)
  const processedGenres = useMemo(() => {
    let genres = [...rawGenres];

    // Filter out unwanted genres locally
    const unwantedGenres = ["电视电影", "音乐", "Sci-Fi & Fantasy", "动作冒险"];
    genres = genres.filter(g => !unwantedGenres.includes(g));

    // Move "Local" to the end
    const localIndex = genres.indexOf("Local");
    if (localIndex !== -1) {
      genres.splice(localIndex, 1);
      genres.push("Local");
    }

    return ["全部类型", ...genres];
  }, [rawGenres]);

  // Logic 2: Process Regions (Move Unknown to end)
  const processedRegions = useMemo(() => {
    let regions = [...rawRegions];

    const unknownIndex = regions.indexOf("Unknown");
    if (unknownIndex !== -1) {
        regions.splice(unknownIndex, 1);
        regions.push("Unknown");
    }

    return ["全部地区", ...regions];
  }, [rawRegions]);

  // Logic 3: Process Years (Filter unreasonable, limit length)
  const processedYears = useMemo(() => {
    const currentYear = new Date().getFullYear();
    // Convert strings to numbers for comparison if needed, assuming API sends strings or numbers
    // Here we map to number first to be safe
    let years = rawYears.map(y => parseInt(String(y))).filter(n => !isNaN(n));

    // Filter unreasonable years
    years = years.filter(y => y >= 1880 && y <= currentYear + 1);

    // Sort descending
    years.sort((a, b) => b - a);

    // Limit display length
    const MAX_YEARS_DISPLAY = 25;
    const limitedYears = years.slice(0, MAX_YEARS_DISPLAY);

    return ["全部年份", ...limitedYears.map(String), "更早"];
  }, [rawYears]);

  return (
    <div className="bg-[#0a0a12]/80 border border-white/10 backdrop-blur-md p-6 mb-10 relative overflow-hidden group tech-border">
      <div className="absolute top-0 right-0 w-16 h-16 border-t-2 border-r-2 border-red-500/50"></div>
      <div className="space-y-4 relative z-10">
        {/* Genre Filter */}
        <div className="flex flex-col md:flex-row md:items-center gap-2 md:gap-4">
          <span className="text-primary font-['Noto_Sans_SC'] font-bold py-1 min-w-[4rem] flex items-center gap-2">
            <Cpu size={14} /> 类型
          </span>
          <div className="flex flex-wrap gap-2">
            {processedGenres.map(type => (
              <FilterTag 
                key={type} 
                label={GENRE_DISPLAY_MAP[type] || type} 
                active={activeFilters.type === type} 
                onClick={() => onFilterChange('type', type)} 
              />
            ))}
          </div>
        </div>
        <div className="h-[1px] bg-white/5 w-full"></div>

        {/* Region Filter */}
        <div className="flex flex-col md:flex-row md:items-center gap-2 md:gap-4">
          <span className="text-secondary font-['Noto_Sans_SC'] font-bold py-1 min-w-[4rem] flex items-center gap-2">
            <Globe size={14} /> 地区
          </span>
          <div className="flex flex-wrap gap-2">
            {processedRegions.map(region => (
              <FilterTag 
                key={region} 
                label={REGION_NAME_MAP[region] || region} 
                active={activeFilters.region === region} 
                onClick={() => onFilterChange('region', region)} 
              />
            ))}
          </div>
        </div>
        <div className="h-[1px] bg-white/5 w-full"></div>

        {/* Year Filter */}
        <div className="flex flex-col md:flex-row md:items-center gap-2 md:gap-4">
          <span className="text-accent font-['Noto_Sans_SC'] font-bold py-1 min-w-[4rem] flex items-center gap-2">
            <Calendar size={14} /> 年份
          </span>
          <div className="flex flex-wrap gap-2">
            {processedYears.map(year => (
              <FilterTag 
                key={year} 
                label={year} 
                active={activeFilters.year === year} 
                onClick={() => onFilterChange('year', year)} 
              />
            ))}
          </div>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect, useRef, useCallback, useMemo } from 'react';
import { Filter, AlertTriangle, Loader2, Search } from 'lucide-react';
import { MovieCard } from '../components/movies/Cards';
import { Movie } from '../types';
import { FILTERS } from '../constants';
import { movieService } from '../services/api';
import { FilterPanel } from '../components/library/FilterPanel';

export const Library = ({ onMovieSelect, initialType = "全部类型" }: { onMovieSelect: (m: Movie) => void; initialType?: string }) => { 
  const [filters, setFilters] = useState({ type: initialType, region: "全部地区", year: "全部年份", sort: "更新时间" }); 
  const [libraryMovies, setLibraryMovies] = useState<Movie[]>([]);
  const [page, setPage] = useState(1);
  const [pageSize, setPageSize] = useState(0);
  const [hasMore, setHasMore] = useState(true);
  const [isLoading, setIsLoading] = useState(false);
  const [localQuery, setLocalQuery] = useState(''); // New: Local filter query

  // Raw options from backend
  const [rawOptions, setRawOptions] = useState({
      genres: [] as string[],
      regions: [] as string[],
      years: [] as string[]
  });

  const observer = useRef<IntersectionObserver | null>(null);

  useEffect(() => { setFilters(prev => ({ ...prev, type: initialType })); }, [initialType]); 

  // Fetch global filters on mount
  useEffect(() => {
    const fetchFilters = async () => {
      try {
        const data = await movieService.getGlobalFilters();
        if (data) {
            setRawOptions({
                genres: data.genres.map(g => g.name),
                regions: data.countries.map(c => c.name),
                years: data.years.map(y => String(y.year))
            });
        } else {
            // Fallback
            setRawOptions({
                genres: FILTERS.types,
                regions: FILTERS.regions,
                years: FILTERS.years
            });
        }
      } catch (e) {
        console.error("Failed to fetch global filters", e);
        setRawOptions({
            genres: FILTERS.types,
            regions: FILTERS.regions,
            years: FILTERS.years
        });
      }
    };
    fetchFilters();
  }, []);

  // Calculate dynamic page size
  useEffect(() => {
    const calculateSize = () => {
      const width = window.innerWidth;
      const cols = width >= 1280 ? 6 : width >= 1024 ? 5 : width >= 768 ? 4 : 2;
      const padding = width >= 768 ? 96 : 32; 
      const contentWidth = width - padding;
      const cardWidth = contentWidth / cols;
      const cardHeight = cardWidth * 1.5; 
      const rows = Math.ceil(window.innerHeight / cardHeight) + 1;
      const needed = cols * rows;
      setPageSize(Math.max(needed, 20));
    };
    calculateSize();
  }, []);

  // Reset list when ANY filter changes (Server-side filtering logic)
  useEffect(() => {
    setPage(1);
    setLibraryMovies([]);
    setHasMore(true);
    setLocalQuery(''); // Reset local filter when fetching new category
  }, [filters]);

  // Fetch movies from Backend with all filters
  useEffect(() => {
    if (pageSize === 0) return;

    const fetchMovies = async () => {
      setIsLoading(true);
      try {
        let genreParam: string | undefined = undefined;
        if (filters.type !== "全部类型") {
           genreParam = filters.type;
        }

        let sortBy = 'date_added';
        let order = 'desc';
        if (filters.sort === "综合评分") {
           sortBy = 'rating';
        } else if (filters.sort === "上映年份") {
           sortBy = 'year';
        } else if (filters.sort === "标题") {
           sortBy = 'title';
           order = 'asc';
        }

        const res = await movieService.getAll(
            pageSize, 
            page, 
            genreParam, 
            sortBy, 
            order, 
            filters.region, 
            filters.year
        );

        setLibraryMovies(prev => {
          if (page === 1) return res.items;
          const existingIds = new Set(prev.map(m => m.id));
          const newItems = res.items.filter(m => !existingIds.has(m.id));
          return [...prev, ...newItems];
        });

        if (res.meta) {
          setHasMore(res.meta.current_page < res.meta.total_pages);
        } else {
          setHasMore(res.items.length === pageSize);
        }
      } catch (error) {
        console.error("Failed to fetch library", error);
      } finally {
        setIsLoading(false);
      }
    };
    fetchMovies();
  }, [page, pageSize, filters]); 

  // Infinite Scroll Ref
  const lastMovieRef = useCallback((node: HTMLDivElement) => {
    if (isLoading) return;
    if (observer.current) observer.current.disconnect();
    observer.current = new IntersectionObserver(entries => {
      if (entries[0].isIntersecting && hasMore) {
        setPage(prev => prev + 1);
      }
    });
    if (node) observer.current.observe(node);
  }, [isLoading, hasMore]);

  // Local Filtering Logic: Filter the ALREADY FETCHED movies
  const displayedMovies = useMemo(() => {
    if (!localQuery.trim()) return libraryMovies;
    const lowerQ = localQuery.toLowerCase();
    return libraryMovies.filter(m => 
      m.title.toLowerCase().includes(lowerQ) || 
      (m.year && String(m.year).includes(lowerQ))
    );
  }, [libraryMovies, localQuery]);

  return (
    <div className="min-h-screen w-full pt-24 px-4 md:px-12 pb-12"> 
      <div className="flex items-center gap-4 mb-8"> 
        <div className="p-2 border border-primary text-primary shadow-[0_0_10px_var(--color-primary)]"> <Filter className="w-6 h-6" /> </div> 
        <h1 className="text-3xl font-['Orbitron'] font-bold text-white tracking-widest"> DATABASE <span className="text-primary">ARCHIVES</span> </h1> 
        <div className="flex-grow h-[1px] bg-gradient-to-r from-primary/50 to-transparent"></div> 
      </div> 

      {/* Replaced inline logic with separated component */}
      <FilterPanel 
        rawGenres={rawOptions.genres}
        rawRegions={rawOptions.regions}
        rawYears={rawOptions.years}
        activeFilters={filters}
        onFilterChange={(key, value) => setFilters(prev => ({ ...prev, [key]: value }))}
      />

      {/* List Header with Local Filter Input */}
      <div className="flex flex-col md:flex-row justify-between items-end md:items-center mb-6 font-['Rajdhani'] gap-4"> 
        <div className="flex items-center gap-4 w-full md:w-auto">
             <div className="text-gray-400 text-sm flex items-center gap-2 whitespace-nowrap"> 
                当前展示 <span className="text-primary font-bold text-lg">{displayedMovies.length}</span> 个资源
            </div>
            {/* Local Quick Filter Input */}
            <div className="relative group w-full md:w-64">
                <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-500 group-focus-within:text-primary transition-colors" />
                <input 
                    type="text" 
                    value={localQuery}
                    onChange={(e) => setLocalQuery(e.target.value)}
                    placeholder="在此列表中二次筛选..." 
                    className="w-full bg-black/40 border border-white/10 rounded-sm py-1.5 pl-9 pr-3 text-xs text-white focus:border-primary focus:outline-none focus:shadow-[0_0_10px_var(--color-primary)] transition-all placeholder-gray-600 font-sans"
                />
            </div>
        </div>

        <div className="flex items-center gap-2 bg-black/40 border border-white/10 px-2 py-1 rounded-sm"> 
          {FILTERS.sorts.map(sort => (<button key={sort.id} onClick={() => setFilters({ ...filters, sort: sort.id })} className={`px-3 py-1 text-sm flex items-center gap-1 hover:text-primary transition-colors relative ${filters.sort === sort.id ? 'text-primary font-bold' : 'text-gray-500'}`} > {sort.label} {filters.sort === sort.id && <div className="absolute bottom-0 left-0 w-full h-[2px] bg-primary shadow-[0_0_5px_var(--color-primary)]"></div>} </button>))} 
        </div> 
      </div> 

      {/* Movie Grid */}
      <div className="grid grid-cols-2 md:grid-cols-4 lg:grid-cols-5 xl:grid-cols-6 gap-6"> 
        {displayedMovies.map((movie, index) => {
           // Only attach ref to the last item if we are NOT locally filtering (otherwise infinite scroll logic gets weird)
           if (index === displayedMovies.length - 1 && !localQuery) {
             return <div key={movie.id} ref={lastMovieRef}><MovieCard movie={movie} category={{ colorClass: 'border-white/20' }} onClick={onMovieSelect} /></div>;
           }
           return <MovieCard key={movie.id} movie={movie} category={{ colorClass: 'border-white/20' }} onClick={onMovieSelect} />;
        })} 
      </div>

      {isLoading && (
        <div className="w-full flex flex-col items-center justify-center py-8 gap-2">
          <Loader2 className="w-8 h-8 text-primary animate-spin" />
          <span className="text-xs font-['Orbitron'] text-primary animate-pulse">正在扫描归档...</span>
        </div>
      )}

      {!isLoading && displayedMovies.length === 0 && (
        <div className="h-96 w-full flex flex-col items-center justify-center gap-4 text-gray-600 border border-white/5 bg-black/20"> 
          <AlertTriangle size={48} className="opacity-30" /> 
          <div className="font-['Orbitron'] tracking-widest text-xl">无匹配数据</div> 
          <div className="text-xs font-sans">当前筛选条件下未找到相关资源</div> 
        </div>
      )}

      {!hasMore && displayedMovies.length > 0 && !localQuery && (
        <div className="w-full text-center py-8 text-gray-600 font-['Rajdhani'] text-xs tracking-widest">已加载全部资源</div>
      )}
    </div>
  ); 
};

