const REGION_NAME_MAP: Record<string, string> = {
  "United States of America": "美国",
  "United States": "美国",
  "United Kingdom": "英国",
  "China": "中国",
  "Japan": "日本",
  "South Korea": "韩国",
  "Korea": "韩国",
  "France": "法国",
  "Germany": "德国",
  "Canada": "加拿大",
