  useEffect(() => {
    setPage(1);
    setLibraryMovies([]);
    setHasMore(true);
  }, [filters.type, filters.region, filters.year]);

  // Fetch movies from Backend 
  // NOTE: 'sort' is removed from dependency to prevent re-fetch on sort change
  useEffect(() => {
    if (pageSize === 0) return;

    const fetchMovies = async () => {
      setIsLoading(true);
      try {
        // Map UI filter labels to API params
        let genreParam: string | undefined = undefined;
        if (filters.type !== "全部类型") {
           genreParam = filters.type;
        }

        // Always fetch sorted by date_added from server to maintain consistent pagination base
        // We will handle specific sorting (Rating/Year) locally
        const sortBy = 'date_added';
        const order = 'desc';

        const res = await movieService.getAll(
            pageSize, 
            page, 
            genreParam, 
            sortBy, 
            order, 
            filters.region, 
            filters.year
        );

        setLibraryMovies(prev => {
          if (page === 1) return res.items;
          const existingIds = new Set(prev.map(m => m.id));
          const newItems = res.items.filter(m => !existingIds.has(m.id));
          return [...prev, ...newItems];
        });

        if (res.meta) {
          setHasMore(res.meta.current_page < res.meta.total_pages);
        } else {
          setHasMore(res.items.length === pageSize);
        }
      } catch (error) {
        console.error("Failed to fetch library", error);
      } finally {
        setIsLoading(false);
      }
    };
    fetchMovies();
  }, [page, pageSize, filters.type, filters.region, filters.year]); 

  // Infinite Scroll Ref
  const lastMovieRef = useCallback((node: HTMLDivElement) => {
    if (isLoading) return;
    if (observer.current) observer.current.disconnect();
    observer.current = new IntersectionObserver(entries => {
      if (entries[0].isIntersecting && hasMore) {
        setPage(prev => prev + 1);
      }
    });
    if (node) observer.current.observe(node);
  }, [isLoading, hasMore]);

  // Local Sort Logic: Sort the accumulated list locally
  const sortedMovies = useMemo(() => {
    const movies = [...libraryMovies];

    if (filters.sort === 'rating') {
      // Sort by Rating Descending
      return movies.sort((a, b) => parseFloat(b.rating) - parseFloat(a.rating));
    } else if (filters.sort === 'year') {
      // Sort by Year Descending
      return movies.sort((a, b) => b.year - a.year);
    }

    // Default 'update_time' or others: keep order as received from server (which is date_added desc)
    return movies;
  }, [libraryMovies, filters.sort]);

  return (
    <div className="min-h-screen w-full pt-24 px-4 md:px-12 pb-12"> 
