import { API_BASE } from '../constants';
import { Movie, Episode, HistoryItem, Notification, Resource, Genre, TechSpecs, FilterDictionaries } from '../types';
import { formatBytes } from '../utils';

// Types defining the raw API response structure based on openapi.json
interface ApiResponse<T> {
  code: number;
  msg: string;
  trace_id?: string;
  data: T;
}

interface ApiPagination {
  current_page: number;
  page_size: number;
  total_items: number;
  total_pages: number;
}

interface ApiMovieSimple {
  id: string;
  title: string;
  poster_url?: string;
  rating?: number;
  year?: number;
  date_added?: string;
  source_ids?: number[];
  genres?: string[];
  user_data?: {
      is_played?: boolean;
      last_played_at?: string;
  };
  // Allow loose typing for fields that might exist in backend but not spec yet
  [key: string]: any; 
}

interface ApiMovieDetailed extends ApiMovieSimple {
  original_title?: string;
  overview?: string;
  backdrop_url?: string;
  resources?: Resource[];
}

async function fetchApi<T>(path: string, options?: RequestInit): Promise<T | null> {
  try {
    const res = await fetch(`${API_BASE}${path}`, options);
    if (!res.ok) {
      console.warn(`API Error ${res.status} on ${path}`);
      return null;
    }
    const json: ApiResponse<T> = await res.json();
    if (json.code !== 200) {
      console.warn(`API Business Error ${json.code}: ${json.msg}`);
      return null;
    }
    return json.data;
  } catch (error) {
    console.error(`Network Error on ${path}`, error);
    return null;
  }
}

// Helper to infer metadata from text content
const inferMetadata = (title: string = '', overview: string = '') => {
  const safeTitle = title || '';
  const safeOverview = overview || '';
  const text = (safeTitle + ' ' + safeOverview).toLowerCase();

  const types = [];
  if (/sci-fi|space|future|alien|robot|cyber|star|planet|未来|太空|外星|科幻|赛博/.test(text)) types.push('科幻');
  if (/action|fight|battle|war|kill|gun|hero|动作|战斗|战争/.test(text)) types.push('动作');
  if (/love|romance|kiss|heart|爱情|恋爱/.test(text)) types.push('剧情');
  if (/anime|manga|cartoon|animation|动画|动漫/.test(text)) types.push('动画');
  if (/thriller|horror|ghost|scary|惊悚|恐怖|悬疑/.test(text)) types.push('惊悚');

  const regions = [];
  if (/china|chinese|mandarin|cantonese|中国|华语/.test(text)) regions.push('中国');
  if (/hong kong|hk|香港/.test(text)) regions.push('中国'); // Group HK into CN for simple filter, or keep separate if needed
  if (/taiwan|tw|台湾/.test(text)) regions.push('中国');
  if (/japan|japanese|tokyo|日本|日语/.test(text)) regions.push('日本');
  if (/korea|korean|seoul|韩国|韩语/.test(text)) regions.push('韩国');
  if (/usa|america|hollywood|new york|美国|美剧/.test(text)) regions.push('美国');
  if (/uk|united kingdom|britain|london|英国|英剧/.test(text)) regions.push('英国');

  const mainType = types[0] || '剧情';
  // Ensure the main type is present in tags
  const finalTags = [...types];
  if (!finalTags.includes(mainType)) {
    finalTags.push(mainType);
  }

  return {
    type: mainType, // Default to Drama
    tags: [...finalTags, ...regions, 'HD'],
    region: regions[0] || '其他'
  };
};

// Helper to parse duration from various formats to seconds
const parseDuration = (val: string | number | undefined): number => {
  if (val === undefined || val === null) return 0;
  if (typeof val === 'number') {
    return isNaN(val) ? 0 : val;
  }
  const str = String(val).trim().toUpperCase();
  if (str === 'N/A' || str === '') return 0;

  // Try to find a number at the start
  const match = str.match(/^(\d+(\.\d+)?)/);
  if (!match) return 0;

  let num = parseFloat(match[1]);

  // Check units
  if (str.includes('MIN')) {
    num *= 60;
  } else if (str.includes('H') && !str.includes('MIN')) { 
     // Handle "2H" or similar if needed, though MIN is standard in this app
     num *= 3600;
  }
  // If no unit, assume seconds if it's from API logic, but if from constants mock it might be mixed.
  // Assuming raw number in string is seconds unless MIN specified.

  return Math.floor(num);
};

// Adapter to convert API format to UI Movie format
const mapApiMovieToUi = (apiMovie: ApiMovieSimple | ApiMovieDetailed): Movie => {
  const isDetailed = (m: any): m is ApiMovieDetailed => 'resources' in m;

  const safeTitle = apiMovie.title || 'Unknown Title';

  // Use explicit genres from API if available, otherwise fallback to inference
  let type = apiMovie.type;
  let tags = apiMovie.tags || [];
  let region = apiMovie.region;

  if (apiMovie.genres && apiMovie.genres.length > 0) {
    // If API provides genres, use them primarily
    tags = [...apiMovie.genres, ...tags];
    if (!type) type = apiMovie.genres[0];
  }

  // Fallback if still missing info
  if (!type || tags.length === 0 || !region) {
      const inferred = inferMetadata(safeTitle, isDetailed(apiMovie) ? apiMovie.overview : '');
      if (!type) type = inferred.type;
      if (tags.length === 0) tags = inferred.tags;
      if (!region) region = inferred.region;
  }

  // Deduplicate tags
  tags = Array.from(new Set(tags));

  // Build Tech Specs from Resource info if detailed
  let techSpecs: TechSpecs = { resolution: 'HD' };
  if (isDetailed(apiMovie) && apiMovie.resources && apiMovie.resources.length > 0) {
      const bestRes = apiMovie.resources[0]; // Assuming first is best
      if (bestRes.media_info) {
          techSpecs = {
              resolution: bestRes.media_info.resolution || 'HD',
              codec: bestRes.media_info.video_codec?.toUpperCase(),
              audio: bestRes.media_info.audio_codec?.toUpperCase(),
              bitrate: bestRes.media_info.bitrate ? `${(bestRes.media_info.bitrate / 1000).toFixed(1)} Mbps` : undefined,
              container: bestRes.container?.toUpperCase(),
              size: bestRes.size_bytes ? formatBytes(bestRes.size_bytes) : undefined
          };
      } else if (bestRes.quality_label) {
          techSpecs.resolution = bestRes.quality_label;
      }
  } else if (apiMovie.tech_specs) {
      // Legacy or pre-computed field support
      techSpecs = apiMovie.tech_specs;
  }

  return {
    id: apiMovie.id || `unknown-${Math.random()}`,
    title: safeTitle,
    original_title: isDetailed(apiMovie) ? apiMovie.original_title : undefined,
    rating: apiMovie.rating ? Number(apiMovie.rating).toFixed(1) : '0.0',
    year: apiMovie.year || new Date().getFullYear(),
    date_added: apiMovie.date_added, // Map date_added for sorting
    cover_url: apiMovie.poster_url || '', // Map poster to cover
    poster_url: apiMovie.poster_url,
    backdrop_url: isDetailed(apiMovie) ? apiMovie.backdrop_url : undefined,
    desc: isDetailed(apiMovie) ? apiMovie.overview : '',
    overview: isDetailed(apiMovie) ? apiMovie.overview : '',
    resources: isDetailed(apiMovie) ? apiMovie.resources : [],
    duration: apiMovie.duration || 'N/A', 
    tags: tags,
    type: type,
    region: region,
    views: 'N/A',
    isPlayed: apiMovie.user_data?.is_played || false,
    lastPlayedAt: apiMovie.user_data?.last_played_at,
    tech_specs: techSpecs
  };
};

const getDeviceId = () => {
    let id = localStorage.getItem('cyber_device_id');
    if (!id) {
        id = crypto.randomUUID();
        localStorage.setItem('cyber_device_id', id);
    }
    return id;
};

export const movieService = {
  // Updated to support country and year parameters
  getAll: async (limit = 20, page = 1, genre?: string, sort_by?: string, order?: string, country?: string, year?: string): Promise<{ items: Movie[], meta?: ApiPagination }> => {
    let url = `/api/v1/movies?page=${page}&page_size=${limit}`;
    if (genre && genre !== '全部类型') {
      url += `&genre=${encodeURIComponent(genre)}`;
    }
    if (sort_by) {
      url += `&sort_by=${encodeURIComponent(sort_by)}`;
    }
    if (order) {
      url += `&order=${encodeURIComponent(order)}`;
    }
    if (country && country !== '全部地区') {
      url += `&country=${encodeURIComponent(country)}`;
    }
    if (year && year !== '全部年份') {
      url += `&year=${encodeURIComponent(year)}`;
    }

    const data = await fetchApi<{ items: ApiMovieSimple[], pagination: ApiPagination }>(url);
    if (!data) return { items: [] };

    return {
      items: data.items.map(mapApiMovieToUi),
      meta: data.pagination
    };
  },

  getGenres: async (): Promise<Genre[]> => {
    // Fallback to filters endpoint if direct endpoint is problematic or to unify
    const data = await fetchApi<FilterDictionaries>('/api/v1/filters');
    return data?.genres || [];
  },

  // New method to get all filters (genres, years, countries) in one go
  getGlobalFilters: async (): Promise<FilterDictionaries | null> => {
    return await fetchApi<FilterDictionaries>('/api/v1/filters');
  },

  // Get Featured content (Hero Banner)
  getFeatured: async (): Promise<Movie[]> => {
    const data = await fetchApi<ApiMovieDetailed[]>('/api/v1/featured');
    if (!data) return [];
    return data.map(mapApiMovieToUi);
  },

  // Since /movies/top doesn't exist in OpenAPI, we assume using the general list 
  // Client-side sorting will be needed if backend doesn't support sort param (not in spec)
  getTop: async (type: string, limit = 15): Promise<Movie[]> => {
    const data = await fetchApi<{ items: ApiMovieSimple[] }>(`/api/v1/movies?page_size=${limit}`);
    if (!data) return [];
    // Mock sort by rating for "HOT" since API doesn't have sort param yet
    return data.items.map(mapApiMovieToUi).sort((a, b) => parseFloat(b.rating) - parseFloat(a.rating));
  },

  // Server-side search using the 'keyword' parameter from /api/v1/movies endpoint
  search: async (query: string): Promise<Movie[]> => {
    const data = await fetchApi<{ items: ApiMovieSimple[] }>(`/api/v1/movies?keyword=${encodeURIComponent(query)}&page_size=50`);
    if (!data) return [];
    return data.items.map(mapApiMovieToUi);
  },

  getDetail: async (id: string | number): Promise<Movie | null> => {
    const data = await fetchApi<ApiMovieDetailed>(`/api/v1/movies/${id}`);
    if (!data) return null;
    return mapApiMovieToUi(data);
  },

  // Implemented getRecommendations based on new OpenAPI spec
  getRecommendations: async (limit = 12, strategy: 'default' | 'latest' | 'top_rated' | 'surprise' = 'default'): Promise<Movie[]> => {
    const data = await fetchApi<ApiMovieSimple[]>(`/api/v1/recommendations?limit=${limit}&strategy=${strategy}`);
    if (!data) return [];
    return data.map(mapApiMovieToUi);
  },

  // Helper to construct stream URL
  getStreamUrl: (resourceId: string): string => {
    return `${API_BASE}/api/v1/resources/${resourceId}/stream`;
  }
};

export const userService = {
  getHistory: async (): Promise<HistoryItem[]> => {
    const data = await fetchApi<any>('/api/v1/user/history');
    if (!data) return [];

    let items: any[] = [];
    // API might return array directly OR { items: [...] } OR { data: [...] }
    if (Array.isArray(data)) {
        items = data;
    } else if (typeof data === 'object') {
        if (Array.isArray(data.items)) items = data.items;
        else if (Array.isArray(data.data)) items = data.data;
    }

    return items.map(item => {
      // Robustly handle various backend response shapes
      const movieInfo = item.movie || item; 
      // Map base movie info
      const movie = mapApiMovieToUi(movieInfo);

      const updatedAt = item.updated_at || item.created_at || new Date().toISOString();
      let dateObj = new Date(updatedAt);
      if (isNaN(dateObj.getTime())) dateObj = new Date();

      // Parse duration: prioritise history item's duration (usually seconds), fallback to movie metadata
      let duration = 0;
      if (item.duration) {
         duration = parseDuration(item.duration);
      } else {
         duration = parseDuration(movie.duration);
      }

      const progress = Number(item.progress || item.position_sec || 0);

      return {
        ...movie,
        // Keep resource_id specifically for history deletion
        resourceId: item.resource_id, 
        progress: progress,
        duration: duration, 
        time_str: dateObj.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
        date: dateObj.toLocaleDateString(),
        updated_at: updatedAt
      };
    }).sort((a, b) => new Date(b.updated_at!).getTime() - new Date(a.updated_at!).getTime());
  },

  clearHistory: async (): Promise<void> => {
    try {
      await fetch(`${API_BASE}/api/v1/user/history`, { method: 'DELETE' });
    } catch (e) { console.error(e); }
  },

  deleteHistoryItem: async (resourceId: string): Promise<void> => {
    try {
      await fetch(`${API_BASE}/api/v1/user/history/${resourceId}`, { method: 'DELETE' });
    } catch (e) { console.error(e); }
  },

  reportHistory: async (resourceId: string, positionSec: number, totalDuration: number) => {
    try {
      await fetch(`${API_BASE}/api/v1/user/history`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          resource_id: resourceId,
          position_sec: Math.floor(positionSec),
          total_duration: Math.floor(totalDuration),
          device_id: getDeviceId(),
          device_name: navigator.userAgent
        })
      });
    } catch (e) { console.error(e); }
  },

  getVault: async (): Promise<Movie[]> => {
    // Not in OpenAPI, return empty or mock
    return [];
  },

  toggleFavorite: async (movie: Movie) => {
    // Not in OpenAPI
    console.warn("Vault API not available in current spec");
  }
};

