  // This ensures LCP (Largest Contentful Paint) is as fast as possible before API returns
  const [heroMovie, setHeroMovie] = useState<Movie>(() => {
     if (movies && movies.length > 0) return movies[0];
     return FEATURED_MOVIE;
  });

  // Initialize state directly from cache if available to ensure instant render
