export const Home = ({ movies, onMovieSelect, onViewMore }: { movies: Movie[]; onMovieSelect: (m: Movie) => void; onViewMore: (id: string) => void }) => { 
  // Initial Hero state is either the first movie from prop (if available early) or the static constant
  // This ensures LCP (Largest Contentful Paint) is as fast as possible before API returns
  const [heroMovie, setHeroMovie] = useState<Movie>(() => {
     if (movies && movies.length > 0) return movies[0];
     return FEATURED_MOVIE;
  });

  // Initialize state directly from cache if available to ensure instant render
  const [categoryMovies, setCategoryMovies] = useState<Record<string, Movie[]>>(cachedCategoryData || {});
  const [recommendedMovies, setRecommendedMovies] = useState<Movie[]>([]);

  useEffect(() => {
    // 1. Fetch Featured Hero Content (Separate API for fast loading)
    const fetchHero = async () => {
        try {
            const featuredList = await movieService.getFeatured();
            if (featuredList && featuredList.length > 0) {
                setHeroMovie(featuredList[0]);
            } else if (movies && movies.length > 0) {
                // Fallback to general list if featured API returns empty
                setHeroMovie(movies[0]);
            }
        } catch (e) {
            console.error("Failed to fetch featured content", e);
        }
    };
    fetchHero();

    // 2. Fetch Recommendations
    const fetchRecs = async () => {
        try {
            const recs = await movieService.getRecommendations(10, 'default');
            setRecommendedMovies(recs);
        } catch (e) {
            console.error("Failed to fetch recommendations", e);
        }
    };
    fetchRecs();

    // 3. Fetch Categories
    // If cache exists for categories, DO NOT re-fetch. This fixes the reloading issue.
    if (cachedCategoryData) return;

    const fetchCategoryData = async () => {
      try {
        // Get live genres from API to find correct slugs via Global Filters
        const filters = await movieService.getGlobalFilters();
        const genres = Array.isArray(filters?.genres) ? filters.genres : [];

        const promises = categories.map(async (cat) => {
          // Find if we have a matching genre in the database
          const matchedGenre = genres.find(g => 
            cat.keywords.some(k => 
              g.name.toLowerCase().includes(k.toLowerCase()) || 
              g.slug.toLowerCase().includes(k.toLowerCase())
            )
          );

          // Use the slug from API, or fallback to the primary keyword (usually Chinese) if not found in list but likely exists
          const genreSlug = matchedGenre ? matchedGenre.slug : cat.keywords[1];

          try {
            const res = await movieService.getAll(10, 1, genreSlug);
            return { id: cat.id, items: res.items };
          } catch (e) {
            console.warn(`Failed to fetch genre ${genreSlug}`, e);
            return { id: cat.id, items: [] };
          }
        });

        const results = await Promise.all(promises);
        const newMap: Record<string, Movie[]> = {};
        results.forEach(r => {
          if (r.items && r.items.length > 0) {
            newMap[r.id] = r.items;
          }
        });

        // Update both State (for render) and Cache (for future visits)
        cachedCategoryData = newMap;
        setCategoryMovies(newMap);
      } catch (err) {
        console.error("Home initialization failed", err);
      }
    };
    fetchCategoryData();
  }, [movies]); // Depend on movies to update fallback if API fails

  return (
    <> 
      <div className="relative w-full h-[85vh] overflow-hidden flex items-center z-10 transition-all duration-700"> 
        <div className="absolute inset-0 bg-[#0a0a12]">
             {/* Dynamic Background Image from Featured API */}
             <div 
                className="absolute inset-0 bg-cover bg-center opacity-70 transition-opacity duration-1000"
                style={{ backgroundImage: `url('${heroMovie.backdrop_url || heroMovie.cover_url || "https://images.unsplash.com/photo-1535868463750-c78d9543614f?q=80&w=2676&auto=format&fit=crop"}')` }}
             ></div>
             {/* Gradient Overlay - Darker at bottom for text readability, but transparent top to show color */}
             <div className="absolute inset-0 bg-gradient-to-t from-[#050505] via-[#050505]/40 to-transparent"></div>
             {/* Optional: Colorful accent gradient to enhance "cyber" feel without removing image color */}
             <div className="absolute inset-0 bg-gradient-to-r from-[#050505]/80 via-transparent to-transparent opacity-80"></div>
        </div> 
        <div className="container mx-auto px-6 md:px-12 relative mt-20"> 
          <h1 className="text-6xl md:text-8xl font-black font-['Orbitron'] text-white mb-4 tracking-tighter glitch-text max-w-4xl leading-tight drop-shadow-2xl" data-text={heroMovie.title || "CYBERSTREAM"}>{heroMovie.title || "CYBERSTREAM"}</h1> 
          <p className="max-w-xl text-gray-200 text-lg mb-10 leading-relaxed font-sans border-l-2 border-primary pl-4 line-clamp-3 drop-shadow-md bg-black/30 backdrop-blur-sm p-2 rounded-r-md">{heroMovie.desc || heroMovie.overview || "Connect. Stream. Transcend."}</p> 
          <button onClick={() => onMovieSelect(heroMovie)} className="bg-white hover:bg-primary text-black px-8 py-3 rounded-sm font-['Orbitron'] font-bold flex items-center gap-2 transition-all hover:scale-105 shadow-[0_0_20px_rgba(255,255,255,0.3)] hover:shadow-[0_0_20px_var(--color-primary)]"><Play className="w-5 h-5 fill-black" /><span>START_SYSTEM</span></button> 
        </div> 
      </div> 
      <div className="relative -mt-20 pb-10 space-y-8"> 
        {/* Recommendations Section */}
        {recommendedMovies.length > 0 && (
          <CategoryRow 
            category={{
               id: 'recommendations',
               title: '为你推荐 / FOR YOU',
               icon: <Sparkles className="w-5 h-5" />,
               colorClass: 'border-accent text-accent',
               bgClass: 'bg-accent/10',
               keywords: []
            }}
            data={recommendedMovies}
            onMovieSelect={onMovieSelect}
            onViewMore={() => onViewMore('recommendations')} 
          />
        )}

        {categories.map(cat => (
          <CategoryRow 
            key={cat.id} 
            category={cat} 
            data={categoryMovies[cat.id] || []} 
            onMovieSelect={onMovieSelect} 
            onViewMore={() => onViewMore(cat.id)} 
          />
        ))} 
      </div> 
    </>
  ); 
};

