                  <button onClick={() => onMovieSelect(heroMovie)} className="w-fit bg-white hover:bg-primary text-black px-8 py-4 rounded-sm font-['Orbitron'] font-bold flex items-center gap-3 transition-all hover:scale-105 shadow-[0_0_20px_rgba(255,255,255,0.3)] hover:shadow-[0_0_20px_var(--color-primary)] group/btn">
                      <Play className="w-5 h-5 fill-black group-hover/btn:fill-black" />
